package com.tsghub;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;
import net.runelite.client.util.Text;

final class ActivityDetector
{
	static final long RECENT_MILLIS = 90_000;
	static final long SLAYER_MILLIS = 300_000;
	private static final Set<Skill> COMBAT = EnumSet.of(Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED, Skill.HITPOINTS);

	private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
	private final Map<Skill, Deque<Long>> drops = new EnumMap<>(Skill.class);
	private Skill lastSkill;
	private long lastSkillAt;
	private long lastCombatAt;
	private long lastSlayerAt;
	private long slayerTarget;
	private int slayerRemaining;
	private String slayerTask;
	private String lastBoss;
	private long lastBossAt;

	static String bossFor(String npcName)
	{
		return npcName == null ? null : TsgHubRules.get().bosses.get(Text.removeTags(npcName).trim().toLowerCase(Locale.ROOT));
	}

	void onXp(Skill skill, int value, long now)
	{
		Integer previous = xp.put(skill, value);
		if (previous == null || value <= previous) return;
		if (skill == Skill.HITPOINTS) lastCombatAt = now;
		else if (skill != Skill.SLAYER && !COMBAT.contains(skill) && training(skill, now))
		{
			lastSkill = skill;
			lastSkillAt = now;
		}
	}

	private boolean training(Skill skill, long now)
	{
		if (skill == lastSkill && now - lastSkillAt < RECENT_MILLIS) return true;
		TsgHubRules rules = TsgHubRules.get();
		Deque<Long> recent = drops.computeIfAbsent(skill, s -> new ArrayDeque<>());
		while (!recent.isEmpty() && now - recent.peekFirst() >= rules.skillingWindowMillis) recent.pollFirst();
		recent.addLast(now);
		if (recent.size() < rules.skillingDrops) return false;
		recent.clear();
		return true;
	}

	void onOpponent(String npcName, long now)
	{
		String boss = bossFor(npcName);
		if (boss == null) return;
		lastBoss = boss;
		lastBossAt = now;
	}

	void onSlayerTask(long target, int remaining, String task, long now)
	{
		if (remaining <= 0)
		{
			clearSlayer();
			return;
		}
		if (target == slayerTarget && remaining < slayerRemaining) lastSlayerAt = now;
		slayerTarget = target;
		slayerRemaining = remaining;
		slayerTask = task;
	}

	boolean needsSlayerTaskName()
	{
		return slayerRemaining > 0 && slayerTask == null;
	}

	private void clearSlayer()
	{
		lastSlayerAt = 0;
		slayerTarget = 0;
		slayerRemaining = 0;
		slayerTask = null;
	}

	void reset()
	{
		xp.clear();
		drops.clear();
		lastSkill = null;
		lastSkillAt = 0;
		lastCombatAt = 0;
		clearSlayer();
		lastBoss = null;
		lastBossAt = 0;
	}

	String activity(AreaNames.Area area, long now)
	{
		if (lastBoss != null && now - lastBossAt < RECENT_MILLIS) return "Bossing - " + lastBoss;
		if (area != null)
		{
			if (area.type == AreaNames.Type.BOSSES) return "Bossing - " + area.name;
			if (area.type == AreaNames.Type.RAIDS) return "Raiding - " + area.name;
			if (area.type == AreaNames.Type.MINIGAMES) return "Minigame - " + area.name;
		}
		boolean fighting = lastCombatAt > 0 && now - lastCombatAt < RECENT_MILLIS;
		boolean slaying = lastSlayerAt > 0 && now - lastSlayerAt < (fighting ? SLAYER_MILLIS : RECENT_MILLIS);
		if (slaying) return slayerTask == null ? "Slayer" : "Slayer - " + slayerTask;
		if (fighting) return "Combat";
		if (lastSkill != null && now - lastSkillAt < RECENT_MILLIS) return "Skilling - " + lastSkill.getName();
		return "Idle";
	}
}

package com.tsghub;

import lombok.RequiredArgsConstructor;
import net.runelite.api.coords.WorldPoint;

final class AreaNames
{
	enum Type { BOSSES, RAIDS, MINIGAMES, DUNGEONS, CITIES, REGIONS }

	@RequiredArgsConstructor
	static final class Area
	{
		final String name;
		final Type type;
	}

	private AreaNames() {}

	static Area forRegion(int region)
	{
		return TsgHubRules.get().areas.get(region);
	}

	static Area at(WorldPoint point)
	{
		Area named = forRegion(point.getRegionID());
		if (named != null && (named.type == Type.BOSSES || named.type == Type.RAIDS)) return named;
		int level = wildernessLevel(point);
		return level > 0 ? new Area("Wilderness lvl " + level, Type.REGIONS) : named;
	}

	static int wildernessLevel(WorldPoint point)
	{
		int x = point.getX();
		int y = point.getY();
		if (x < 2944 || x > 3391) return 0;
		if (y >= 3520 && y <= 3967) return (y - 3520) / 8 + 1;
		if (y >= 9920 && y <= 10367) return (y - 9920) / 8 + 1;
		return 0;
	}
}

