package com.tsghub;

import lombok.Value;
import net.runelite.api.Skill;

@Value
class PartyStatChange
{
	int s; // Skill ordinal
	int l; // Level
	int b; // Boosted Level

	void process(PartyPlayer p)
	{
		Skill skill = Skill.values()[s];
		p.getStats().getBaseLevels().put(skill, l);
		p.getStats().getBoostedLevels().put(skill, b);
	}
}

