	private static final int CARD_CLAIMS = 3;
	private final JPanel boardSummary = stack();
	private final WidthTrackingPanel tasksTab = new WidthTrackingPanel();
	private final WidthTrackingPanel scoreboardTab = new WidthTrackingPanel();
	private final WidthTrackingPanel teamTab = new WidthTrackingPanel();
	private final JCheckBox hideCompleted = new JCheckBox("Hide completed");

	JsonObject boardEvent;
	String boardDisplayName = "";
	TsgHubBoardView(TsgHubPlugin plugin, TsgHubSidebarPanel shell)
	{
		this.plugin = plugin;
		this.shell = shell;
		plain(hideCompleted, MUTED).setFont(smallFont());
		hideCompleted.setSelected("true".equals(plugin.session().get(HIDE_COMPLETED)));
		hideCompleted.addActionListener(e -> {
			plugin.session().set(HIDE_COMPLETED, hideCompleted.isSelected() ? "true" : "");
			renderTasks();
		});
	}

	JPanel buildBoard()
	{
		JPanel board = panel(new BorderLayout(0, 6));
		JPanel display = panel(new BorderLayout());
		MaterialTabGroup tabs = new MaterialTabGroup(display);
		tabs.setLayout(new GridLayout(1, 3, 4, 0));
		tabs.setOpaque(false);
		MaterialTab tasks = themedTab("Tasks", tabs, scroll(tasksTab));
		tabs.addTab(tasks);
		tabs.addTab(themedTab("Scores", tabs, scroll(scoreboardTab)));
		tabs.addTab(themedTab("Team", tabs, scroll(teamTab)));
		tabs.select(tasks);

		JPanel north = stack();
		north.add(boardSummary);
		north.add(gap(GAP_M));
		north.add(fitHeight(tabs));
		board.add(north, BorderLayout.NORTH);
		board.add(display, BorderLayout.CENTER);
		return board;
	}

	void closeBoard()
	{
		if (shell.view == View.BOARD || shell.view == View.SIGNUP) shell.eventsView.showEventList();
	}

	void showBoard(JsonObject event, String displayName, boolean open)
	{
		// Background refreshes must not pull the user off another screen.
		if (!open && shell.view != View.BOARD && shell.view != View.SIGNUP) return;
		String name = displayName == null ? "" : displayName;
		shell.refresh.setToolTipText("Refresh (updated " + LocalTime.now().format(TsgHubSidebarPanel.TIME) + ")");
		if (!open && event.equals(boardEvent) && name.equals(boardDisplayName)) return;
		boardEvent = event;
		boardDisplayName = name;
		shell.setView(View.BOARD);
		renderBoard();
	}

	private void renderBoard()
	{
		JsonObject event = boardEvent;
		shell.setEventHeader(event, true, true);
		renderSummary();
		renderTasks();
		renderScoreboard();
		renderTeam();
	}

	private String ownTeamId()
	{
		return teamIdFor(boardEvent, boardDisplayName);
	}

	private void renderSummary()
	{
		boardSummary.removeAll();
		String teamId = ownTeamId();
		List<JsonObject> ranked = rankedTeams(boardEvent);
		JsonObject score = scoreFor(array(boardEvent, "teamScores"), teamId);
		int totalTasks = array(boardEvent, "tasks").size();
		int completed = integer(score, "completedTasks", 0);
		String teamName = "No team";
		int rank = 0;
		for (int i = 0; i < ranked.size(); i++)
		{
			if (str(ranked.get(i), "id").equals(teamId))
			{
				teamName = str(ranked.get(i), "name");
				rank = i + 1;
			}
		}

		JPanel card = card();
		JPanel row = row();
		row.add(label(html(escape(teamName), CARD_TITLE_W), TEXT, boldFont()), BorderLayout.CENTER);
		if (rank > 0 && !bool(boardEvent, "hideScores"))
		{
			JLabel rankLabel = label("#" + rank + " of " + ranked.size(), rank == 1 ? ACCENT : MUTED, boldFont());
			row.add(rankLabel, BorderLayout.EAST);
		}
		card.add(row, BorderLayout.NORTH);
		ProgressBar bar = progressBar(completed, Math.max(totalTasks, 1));
		bar.setLeftLabel(integer(score, "points", 0) + " pts");
		bar.setRightLabel(completed + "/" + totalTasks + " tasks");
		card.add(bar, BorderLayout.CENTER);
		JPanel prizes = prizeRow(boardEvent, smallFont());
		if (prizes != null)
		{
			prizes.setBorder(BorderFactory.createEmptyBorder(5, 0, 0, 0));
			card.add(prizes, BorderLayout.SOUTH);
		}
		boardSummary.add(fitHeight(card));
		refresh(boardSummary);
	}

	private void renderTasks()
	{
		if (boardEvent == null) return;
		tasksTab.removeAll();
		JsonArray tasks = array(boardEvent, "tasks");
		JsonObject score = scoreFor(array(boardEvent, "teamScores"), ownTeamId());
		JsonArray progressRows = array(score, "tasks");

		List<JsonObject> open = new ArrayList<>();
		List<JsonObject> done = new ArrayList<>();
		for (JsonObject task : objects(tasks))
		{
			boolean completed = bool(progressFor(progressRows, str(task, "id")), "completed");
			(completed ? done : open).add(task);
		}

		JPanel controls = panel(new BorderLayout());
		controls.add(hideCompleted, BorderLayout.WEST);
		JLabel left = caption(open.size() + " left");
		left.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 4));
		controls.add(left, BorderLayout.EAST);
		tasksTab.add(fitHeight(controls));
		tasksTab.add(gap(GAP_S));

		if (tasks.size() == 0)
		{
			tasksTab.add(shell.errorPanel("No tasks yet", "The admins haven't added tasks to this event yet."));
		}
		else if (open.isEmpty() && hideCompleted.isSelected())
		{
			tasksTab.add(shell.errorPanel("All done!", "Your team has completed every task."));
		}
		for (JsonObject task : open) addTaskCard(task, progressFor(progressRows, str(task, "id")));
		if (!hideCompleted.isSelected())
		{
			for (JsonObject task : done) addTaskCard(task, progressFor(progressRows, str(task, "id")));
		}
		refresh(tasksTab);
	}

	private void addTaskCard(JsonObject task, JsonObject progress)
	{
		addCard(tasksTab, taskCard(task, progress));
	}

	private JPanel taskCard(JsonObject task, JsonObject progress)
	{
		String taskId = str(task, "id");
		boolean completed = bool(progress, "completed");
		boolean individual = "individual".equals(str(task, "scope"));
		boolean solo = "solo".equals(str(task, "scope"));

		JPanel card = card();
		JLabel name = shrinkable(label(str(task, "title"), completed ? MUTED : TEXT, boldFont()));
		name.putClientProperty("html.disable", Boolean.TRUE);
		if (completed) name.setIcon(icon("check", SUCCESS));
		JLabel points = label(integer(task, "points", 1) + " pts", completed ? MUTED : ACCENT, smallFont());
		card.add(row(name, north(points)), BorderLayout.NORTH);

		JPanel body = stack();
		String description = str(task, "description").trim();
		if (!description.isEmpty() && !completed) body.add(TsgHubSidebarPanel.cardNote(description));

		int value = integer(progress, "progress", 0);
		int target = Math.max(1, integer(progress, "target", 1));
		JsonObject mine = (individual || solo) && progress.has("mine") ? object(progress, "mine") : null;
		if (completed)
		{
			String line = str(progress, "completedLine");
			if (!line.isEmpty() && !"Completed".equals(line)) body.add(label(line, SUCCESS, smallFont()));
		}
		else if (addSetProgress(body, individual || solo ? mine : progress, individual || solo))
		{
			if (individual) body.add(teammatesLine(mine, value, target));
			if (solo) addSoloLeader(body, progress);
		}
		else if (solo)
		{
			int have = mine == null ? 0 : integer(mine, "progress", 0);
			if (target > 1) addBar(body, have, target, "You: " + have + "/" + target);
			addSoloLeader(body, progress);
		}
		else if (individual)
		{
			int have = mine == null ? 0 : integer(mine, "progress", 0);
			int need = mine == null ? 1 : integer(mine, "target", 1);
			if (mine != null && need > 1 && !bool(mine, "completed")) addBar(body, have, need, "You: " + have + "/" + need);
			body.add(teammatesLine(mine, value, target));
		}
		else if (target > 1) addBar(body, value, target, value + " / " + target);
		if (!individual && !solo && (!progress.has("sets") || completed))
		{
			String amounts = contributorsHtml(progress, " · ", CARD_CONTRIBUTORS, boardDisplayName);
			if (!amounts.isEmpty()) body.add(TsgHubSidebarPanel.cardNoteHtml(amounts));
		}
		List<JsonObject> claims = completed ? new ArrayList<>() : TsgHubTileClaims.forTask(boardEvent, taskId);
		if (!claims.isEmpty()) body.add(TsgHubSidebarPanel.cardNoteHtml("Claimed: " + claimNames(claims, CARD_CLAIMS)));
		addLineSpacing(body);
		addScopeIcon(body, solo, individual);
		card.add(body, BorderLayout.CENTER);
		JsonObject myClaim = completed ? null : TsgHubTileClaims.mine(boardEvent, taskId);
		if (myClaim != null) highlightSelf(card);
		if (TsgHubTileClaims.claimable(boardEvent, ownTeamId(), progress)) addClaimMenu(card, taskId, str(task, "title"), myClaim);
		lazyTooltip(card, () -> taskTooltip(task, progress, truncated(name)));
		return fitHeight(card);
	}

	private String claimName(JsonObject claim)
	{
		String name = escape(str(claim, "displayName"));
		return bool(claim, "mine") ? selfName(name) : nameHtml(str(claim, "displayName"), boardDisplayName);
	}

	private String claimNames(List<JsonObject> claims, int max)
	{
		List<String> names = new ArrayList<>();
		for (int i = 0; i < Math.min(max, claims.size()); i++) names.add(claimName(claims.get(i)));
		if (claims.size() > max) names.add("+" + (claims.size() - max));
		return String.join(", ", names);
	}

	private void addClaimMenu(JPanel card, String taskId, String title, JsonObject myClaim)
	{
		JPopupMenu menu = new JPopupMenu();
		if (myClaim == null)
		{
			JMenuItem claim = new JMenuItem("Claim tile");
			claim.addActionListener(e -> promptClaim(taskId, title, null));
			menu.add(claim);
		}
		else
		{
			JMenuItem note = new JMenuItem("Change note");
			note.addActionListener(e -> promptClaim(taskId, title, myClaim));
			menu.add(note);
			JMenuItem drop = new JMenuItem("Drop claim");
			drop.addActionListener(e -> sendClaim(taskId, null));
			menu.add(drop);
		}
		card.setComponentPopupMenu(menu);
		eachDeep(card, c -> { if (c != card && c instanceof JComponent) ((JComponent) c).setInheritsPopupMenu(true); });
	}

	private void promptClaim(String taskId, String title, JsonObject current)
	{
		String previous = current == null ? "" : str(current, "note");
		Object input = JOptionPane.showInputDialog(shell, "Note for your team (optional, up to " + TsgHubTileClaims.MAX_NOTE_LENGTH + " characters)",
			current == null ? "Claim " + title : "Change note", JOptionPane.PLAIN_MESSAGE, null, null, previous);
		if (input == null) return;
		String note = TsgHubTileClaims.cleanNote(input.toString());
		if (note == null)
		{
			shell.setStatus("Keep the note to " + TsgHubTileClaims.MAX_NOTE_LENGTH + " characters.", Tone.ERROR);
			return;
		}
		if (current != null && note.equals(previous)) return;
		sendClaim(taskId, note);
	}

	private void sendClaim(String taskId, String note)
	{
		if (boardEvent == null) return;
		String eventId = str(boardEvent, "id");
		boolean sent = note == null ? plugin.sessions().dropTileClaim(eventId, taskId) : plugin.sessions().claimTile(eventId, taskId, note);
		if (!sent) return;
		boardEvent = TsgHubTileClaims.withClaim(boardEvent, taskId, ownTeamId(), boardDisplayName, note);
		renderTasks();
	}

	private static void addScopeIcon(JPanel body, boolean solo, boolean individual)
	{
		JLabel scope = new JLabel(icon("scope" + (solo ? 1 : individual ? 3 : 2), MUTED));
		scope.setToolTipText(solo ? "Solo: one player completes it" : individual ? "Everyone: each teammate completes it" : "Team: progress is shared");
		JPanel corner = panel(new BorderLayout());
		corner.add(scope, BorderLayout.SOUTH);
		int last = body.getComponentCount() - 1;
		Component line = last >= 0 && body.getComponent(last) instanceof JLabel ? body.getComponent(last) : new JLabel();
		if (line.getParent() == body) body.remove(last);
		body.add(fitHeight(row(line, corner)));
	}

	private JLabel teammatesLine(JsonObject mine, int value, int target)
	{
		String count = value + " of " + target + " teammates done";
		if (mine == null || !bool(mine, "completed")) return caption(count);
		return label(html("<font color='" + toHexColor(SUCCESS) + "'>You're done</font> · " + count, TsgHubSidebarPanel.CARD_TEXT_W), MUTED, smallFont());
	}

	private boolean addSetProgress(JPanel body, JsonObject source, boolean mine)
	{
		if (source == null || !source.has("sets")) return false;
		if (bool(source, "completed")) return true;
		List<JsonObject> sets = objects(array(source, "sets"));
		List<JsonObject> shown = new ArrayList<>();
		for (JsonObject set : sets) if (integer(set, "have", 0) > 0) shown.add(set);
		if (shown.isEmpty() && !sets.isEmpty()) shown.add(sets.get(0));
		for (JsonObject set : shown)
		{
			int have = integer(set, "have", 0);
			int target = integer(set, "target", 1);
			ProgressBar bar = progressBar(have, target);
			bar.setCenterLabel((mine ? "You: " : "") + str(set, "name") + " " + have + "/" + target);
			body.add(gap(GAP_S));
			body.add(bar);
			body.add(gap(GAP_XS));
			List<String> needed = strings(array(set, "needed"));
			if (!needed.isEmpty()) body.add(TsgHubSidebarPanel.cardNote("Need: " + String.join(", ", needed)));
		}
		int notStarted = sets.size() - shown.size();
		if (notStarted > 0) body.add(caption("+" + notStarted + (notStarted == 1 ? " more set" : " more sets") + " not started"));
		return true;
	}

	private static void addLineSpacing(JPanel body)
	{
		Component[] parts = body.getComponents();
		body.removeAll();
		int first = 0;
		while (first < parts.length && parts[first] instanceof Box.Filler) first++;
		for (int i = first; i < parts.length; i++)
		{
			body.add(parts[i]);
			boolean next = i + 1 < parts.length;
			if (next && parts[i] instanceof JLabel && parts[i + 1] instanceof JLabel) body.add(gap(GAP_XS));
		}
	}

	private String taskTooltip(JsonObject task, JsonObject progress, boolean titleCut)
	{
		boolean completed = bool(progress, "completed");
		boolean individual = "individual".equals(str(task, "scope"));
		boolean solo = "solo".equals(str(task, "scope"));
		String head = titleCut ? "<b>" + escape(str(task, "title")) + "</b>" : "";
		String description = str(task, "description").trim();
		if (completed && !description.isEmpty()) head += (head.isEmpty() ? "" : "<br>") + escape(description).replace("\n", "<br>");

		String sections = "";
		if (!completed && !individual && !solo) sections += setSections(progress, head.isEmpty());
		if (individual || solo) sections += memberSections(progress, solo, head.isEmpty());
		else if (sections.isEmpty() && array(progress, "contributors").size() > CARD_CONTRIBUTORS)
		{
			sections += tipSection(head.isEmpty(), tipLine(MUTED, "<b>CONTRIBUTORS</b>")) + tipCard(CARD_HOVER, contributorsHtml(progress, "<br>", 50, boardDisplayName));
		}
		if (!completed) sections += claimSection(str(task, "id"), head.isEmpty() && sections.isEmpty());
		if (head.isEmpty() && sections.isEmpty()) return null;
		return html("<div style='padding:2px'>" + head + sections + "</div>", 240);
	}

	private String claimSection(String taskId, boolean first)
	{
		List<JsonObject> claims = TsgHubTileClaims.forTask(boardEvent, taskId);
		if (claims.isEmpty()) return "";
		List<String> lines = new ArrayList<>();
		for (JsonObject claim : claims)
		{
			String note = str(claim, "note");
			lines.add(claimName(claim) + (note.isEmpty() ? "" : "<br>" + tipLine(MUTED, escape(note))));
		}
		return tipSection(first, tipLine(MUTED, "<b>CLAIMED</b> " + claims.size())) + tipCard(ACCENT, String.join("<br>", lines));
	}

	private String setSections(JsonObject progress, boolean first)
	{
		StringBuilder out = new StringBuilder();
		for (JsonObject set : objects(array(progress, "sets")))
		{
			if (integer(set, "have", 0) == 0) continue;
			List<String> found = new ArrayList<>();
			for (JsonObject piece : objects(array(set, "found")))
			{
				String by = str(piece, "by");
				found.add(escape(str(piece, "piece")) + (by.isEmpty() ? "" : " (" + nameHtml(by, boardDisplayName) + ")"));
			}
			if (!found.isEmpty()) out.append(tipCard(ACCENT, "<b>" + escape(str(set, "name")) + "</b><br>" + String.join(", ", found)));
		}
		return out.length() == 0 ? "" : tipSection(first, tipLine(MUTED, "<b>FOUND</b>")) + out;
	}

	private String memberSections(JsonObject progress, boolean solo, boolean first)
	{
		List<JsonObject> members = objects(array(progress, "members"));
		if (members.isEmpty()) return "";
		members.sort((a, b) -> integer(b, "progress", 0) - integer(a, "progress", 0));
		List<String> done = new ArrayList<>();
		List<String> waiting = new ArrayList<>();
		for (JsonObject member : members)
		{
			String name = nameHtml(str(member, "displayName"), boardDisplayName);
			int have = integer(member, "progress", 0);
			int need = integer(member, "target", 1);
			if (solo) waiting.add(name + " " + tipLine(MUTED, have + "/" + need));
			else if (bool(member, "completed")) done.add(name);
			else waiting.add(need > 1 ? name + " " + tipLine(MUTED, have + "/" + need) : name);
		}
		if (solo) return tipSection(first, tipLine(MUTED, "<b>STANDINGS</b>")) + tipCard(CARD_HOVER, String.join("<br>", waiting));
		String out = "";
		if (!done.isEmpty()) out += tipSection(first, tipLine(SUCCESS, "<b>DONE</b> ") + tipLine(MUTED, String.valueOf(done.size()))) + tipCard(SUCCESS, String.join("<br>", done));
		if (!waiting.isEmpty()) out += tipSection(first && done.isEmpty(), tipLine(MUTED, "<b>STILL NEED</b> " + waiting.size())) + tipCard(CARD_HOVER, String.join("<br>", waiting));
		return out;
	}

	private void addSoloLeader(JPanel body, JsonObject progress)
	{
		String leader = str(progress, "leader");
		if (leader.isEmpty()) return;
		body.add(caption("Leader: " + leader + " (" + integer(progress, "progress", 0) + "/" + integer(progress, "target", 1) + ")"));
	}

	private static String contributorsHtml(JsonObject progress, String separator, int max, String self)
	{
		JsonArray contributors = array(progress, "contributors");
		if (contributors.size() == 0) return "";
		List<String> parts = new ArrayList<>();
		for (int i = 0; i < Math.min(max, contributors.size()); i++)
		{
			JsonObject entry = contributors.get(i).getAsJsonObject();
			parts.add(nameHtml(str(entry, "displayName"), self) + " " + integer(entry, "amount", 1));
		}
		if (contributors.size() > max) parts.add("+" + (contributors.size() - max));
		return String.join(separator, parts);
	}

	private void renderScoreboard()
	{
		scoreboardTab.removeAll();
		if (bool(boardEvent, "hideScores"))
		{
			renderHiddenScoreboard();
			return;
		}
		List<JsonObject> ranked = rankedTeams(boardEvent);
		JsonArray scores = array(boardEvent, "teamScores");
		int totalTasks = array(boardEvent, "tasks").size();
		String ownTeam = ownTeamId();
		if (ranked.isEmpty()) scoreboardTab.add(shell.errorPanel("No teams yet", "Teams appear here once an admin adds them."));
		for (int i = 0; i < ranked.size(); i++)
		{
			JsonObject team = ranked.get(i);
			JsonObject score = scoreFor(scores, str(team, "id"));
			boolean mine = str(team, "id").equals(ownTeam);
			JPanel card = card();
			card.setLayout(new BorderLayout(8, 0));
			if (mine) highlightSelf(card);
			card.add(rankLabel(i + 1, boldFont(), 14), BorderLayout.WEST);
			JPanel text = stack();
			text.add(wrapped(str(team, "name"), TEXT, boldFont(), 120));
			text.add(caption(integer(score, "completedTasks", 0) + "/" + totalTasks + " tasks"));
			card.add(text, BorderLayout.CENTER);
			card.add(label(integer(score, "points", 0) + " pts", i == 0 ? ACCENT : TEXT, boldFont()), BorderLayout.EAST);
			addCard(scoreboardTab, fitHeight(card));
		}
		refresh(scoreboardTab);
	}

	private void renderHiddenScoreboard()
	{
		scoreboardTab.add(shell.errorPanel("Scores are hidden", "The admins are keeping scores secret for now. Your own team's progress is on the Tasks tab."));
		List<JsonObject> teams = objects(array(boardEvent, "teams"));
		teams.sort((a, b) -> str(a, "name").compareToIgnoreCase(str(b, "name")));
		String ownTeam = ownTeamId();
		for (JsonObject team : teams)
		{
			boolean mine = str(team, "id").equals(ownTeam);
			JPanel card = card();
			if (mine) highlightSelf(card);
			card.add(wrapped(str(team, "name"), TEXT, plainFont(), TsgHubSidebarPanel.CARD_TEXT_W), BorderLayout.CENTER);
			addCard(scoreboardTab, fitHeight(card));
		}
		refresh(scoreboardTab);
	}

	private void renderTeam()
	{
		teamTab.removeAll();
		String ownTeam = ownTeamId();
		List<String> teammates = new ArrayList<>();
		for (JsonObject member : objects(array(boardEvent, "members")))
		{
			if (!ownTeam.isEmpty() && str(member, "teamId").equals(ownTeam)) teammates.add(str(member, "displayName"));
		}
		teammates.sort(String.CASE_INSENSITIVE_ORDER);
		teamTab.add(caption(teammates.size() == 1 ? "1 member" : teammates.size() + " members"));
		teamTab.add(gap(GAP_S));
		for (String name : teammates)
		{
			JPanel row = card();
			if (samePlayer(name, boardDisplayName)) highlightSelf(row);
			row.add(wrapped(name, TEXT, plainFont(), TsgHubSidebarPanel.CARD_TEXT_W), BorderLayout.CENTER);
			addCard(teamTab, fitHeight(row));
		}
		teamTab.add(gap(GAP_L));
		JButton leave = onClick(dangerButton("Disconnect from event"), () -> confirmLeave());
		teamTab.add(fitHeight(leave));
		teamTab.add(gap(GAP_S));
		teamTab.add(TsgHubSidebarPanel.hint("Stops tracking on this device. Your team keeps its progress and you can rejoin with the same code."));
		refresh(teamTab);
	}

	private void confirmLeave()
	{
		if (boardEvent == null) return;
		if (confirm(shell, "Disconnect from event", "Stop tracking \"" + eventName(boardEvent) + "\" on this device?\nYour team keeps its progress and you can rejoin with your team code.", "Disconnect", true))
			plugin.sessions().leaveEvent(str(boardEvent, "id"));
	}

	private void addBar(JPanel body, int value, int max, String label)
	{
		ProgressBar bar = progressBar(value, max);
		bar.setCenterLabel(label);
		body.add(gap(GAP_S));
		body.add(bar);
		body.add(gap(GAP_S));
	}
}

package com.tsghub;

import static com.tsghub.TsgHubSession.EVENT_ID;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.tsghub.TsgHubUi.Tone;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import lombok.RequiredArgsConstructor;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

@RequiredArgsConstructor
final class TsgHubChat
{
	private final TsgHubPlugin plugin;
	private final TsgHubConfig config;
	private final ConfigManager configManager;
	private final ChatMessageManager chatMessageManager;
	private final Set<String> localMessages = ConcurrentHashMap.newKeySet();
	private volatile String notifiedUpdate = "";
	private volatile boolean mapNoticeChecked;

	boolean isOwnEcho(String message)
	{
		return localMessages.remove(Text.removeTags(message));
	}

	void onLoggedOut()
	{
		mapNoticeChecked = false;
	}

	void reset()
	{
		localMessages.clear();
		notifiedUpdate = "";
		mapNoticeChecked = false;
	}

	void reply(JsonObject message)
	{
		String eventId = TsgHubJson.str(message, "eventId");
		switch (TsgHubJson.str(message, "type"))
		{
			case "progress":
				try
				{
					long gained = Long.parseLong(TsgHubJson.str(message, "gained"));
					String rank = TsgHubJson.str(message, "rank");
					Long parsedRank = rank.isEmpty() ? null : Long.parseLong(rank);
					plugin.ui(s -> s.competitionView.competitionProgress(eventId, gained, parsedRank));
				}
				catch (NumberFormatException ignored) { /* Malformed progress waits for the next report. */ }
				break;
			case "claimed":
				progress(TsgHubJson.str(message, "taskTitle"), TsgHubJson.str(message, "progress"), TsgHubJson.str(message, "complete"));
				if (!plugin.live() && eventId.equals(plugin.session().get(EVENT_ID))) plugin.sessions().refreshBoard();
				break;
			case "notice":
				String text = TsgHubJson.str(message, "text");
				if (!text.isEmpty()) plugin.memberStatus(text, "error".equals(TsgHubJson.str(message, "tone")) ? Tone.ERROR : Tone.INFO);
				break;
			default:
		}
	}

	boolean notifications(JsonArray notifications)
	{
		if (notifications == null) return false;
		for (JsonObject notification : TsgHubJson.objects(notifications))
		{
			if (!"task-completed".equals(TsgHubJson.str(notification, "type"))) continue;
			local(new ChatMessageBuilder()
				.append(ChatColorType.NORMAL).append(TsgHubJson.str(notification, "actorName") + " completed ")
				.append(ChatColorType.HIGHLIGHT).append(TsgHubJson.str(notification, "taskTitle"))
				.append(ChatColorType.NORMAL).append(" for " + TsgHubJson.str(notification, "teamName") + "!"));
		}
		return notifications.size() > 0;
	}

	private void progress(String title, String count, String complete)
	{
		if (title.isEmpty() || count.isEmpty()) return;
		ChatMessageBuilder message = new ChatMessageBuilder();
		if (!complete.isEmpty())
		{
			message.append(TsgHubTheme.CHAT_SUCCESS, "task".equals(complete) ? "Task complete: " : "Your part is done: ")
				.append(ChatColorType.HIGHLIGHT).append(title)
				.append(ChatColorType.NORMAL).append(" (" + count + ")");
		}
		else message.append(ChatColorType.HIGHLIGHT).append(title).append(ChatColorType.NORMAL).append(": " + count);
		local(message);
	}

	void announce(String text)
	{
		if (!config.eventAnnouncements()) return;
		clan("Event", new ChatMessageBuilder().append(ChatColorType.HIGHLIGHT).append(Text.escapeJagex(text)));
	}

	void clanAnnouncement(String text)
	{
		if (!config.clanAnnouncements()) return;
		clan("Announcement", new ChatMessageBuilder().append(ChatColorType.HIGHLIGHT).append(Text.escapeJagex(text)));
	}

	void updateAvailable(String version)
	{
		if (version.equals(notifiedUpdate)) return;
		notifiedUpdate = version;
		plugin.ui(s -> s.homeView.setUpdate(version));
		local(new ChatMessageBuilder().append(ChatColorType.HIGHLIGHT).append("TSG Hub " + Text.escapeJagex(version) + " is available. Restart RuneLite to update."));
	}

	void mapNotice()
	{
		if (mapNoticeChecked) return;
		mapNoticeChecked = true;
		if (config.mapNoticeShown()) return;
		configManager.setConfiguration("tsghub", "mapNoticeShown", true);
		if (plugin.locationSharingEnabled()) local(new ChatMessageBuilder().append(ChatColorType.HIGHLIGHT).append("Your position now shows on clanmates' world maps. Turn off Share location and activity to stop."));
	}

	private void local(ChatMessageBuilder body)
	{
		String message = new ChatMessageBuilder().append(config.chatColor(), "[TSG Hub] ").build() + body.build();
		chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.GAMEMESSAGE).runeLiteFormattedMessage(message).build());
	}

	private void clan(String tag, ChatMessageBuilder body)
	{
		TsgHubClan clan = plugin.clan();
		if (!clan.isHubClan())
		{
			local(body);
			return;
		}
		String message = new ChatMessageBuilder().append(config.chatColor(), "[" + tag + "] ").build() + body.build().replace("<colHIGHLIGHT>", ColorUtil.colorTag(config.chatColor()));
		localMessages.add(Text.removeTags(message));
		chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.CLAN_MESSAGE).sender(clan.name()).runeLiteFormattedMessage(message).build());
	}
}

package com.tsghub;

import com.google.gson.JsonObject;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanSettings;

@RequiredArgsConstructor
class TsgHubClan
{
	private static final int CHECK_TICKS = 50;

	private final Client client;
	private final String hubName;
	private volatile String clanName = "";
	private volatile String playerName = "";
	private volatile int rank = -1;
	private volatile boolean inClanChat;
	private volatile int checkTicks;

	String name() { return clanName; }
	String playerName() { return playerName; }
	int rank() { return rank; }
	boolean inClanChat() { return inClanChat; }
	String hubName() { return hubName; }

	boolean isHubClan()
	{
		return PlayerNames.samePlayer(clanName, hubName);
	}

	boolean pending()
	{
		return clanName.isEmpty() && checkTicks > 0;
	}

	void loggedIn()
	{
		if (clanName.isEmpty()) checkTicks = CHECK_TICKS;
	}

	boolean tick()
	{
		if (checkTicks <= 0) return false;
		checkTicks--;
		if (client.getClanSettings() != null) checkTicks = 0;
		return checkTicks == 0;
	}

	void detect()
	{
		ClanSettings settings = client.getClanSettings();
		String player = client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null ? "" : client.getLocalPlayer().getName();
		playerName = player;
		String name = settings == null ? "" : settings.getName();
		clanName = name == null ? "" : name.trim();
		if (!clanName.isEmpty()) checkTicks = 0;
		int detected = -1;
		if (settings != null && !player.isEmpty())
		{
			ClanMember member = settings.findMember(player);
			if (member != null && member.getRank() != null) detected = member.getRank().getRank();
		}
		rank = detected;
		ClanChannel channel = client.getClanChannel();
		inClanChat = channel != null && channel.getName() != null && channel.getName().trim().equalsIgnoreCase(clanName);
	}

	void reset()
	{
		playerName = "";
		clanName = "";
		rank = -1;
		inClanChat = false;
		checkTicks = 0;
	}

	String accountHash()
	{
		long hash = client.getAccountHash();
		return hash == -1 ? "" : Long.toString(hash);
	}

	void addAccountHash(JsonObject body)
	{
		String hash = accountHash();
		if (!hash.isEmpty()) body.addProperty("accountHash", hash);
	}

	JsonObject memberBody(String displayName)
	{
		JsonObject body = new JsonObject();
		body.addProperty("displayName", displayName);
		body.addProperty("clanName", clanName);
		body.addProperty("clanRank", rank);
		addAccountHash(body);
		return body;
	}
}

package com.tsghub;

import com.google.gson.JsonObject;
import java.util.ArrayDeque;
import java.util.Collections;
import java.util.Deque;
import java.util.EnumSet;
import java.util.IdentityHashMap;
import java.util.Set;
import java.util.function.Consumer;
import lombok.RequiredArgsConstructor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

@RequiredArgsConstructor
final class TsgHubCoffer
{
	private static final int FIRST_READ_TICKS = 3;
	private static final int READ_EVERY_TICKS = 2;
	private static final Set<ChatMessageType> PLAYER_CHAT = EnumSet.of(ChatMessageType.PUBLICCHAT, ChatMessageType.MODCHAT,
		ChatMessageType.AUTOTYPER, ChatMessageType.MODAUTOTYPER, ChatMessageType.PRIVATECHAT, ChatMessageType.MODPRIVATECHAT,
		ChatMessageType.PRIVATECHATOUT, ChatMessageType.FRIENDSCHAT, ChatMessageType.CLAN_CHAT, ChatMessageType.CLAN_GUEST_CHAT,
		ChatMessageType.CLAN_GIM_CHAT);

	private final TsgHubPlugin plugin;
	private final Client client;
	private final Consumer<JsonObject> report;
	private final TsgHubCofferWatch watch = new TsgHubCofferWatch();
	private boolean open;
	private int openTicks;

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.CLANS_STORAGE_MAIN) reset(true);
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.CLANS_STORAGE_MAIN) reset(false);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN) reset(false);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!open || event.getMessage() == null || PLAYER_CHAT.contains(event.getType())) return;
		String sender = event.getName() == null ? "" : Text.removeTags(event.getName()).trim();
		String line = Text.removeTags(event.getMessage()).trim();
		watch.chat(sender.isEmpty() ? line : sender + " " + line, selfName(), System.currentTimeMillis());
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (!open) return;
		if (!plugin.sharingInClan())
		{
			openTicks = 0;
			watch.reset();
			return;
		}
		openTicks++;
		if (openTicks < FIRST_READ_TICKS || (openTicks - FIRST_READ_TICKS) % READ_EVERY_TICKS != 0) return;
		TsgHubCofferWatch.Change change = watch.observe(readCoins(), System.currentTimeMillis());
		if (change != null) send(change);
	}

	private void reset(boolean opened)
	{
		open = opened;
		openTicks = 0;
		watch.reset();
	}

	private long readCoins()
	{
		Widget root = client.getWidget(InterfaceID.ClansStorageMain.ITEMS);
		if (root == null || root.isHidden()) return -1;
		return coins(root);
	}

	static long coins(Widget root)
	{
		Set<Widget> seen = Collections.newSetFromMap(new IdentityHashMap<>());
		Deque<Widget> queue = new ArrayDeque<>();
		queue.add(root);
		long total = 0;
		while (!queue.isEmpty())
		{
			Widget widget = queue.poll();
			if (!seen.add(widget)) continue;
			if (widget.getItemId() == ItemID.COINS) total += Math.max(0, widget.getItemQuantity());
			for (Widget[] children : new Widget[][]{widget.getChildren(), widget.getDynamicChildren(), widget.getStaticChildren(), widget.getNestedChildren()})
			{
				if (children == null) continue;
				for (Widget child : children) if (child != null) queue.add(child);
			}
		}
		return total;
	}

	private String selfName()
	{
		Player self = client.getLocalPlayer();
		return self == null || self.getName() == null ? "" : Text.toJagexName(self.getName());
	}

	private void send(TsgHubCofferWatch.Change change)
	{
		long hash = client.getAccountHash();
		String name = plugin.clan().playerName().isEmpty() ? selfName() : plugin.clan().playerName();
		if (hash == -1 || name.isEmpty()) return;
		JsonObject body = new JsonObject();
		body.addProperty("clanName", plugin.clan().name());
		body.addProperty("displayName", name);
		body.addProperty("accountHash", Long.toString(hash));
		body.addProperty("kind", change.kind.wire());
		body.addProperty("before", change.before);
		body.addProperty("after", change.after);
		body.addProperty("confirmed", change.confirmed);
		report.accept(body);
	}
}

package com.tsghub;

import java.util.Locale;

final class TsgHubCofferWatch
{
	static final long CHAT_WINDOW_MILLIS = 15_000;

	enum Kind
	{
		SNAPSHOT, DEPOSIT, WITHDRAWAL;

		String wire()
		{
			return name().toLowerCase(Locale.ROOT);
		}
	}

	static final class Change
	{
		final Kind kind;
		final long before;
		final long after;
		final boolean confirmed;

		Change(Kind kind, long before, long after, boolean confirmed)
		{
			this.kind = kind;
			this.before = before;
			this.after = after;
			this.confirmed = confirmed;
		}
	}

	private long balance = -1;
	private Kind chatKind;
	private long chatAt;

	void reset()
	{
		balance = -1;
		chatKind = null;
		chatAt = 0;
	}

	void chat(String line, String self, long now)
	{
		Kind kind = chatKind(line, self);
		if (kind == null) return;
		chatKind = kind;
		chatAt = now;
	}

	Change observe(long coins, long now)
	{
		if (coins < 0) return null;
		if (balance < 0)
		{
			balance = coins;
			return new Change(Kind.SNAPSHOT, coins, coins, false);
		}
		if (coins == balance) return null;
		Kind kind = coins > balance ? Kind.DEPOSIT : Kind.WITHDRAWAL;
		boolean confirmed = chatKind == kind && now >= chatAt && now - chatAt <= CHAT_WINDOW_MILLIS;
		Change change = new Change(kind, balance, coins, confirmed);
		balance = coins;
		chatKind = null;
		chatAt = 0;
		return change;
	}

	static Kind chatKind(String line, String self)
	{
		if (line == null) return null;
		String text = PlayerNames.key(line);
		if (!text.contains("coffer")) return null;
		String name = PlayerNames.key(self);
		boolean mine = text.startsWith("you ") || text.startsWith("you've ") || (!name.isEmpty() && text.startsWith(name + " "));
		if (!mine) return null;
		if (text.contains("deposited") || text.contains("donated")) return Kind.DEPOSIT;
		if (text.contains("withdrew") || text.contains("withdrawn")) return Kind.WITHDRAWAL;
		return null;
	}
}

package com.tsghub;

import static com.tsghub.PlayerNames.*;
import static com.tsghub.TsgHubEvents.*;
import static com.tsghub.TsgHubFormat.*;
import static com.tsghub.TsgHubJson.*;
import static com.tsghub.TsgHubTheme.*;
import static com.tsghub.TsgHubUi.*;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.tsghub.TsgHubSidebarPanel.View;
import java.awt.BorderLayout;
import java.awt.event.ActionListener;
import java.time.LocalTime;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import javax.swing.JButton;
import javax.swing.JPanel;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
final class TsgHubCompetitionView
{
	private final TsgHubPlugin plugin;
	private final TsgHubSidebarPanel shell;

	JsonObject competitionEvent;
	String competitionName = "";
	volatile String openCompetitionId;
	private final JButton competitionJoinButton = primaryButton("Join");

	String openCompetitionId()
	{
		return shell.active ? openCompetitionId : null;
	}

	private String unit()
	{
		return "skill".equals(str(competitionEvent, "type")) ? "XP" : "kills";
	}

	void showCompetitionPreview(JsonObject event)
	{
		competitionEvent = event;
		shell.setView(View.COMPETITION_PREVIEW);
		shell.setEventHeader(event, true, false);
		shell.page.removeAll();
		JsonObject config = eventConfig(event);
		boolean skill = "skill".equals(str(event, "type"));
		String subject = skill ? skillName(str(config, "skill")) : str(config, "npcName");
		shell.page.add(shell.eventsView.eventSummaryCard(event, subject, skill ? "Most " + subject + " XP gained wins." : "Most " + subject + " kills wins."));
		shell.page.add(gap(GAP_L));
		competitionJoinButton.setEnabled(true);
		competitionJoinButton.setText("Join");
		for (ActionListener l : competitionJoinButton.getActionListeners()) competitionJoinButton.removeActionListener(l);
		competitionJoinButton.addActionListener(e -> {
			competitionJoinButton.setEnabled(false);
			competitionJoinButton.setText("Joining...");
			shell.eventsView.joinError.setVisible(false);
			plugin.sessions().participate(str(event, "id"));
		});
		shell.page.add(fitHeight(competitionJoinButton));
		shell.eventsView.joinError.setVisible(false);
		shell.page.add(shell.eventsView.joinError);
		shell.page.add(gap(GAP_S));
		shell.page.add(TsgHubSidebarPanel.hint(skill
			? "Your XP counts from the first time TSG Hub sees you after joining. Gains on other devices count the next time you log in with it."
			: !"loot".equals(str(config, "signal"))
				? "Kills count from your kill count message, so kills while TSG Hub isn't running still count at your next kill."
				: "Each kill counts when its loot drops while TSG Hub is running."));
		shell.refreshPage();
	}

	void competitionJoinFailed(String message)
	{
		competitionJoinButton.setEnabled(true);
		competitionJoinButton.setText("Join");
		showError(shell.eventsView.joinError, message, TsgHubSidebarPanel.TEXT_W);
	}

	void showCompetition(JsonObject event, String displayName, boolean open)
	{
		if (!open && shell.view != View.COMPETITION) return;
		if (!open && event.equals(competitionEvent) && Objects.equals(displayName == null ? "" : displayName, competitionName)) return;
		competitionEvent = event;
		competitionName = displayName == null ? "" : displayName;
		shell.setView(View.COMPETITION);
		openCompetitionId = str(event, "id");
		shell.refresh.setToolTipText("Refresh (updated " + LocalTime.now().format(TsgHubSidebarPanel.TIME) + ")");
		shell.setEventHeader(event, true, true);
		shell.page.removeAll();
		JsonObject config = eventConfig(event);
		boolean skill = "skill".equals(str(event, "type"));
		boolean hidden = bool(event, "hideScores");
		JsonArray rows = array(event, "leaderboard");
		JsonObject mine = null;
		for (JsonObject row : objects(rows)) if (samePlayer(str(row, "displayName"), competitionName)) mine = row;

		boolean started = !"scheduled".equals(str(event, "status"));
		boolean tracking = mine != null && bool(mine, "tracking");
		JPanel summary = card();
		JPanel top = row();
		top.add(shrinkable(boldLabel(skill ? skillName(str(config, "skill")) : str(config, "npcName"))), BorderLayout.CENTER);
		if (started && mine != null && mine.has("rank") && !hidden)
		{
			int rank = integer(mine, "rank", 0);
			top.add(label("#" + rank + " of " + integer(event, "participants", rows.size()), rank == 1 ? ACCENT : MUTED, smallFont()), BorderLayout.EAST);
		}
		JPanel lines = stack();
		lines.add(top);
		lines.add(gap(GAP_XS));
		if (!started)
		{
			String start = eventStartWhen(event);
			lines.add(TsgHubSidebarPanel.cardNote(start.isEmpty() ? "Counting starts when the event begins." : "Counting starts " + start + "."));
		}
		else
		{
			lines.add(label("+" + TsgHubFormat.number(mine == null ? 0 : integer(mine, "gained", 0)) + " " + unit(), SUCCESS, boldFont()));
			if (!tracking)
			{
				lines.add(gap(GAP_XS));
				lines.add(TsgHubSidebarPanel.cardNote(skill ? "Starts counting the next time you gain XP." : "Starts counting at your next kill."));
			}
		}
		JPanel prizes = prizeRow(event, smallFont());
		if (prizes != null)
		{
			lines.add(gap(GAP_S));
			lines.add(prizes);
		}
		summary.add(lines, BorderLayout.CENTER);
		shell.page.add(fitHeight(summary));
		shell.page.add(gap(GAP_M));

		if (hidden)
		{
			shell.page.add(shell.errorPanel("Scores are hidden", "The admins are keeping the leaderboard secret for now."));
		}
		else
		{
			shell.page.add(caption(integer(event, "participants", rows.size()) + (started ? " taking part" : " signed up")));
			shell.page.add(gap(GAP_S));
			for (int i = 0; i < rows.size(); i++)
			{
				JsonObject row = rows.get(i).getAsJsonObject();
				boolean me = samePlayer(str(row, "displayName"), competitionName);
				int rank = integer(row, "rank", i + 1);
				JPanel card = card();
				card.setLayout(new BorderLayout(8, 0));
				if (me) highlightSelf(card);
				if (started) card.add(rankLabel(rank, boldFont(), 18), BorderLayout.WEST);
				card.add(wrapped(str(row, "displayName"), TEXT, plainFont(), 110), BorderLayout.CENTER);
				String gained = bool(row, "tracking") ? TsgHubFormat.number(integer(row, "gained", 0)) : "-";
				if (started) card.add(label(gained, rank == 1 ? ACCENT : TEXT, boldFont()), BorderLayout.EAST);
				addCard(shell.page, fitHeight(card));
			}
		}
		shell.page.add(gap(GAP_L));
		JButton leave = dangerButton("Leave competition");
		leave.addActionListener(e -> {
			if (confirm(shell, "Leave competition", "Leave \"" + eventName(event) + "\"?\nYou'll drop off the leaderboard on this device. You can rejoin while it's running.", "Leave", true))
				plugin.sessions().leaveEvent(str(event, "id"));
		});
		shell.page.add(fitHeight(leave));
		shell.refreshPage();
	}

	void competitionProgress(String eventId, long gained, Long rank)
	{
		if (shell.view != View.COMPETITION || competitionEvent == null || !eventId.equals(openCompetitionId)) return;
		List<JsonObject> rows = new ArrayList<>(objects(array(competitionEvent, "leaderboard")));
		JsonObject mine = null;
		for (JsonObject row : rows) if (samePlayer(str(row, "displayName"), competitionName)) mine = row;
		if (mine == null) return;
		mine.addProperty("gained", gained);
		mine.addProperty("tracking", true);
		if (rank != null)
		{
			rows.sort(Comparator.comparingLong((JsonObject row) -> -integer(row, "gained", 0)).thenComparing(row -> str(row, "displayName")));
			JsonArray sorted = new JsonArray();
			for (int i = 0; i < rows.size(); i++)
			{
				rows.get(i).addProperty("rank", i + 1);
				sorted.add(rows.get(i));
			}
			mine.addProperty("rank", rank);
			competitionEvent.add("leaderboard", sorted);
		}
		showCompetition(competitionEvent, competitionName, false);
	}
}

package com.tsghub;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
