@RequiredArgsConstructor
final class TsgHubDropsView
{
	private final TsgHubPlugin plugin;
	private final TsgHubSidebarPanel shell;
	final JPanel dropsPanel = new JPanel(new BorderLayout(0, GAP_M));

	private final WidthTrackingPanel dropsPage = new WidthTrackingPanel();
	private final JScrollPane dropsScroll = scroll(dropsPage);
	private final JComboBox<String> dropType = new JComboBox<>(new String[] {"All types", "Mine", "Raids", "Pets", "Log"});
	private final JComboBox<String> dropValue = new JComboBox<>(new String[] {"Any value", "100k+", "1m+", "10m+"});
	private volatile int dropTypeIndex;
	private volatile int dropValueIndex;
	private JsonArray drops;
	private static final int DROP_ICON_W = 40;
	private static final String[] DROP_KINDS = {"", "", "raid", "pet", "log"};
	private static final long[] DROP_VALUES = {0, 100_000, 1_000_000, 10_000_000};
	void setDrops(JsonArray drops)
	{
		if (Objects.equals(this.drops, drops)) return;
		this.drops = drops;
		if (shell.shows(View.DROPS)) renderDrops();
	}

	JPanel buildDropsView()
	{
		JPanel filters = panel(new java.awt.GridLayout(1, 2, GAP_S, 0));
		dropTypeIndex = sessionIndex(DROP_TYPE, dropType.getItemCount());
		dropValueIndex = sessionIndex(DROP_VALUE, dropValue.getItemCount());
		dropType.setSelectedIndex(dropTypeIndex);
		dropValue.setSelectedIndex(dropValueIndex);
		dropType.setToolTipText("Drop type");
		dropValue.setToolTipText("Minimum value");
		dropType.addActionListener(e -> changeDropFilter());
		dropValue.addActionListener(e -> changeDropFilter());
		filters.add(dropType);
		filters.add(dropValue);
		dropsPanel.setOpaque(false);
		dropsPanel.add(filters, BorderLayout.NORTH);
		dropsPanel.add(dropsScroll, BorderLayout.CENTER);
		return dropsPanel;
	}

	private int sessionIndex(String key, int size)
	{
		try
		{
			int index = Integer.parseInt(plugin.session().get(key));
			return index >= 0 && index < size ? index : 0;
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	private void changeDropFilter()
	{
		if (dropTypeIndex == dropType.getSelectedIndex() && dropValueIndex == dropValue.getSelectedIndex()) return;
		dropTypeIndex = Math.max(0, dropType.getSelectedIndex());
		dropValueIndex = Math.max(0, dropValue.getSelectedIndex());
		plugin.session().set(DROP_TYPE, dropTypeIndex == 0 ? "" : String.valueOf(dropTypeIndex));
		plugin.session().set(DROP_VALUE, dropValueIndex == 0 ? "" : String.valueOf(dropValueIndex));
		drops = null;
		if (shell.shows(View.DROPS)) renderDrops();
		plugin.drops().load(false);
	}

	String dropsQuery()
	{
		String query = "";
		String kind = DROP_KINDS[dropTypeIndex];
		if (!kind.isEmpty()) query += "&kind=" + kind;
		if (dropTypeIndex == 1) query += "&player=" + TsgHubApi.encode(plugin.clan().playerName());
		if (dropValueIndex > 0) query += "&minValue=" + DROP_VALUES[dropValueIndex];
		return query;
	}

	void showDrops()
	{
		if (shell.pinned == View.DROPS)
		{
			shell.dock.expand();
			plugin.drops().load(false);
			return;
		}
		shell.setView(View.DROPS);
		renderDrops();
		plugin.drops().load(false);
	}

	void renderDrops()
	{
		shell.viewHeader(View.DROPS, "Drops", "", "");
		dropsPage.removeAll();
		if (drops == null)
		{
			dropsPage.add(caption("Loading drops..."));
		}
		else if (drops.size() == 0 && dropTypeIndex == 0 && dropValueIndex == 0)
		{
			dropsPage.add(shell.errorPanel("No drops yet", "Clan broadcasts for drops, raid loot, pets and collection log items show up here."));
		}
		else if (drops.size() == 0)
		{
			dropsPage.add(shell.errorPanel("No matching drops", "Nothing recent matches this type and value."));
		}
		else
		{
			Instant now = clock.instant();
			ZoneId zone = ZoneId.systemDefault();
			String day = null;
			for (int i = 0; i < drops.size(); i++)
			{
				JsonObject drop = drops.get(i).getAsJsonObject();
				String nextDay = TsgHubDrops.dropDay(str(drop, "receivedAt"), now, zone);
				if (!nextDay.equals(day))
				{
					dropsPage.add(listHeading(nextDay, i == 0));
					day = nextDay;
				}
				addCard(dropsPage, dropCard(drop, now, zone));
			}
		}
		refresh(dropsPage);
	}

	private JPanel dropCard(JsonObject drop, Instant now, ZoneId zone)
	{
		String player = str(drop, "player");
		boolean self = samePlayer(player, plugin.clan().playerName());
		JPanel card = card();
		if (self) highlightSelf(card);
		JLabel icon = dropIcon(integer(drop, "itemId", 0));
		if (icon != null) card.add(icon, BorderLayout.WEST);

		String item = str(drop, "name");
		JLabel name = shrinkable(boldLabel(item.isEmpty() ? str(drop, "item") : item));
		JPanel extras = panel(new FlowLayout(FlowLayout.RIGHT, 3, 0));
		for (JsonElement tag : array(drop, "tags"))
		{
			Color color = tag.isJsonObject() ? ColorUtil.fromHex(str(tag.getAsJsonObject(), "color")) : null;
			if (color != null) extras.add(badge(str(tag.getAsJsonObject(), "text"), color));
		}
		long value = drop.has("value") ? drop.get("value").getAsLong() : 0;
		if (value > 0) extras.add(label(formatGp(value), coinColor(value), smallFont()));
		card.add(TsgHubSidebarPanel.fillWidth(twoLines(
			row(name, caption(TsgHubDrops.dropWhen(str(drop, "receivedAt"), now, zone))),
			row(shrinkable(label(player, ACCENT, smallFont())), extras))), BorderLayout.CENTER);
		fullTextTooltip(card, () -> TsgHubDrops.dropTooltip(drop));
		return fitHeight(card);
	}

	private JLabel dropIcon(int itemId)
	{
		if (itemId <= 0) return null;
		AsyncBufferedImage image = plugin.getItemImage(itemId);
		if (image == null) return null;
		JLabel label = new JLabel();
		label.setVerticalAlignment(JLabel.CENTER);
		label.setPreferredSize(new Dimension(DROP_ICON_W, 32));
		image.addTo(label);
		return label;
	}
}

package com.tsghub;

import static com.tsghub.PlayerNames.*;
import static com.tsghub.TsgHubFormat.*;
import static com.tsghub.TsgHubJson.*;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import java.time.DateTimeException;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

final class TsgHubEvents
{
	private static final ZoneId CLAN_ZONE = ZoneId.of("Australia/Sydney");
	static final int MAX_SIGNUP_NOTE = 200;

	private TsgHubEvents()
	{
	}

	private static ZoneId eventZone(JsonObject event)
	{
		try { return ZoneId.of(str(event, "timeZone")); }
		catch (DateTimeException e) { return CLAN_ZONE; }
	}

	private static Instant midnight(String isoDate, ZoneId zone, int plusDays)
	{
		try { return LocalDate.parse(isoDate).plusDays(plusDays).atStartOfDay(zone).toInstant(); }
		catch (DateTimeException e) { return null; }
	}

	static Instant eventStart(JsonObject event)
	{
		Instant start = instant(str(event, "startsAt"));
		if (start == null) start = instant(str(eventConfig(event), "startsAt"));
		return start != null ? start : midnight(str(event, "startDate"), eventZone(event), 0);
	}

	static Instant eventEnd(JsonObject event)
	{
		Instant end = instant(str(event, "endsAt"));
		if (end != null || "drop-party".equals(str(event, "type"))) return end;
		return midnight(str(event, "endDate"), eventZone(event), 1);
	}

	static String eventWhen(JsonObject event)
	{
		return timeRange(eventStart(event), eventEnd(event), ZoneId.systemDefault(), clock.instant());
	}

	static String eventRelative(JsonObject event)
	{
		if ("ended".equals(str(event, "status"))) return "ended";
		return relativeTime(eventStart(event), eventEnd(event), clock.instant());
	}

	static String eventName(JsonObject event)
	{
		String type = str(event, "type");
		if ("skill".equals(type) || "boss".equals(type)) return eventTypeLabel(event);
		return str(event, "name");
	}

	static String eventCountdown(JsonObject event)
	{
		String relative = eventRelative(event);
		if (relative.startsWith("ends in ")) return relative.substring(8) + " left";
		if (relative.startsWith("starts ")) return relative.substring(7);
		return relative.isEmpty() ? "TBD" : capitalize(relative);
	}

	static String eventDetail(JsonObject event)
	{
		JsonObject config = eventConfig(event);
		switch (str(event, "type"))
		{
			case "skill": return skillName(str(config, "skill"));
			case "boss": return str(config, "npcName");
			case "drop-party":
				List<String> where = new ArrayList<>();
				if (integer(config, "world", 0) > 0) where.add("W" + integer(config, "world", 0));
				if (!str(config, "location").isEmpty()) where.add(str(config, "location"));
				return String.join(" · ", where);
			default: return eventDay(event);
		}
	}

	static long prizeTotal(List<Long> prizes)
	{
		long total = 0;
		for (long prize : prizes) total += prize;
		return total;
	}

	static List<Long> eventPrizes(JsonObject event)
	{
		List<Long> prizes = new ArrayList<>();
		for (JsonElement item : array(event, "prizes"))
			if (item.isJsonPrimitive() && item.getAsJsonPrimitive().isNumber() && item.getAsLong() > 0) prizes.add(item.getAsLong());
		return prizes;
	}

	static String prizeSummary(List<Long> prizes)
	{
		List<String> parts = new ArrayList<>();
		for (int i = 0; i < prizes.size(); i++) parts.add(place(i + 1) + " " + formatGp(prizes.get(i)));
		return String.join(" · ", parts);
	}

	static String eventStartWhen(JsonObject event)
	{
		Instant start = eventStart(event);
		if (start == null) return "";
		ZonedDateTime from = start.atZone(ZoneId.systemDefault());
		return when(from, clock.instant()) + " " + zoneName(from);
	}

	static String eventDay(JsonObject event)
	{
		Instant now = clock.instant();
		boolean started = "active".equals(str(event, "status"));
		Instant at = started ? eventEnd(event) : eventStart(event);
		if (at == null) return "";
		return (started ? "Ends " : "Starts ") + day(at.atZone(ZoneId.systemDefault()), now);
	}

	static String statusLabel(String status)
	{
		if ("active".equals(status)) return "Live";
		if ("ended".equals(status)) return "Ended";
		return "Upcoming";
	}

	static String eventTypeLabel(JsonObject event)
	{
		switch (str(event, "type"))
		{
			case "skill": return "Skill of the Week";
			case "boss": return "Boss of the Week";
			case "drop-party": return "Custom";
			default: return "Bingo";
		}
	}

	static JsonObject eventConfig(JsonObject event)
	{
		return object(event, "config");
	}

	static JsonObject scoreFor(JsonArray scores, String teamId)
	{
		for (JsonObject score : objects(scores)) if (str(score, "teamId").equals(teamId)) return score;
		JsonObject empty = new JsonObject();
		empty.addProperty("points", 0);
		empty.addProperty("completedTasks", 0);
		empty.add("tasks", new JsonArray());
		return empty;
	}

	static List<JsonObject> rankedTeams(JsonObject event)
	{
		JsonArray scores = array(event, "teamScores");
		List<JsonObject> ranked = objects(array(event, "teams"));
		ranked.sort(Comparator
			.comparingInt((JsonObject team) -> integer(scoreFor(scores, str(team, "id")), "points", 0)).reversed()
			.thenComparing(Comparator.comparingInt((JsonObject team) -> integer(scoreFor(scores, str(team, "id")), "completedTasks", 0)).reversed())
			.thenComparing(team -> str(team, "name"), String.CASE_INSENSITIVE_ORDER));
		return ranked;
	}

	static JsonObject progressFor(JsonArray progressRows, String taskId)
	{
		for (JsonObject progress : objects(progressRows)) if (str(progress, "taskId").equals(taskId)) return progress;
		JsonObject empty = new JsonObject();
		empty.addProperty("progress", 0);
		empty.addProperty("target", 1);
		empty.addProperty("completed", false);
		empty.add("completedBy", JsonNull.INSTANCE);
		return empty;
	}

	static String teamIdFor(JsonObject event, String displayName)
	{
		for (JsonObject member : objects(array(event, "members")))
		{
			if (samePlayer(str(member, "displayName"), displayName) && !str(member, "teamId").isEmpty()) return str(member, "teamId");
		}
		return "";
	}

	static boolean awaitingTeam(JsonObject event, String displayName)
	{
		for (JsonObject member : objects(array(event, "members")))
		{
			if (samePlayer(str(member, "displayName"), displayName)) return str(member, "teamId").isEmpty();
		}
		return false;
	}

	static boolean signupsOpen(JsonObject event)
	{
		JsonObject signups = object(event, "signups");
		if (!"bingo".equals(str(event, "type")) || !bool(signups, "open")) return false;
		Instant closes = instant(str(signups, "closesAt"));
		return closes == null || clock.instant().isBefore(closes);
	}

	static String signupSummary(JsonObject event, ZoneId zone)
	{
		JsonObject signups = object(event, "signups");
		int count = integer(signups, "count", 0);
		String waiting = count == 0 ? "No one waiting yet" : count + " waiting for a team";
		Instant closes = instant(str(signups, "closesAt"));
		if (closes == null) return waiting;
		ZonedDateTime at = closes.atZone(zone);
		String verb = clock.instant().isBefore(closes) ? "Closes " : "Closed ";
		return waiting + " · " + verb + when(at, clock.instant()) + " " + zoneName(at);
	}
}

package com.tsghub;

import static com.tsghub.TsgHubEvents.*;
import static com.tsghub.TsgHubFormat.*;
import static com.tsghub.TsgHubHtml.*;
import static com.tsghub.TsgHubJson.*;
import static com.tsghub.TsgHubSession.MEMBER_TOKEN;
import static com.tsghub.TsgHubTheme.*;
import static com.tsghub.TsgHubUi.*;
import static net.runelite.client.util.ColorUtil.toHexColor;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.tsghub.TsgHubSidebarPanel.View;
import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.time.ZoneId;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;

final class TsgHubEventsView
{
	private final TsgHubPlugin plugin;
	private final TsgHubSidebarPanel shell;

	private final JTextField codeField = new JTextField();
	private final JButton joinButton = primaryButton("Join event");
	final JLabel joinError = label("", TsgHubTheme.ERROR, smallFont());
	private final JTextField noteField = new JTextField();
	private final JButton signupButton = primaryButton("Sign up");
	private final JLabel signupError = label("", TsgHubTheme.ERROR, smallFont());
	private String signupLabel = "Sign up";
	private JsonObject signedUpEvent;
	private String signedUpNote = "";
	private boolean editingNote;

	private JsonArray events;
	private JsonObject previewEvent;

	TsgHubEventsView(TsgHubPlugin plugin, TsgHubSidebarPanel shell)
	{
		this.plugin = plugin;
		this.shell = shell;
		codeField.setToolTipText("Team code from an admin");
		placeholder(codeField, "Team code, e.g. DRGN42");
		codeField.addActionListener(e -> submitJoin());
		joinButton.addActionListener(e -> submitJoin());
		joinError.setVisible(false);
		noteField.setToolTipText("Optional, up to " + MAX_SIGNUP_NOTE + " characters");
		placeholder(noteField, "Note, e.g. free weekends");
		noteField.addActionListener(e -> submitSignup());
		signupButton.addActionListener(e -> submitSignup());
		signupError.setVisible(false);
	}

	void setEvents(JsonArray events)
	{
		if (Objects.equals(this.events, events)) return;
		this.events = events;
		if (shell.view == View.EVENTS) renderEvents();
		else if (shell.view == View.HOME) shell.homeView.renderHome();
	}

	int liveEvents()
	{
		int live = 0;
		if (events != null)
			for (int i = 0; i < events.size(); i++)
				if ("active".equals(str(events.get(i).getAsJsonObject(), "status"))) live++;
		return live;
	}

	String eventsSummary()
	{
		if (events == null) return "Loading...";
		int live = liveEvents();
		int upcoming = -live;
		for (int i = 0; i < events.size(); i++)
			if (!"ended".equals(str(events.get(i).getAsJsonObject(), "status"))) upcoming++;
		if (live == 0 && upcoming == 0) return "No events right now";
		if (upcoming == 0) return live + " live";
		if (live == 0) return upcoming + " upcoming";
		return live + " live, " + upcoming + " upcoming";
	}

	void openEvents()
	{
		showEventList();
		if (!plugin.live()) plugin.sessions().loadClanEvents();
	}

	void showEventList()
	{
		shell.setView(View.EVENTS);
		renderEvents();
	}

	private void showDropParty(JsonObject event)
	{
		shell.setView(View.DROP_PARTY);
		shell.setHeader(eventName(event), "Custom", true, false);
		shell.page.removeAll();
		JsonObject config = eventConfig(event);
		JPanel card = card();
		JPanel lines = stack();
		String countdown = capitalize(eventRelative(event));
		if (!countdown.isEmpty()) lines.add(label(countdown, "Ended".equals(countdown) ? MUTED : SUCCESS, boldFont()));
		lines.add(gap(GAP_S));
		lines.add(detail("When", eventWhen(event)));
		if (integer(config, "world", 0) > 0) lines.add(detail("World", String.valueOf(integer(config, "world", 0))));
		if (!str(config, "location").isEmpty()) lines.add(detail("Where", str(config, "location")));
		if (!str(config, "host").isEmpty()) lines.add(detail("Host", str(config, "host")));
		JPanel prizes = prizeRow(event, smallFont());
		if (prizes != null)
		{
			lines.add(gap(GAP_S));
			lines.add(prizes);
		}
		card.add(lines, BorderLayout.CENTER);
		shell.page.add(fitHeight(card));
		String notes = str(config, "notes");
		if (!notes.isEmpty())
		{
			shell.page.add(gap(GAP_M));
			shell.page.add(TsgHubSidebarPanel.hint(notes));
		}
		shell.refreshPage();
	}

	private JLabel detail(String label, String value)
	{
		JLabel line = label(html("<font color='" + toHexColor(MUTED) + "'>" + label + ":</font> " + escape(value), TsgHubSidebarPanel.CARD_TEXT_W), TEXT, plainFont());
		line.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
		return line;
	}

	void joinFailed(String message)
	{
		joinButton.setEnabled(true);
		joinButton.setText("Join event");
		showError(joinError, message, TsgHubSidebarPanel.TEXT_W);
		codeField.requestFocusInWindow();
		codeField.selectAll();
	}

	private void renderEvents()
	{
		String clan = plugin.clan().name();
		shell.setHeader("Events", "", true, true);
		shell.page.removeAll();
		if (clan.isEmpty())
		{
			shell.page.add(shell.errorPanel("No clan detected", "Join a clan in game to see its events."));
		}
		else if (events == null)
		{
			shell.page.add(caption("Loading events..."));
		}
		else
		{
			List<JsonObject> visible = objects(events);
			visible.removeIf(event -> "ended".equals(str(event, "status")));
			visible.sort(Comparator
				.comparing((JsonObject e) -> !bool(e, "joined"))
				.thenComparing(e -> !"active".equals(str(e, "status")))
				.thenComparing(TsgHubEvents::eventStart, Comparator.nullsLast(Comparator.naturalOrder())));
			if (visible.isEmpty())
			{
				shell.page.add(shell.errorPanel("No events yet", "When an admin creates an event, it will show up here."));
			}
			String section = null;
			for (JsonObject event : visible)
			{
				String next = "active".equals(str(event, "status")) ? "Live" : "Upcoming";
				if (!next.equals(section))
				{
					shell.page.add(listHeading(next, section == null));
					section = next;
				}
				addCard(shell.page, eventCard(event));
			}
		}
		shell.refreshPage();
	}

	private JPanel eventCard(JsonObject event)
	{
		boolean joined = bool(event, "joined");
		JPanel card = card();
		if (joined) highlightSelf(card);
		card.add(eventLines(event, plugin::getCoinImage), BorderLayout.CENTER);

		String type = str(event, "type");
		boolean dropParty = "drop-party".equals(type);
		boolean competition = "skill".equals(type) || "boss".equals(type);
		fullTextTooltip(card, () -> escape(eventWhen(event)));
		clickable(card, () -> {
			String id = str(event, "id");
			if (dropParty) showDropParty(event);
			else if (competition && joined && !plugin.session().get(MEMBER_TOKEN + id).isEmpty()) plugin.sessions().openCompetition(id, true);
			else if (competition) shell.competitionView.showCompetitionPreview(event);
			else if (joined) plugin.sessions().activateEvent(id);
			else showPreview(event);
		});
		return fitHeight(card);
	}

	JPanel eventSummaryCard(JsonObject event, String subject, String goal)
	{
		JPanel card = card();
		JPanel lines = stack();
		lines.add(shrinkable(boldLabel(subject)));
		lines.add(gap(GAP_XS));
		lines.add(wrapped(goal, TEXT, smallFont(), TsgHubSidebarPanel.CARD_TEXT_W));
		lines.add(gap(GAP_XS));
		lines.add(TsgHubSidebarPanel.cardNote(eventWhen(event)));
		String description = str(event, "description").trim();
		if (!description.isEmpty())
		{
			lines.add(gap(GAP_S));
			lines.add(TsgHubSidebarPanel.cardNote(description));
		}
		JPanel prizes = prizeRow(event, smallFont());
		if (prizes != null)
		{
			lines.add(gap(GAP_S));
			lines.add(prizes);
		}
		card.add(lines, BorderLayout.CENTER);
		return fitHeight(card);
	}

	private void showPreview(JsonObject event)
	{
		previewEvent = event;
		shell.setView(View.PREVIEW);
		shell.setEventHeader(event, true, false);
		shell.page.removeAll();
		shell.page.add(eventSummaryCard(event, "Bingo", "Complete tasks with your team for points. Most points wins."));
		boolean signups = signupsOpen(event);
		if (signups)
		{
			shell.page.add(gap(GAP_L));
			shell.page.add(label("Sign up for a team", TEXT, smallFont()));
			shell.page.add(gap(GAP_XS));
			shell.page.add(TsgHubSidebarPanel.hint(signupSummary(event, ZoneId.systemDefault())));
			shell.page.add(gap(GAP_S));
			resetNoteForm("", "Sign up");
			addNoteForm();
			shell.page.add(gap(GAP_S));
			shell.page.add(TsgHubSidebarPanel.hint("No team yet? Sign up and an admin will put you on one. Your board opens here when they do."));
		}
		shell.page.add(gap(GAP_L));
		shell.page.add(label(signups ? "Have a team code?" : "Team code", TEXT, smallFont()));
		shell.page.add(gap(GAP_S));
		codeField.setText("");
		shell.page.add(fitHeight(codeField));
		joinError.setVisible(false);
		shell.page.add(joinError);
		shell.page.add(gap(GAP_S));
		joinButton.setEnabled(true);
		joinButton.setText("Join event");
		shell.page.add(fitHeight(joinButton));
		shell.page.add(gap(GAP_S));
		shell.page.add(TsgHubSidebarPanel.hint("Ask an admin for your team's code. Your team can't be changed after you join."));
		shell.refreshPage();
		SwingUtilities.invokeLater((signups ? noteField : codeField)::requestFocusInWindow);
	}

	private void resetNoteForm(String note, String action)
	{
		noteField.setText(note);
		signupError.setVisible(false);
		signupLabel = action;
		signupButton.setEnabled(true);
		signupButton.setText(action);
	}

	private void addNoteForm()
	{
		shell.page.add(fitHeight(noteField));
		shell.page.add(signupError);
		shell.page.add(gap(GAP_S));
		shell.page.add(fitHeight(signupButton));
	}

	void showSignedUp(JsonObject event, String note, boolean open)
	{
		if (!open && shell.view != View.SIGNUP) return;
		boolean same = signedUpEvent != null && str(signedUpEvent, "id").equals(str(event, "id"));
		if (!open && same && event.equals(signedUpEvent) && note.equals(signedUpNote)) return;
		if (!same || open) editingNote = false;
		signedUpEvent = event;
		signedUpNote = note;
		previewEvent = event;
		shell.setView(View.SIGNUP);
		renderSignedUp();
	}

	private void renderSignedUp()
	{
		JsonObject event = signedUpEvent;
		boolean open = signupsOpen(event);
		shell.setEventHeader(event, true, true);
		shell.page.removeAll();
		JPanel card = card();
		highlightSelf(card);
		JPanel lines = stack();
		lines.add(label("Signed up, waiting for a team", SUCCESS, boldFont()));
		lines.add(gap(GAP_XS));
		lines.add(TsgHubSidebarPanel.cardNote(signedUpNote.isEmpty() ? "No note" : "Note: " + signedUpNote));
		lines.add(gap(GAP_XS));
		lines.add(TsgHubSidebarPanel.cardNote(signupSummary(event, ZoneId.systemDefault())));
		card.add(lines, BorderLayout.CENTER);
		shell.page.add(fitHeight(card));
		shell.page.add(gap(GAP_M));
		if (editingNote && open)
		{
			shell.page.add(label("Note", TEXT, smallFont()));
			shell.page.add(gap(GAP_S));
			addNoteForm();
			shell.page.add(gap(GAP_S));
			shell.page.add(fitHeight(onClick(button("Cancel"), () -> {
				editingNote = false;
				renderSignedUp();
			})));
		}
		else
		{
			signupError.setVisible(false);
			shell.page.add(signupError);
			JPanel actions = panel(new GridLayout(1, open ? 2 : 1, 4, 0));
			if (open) actions.add(onClick(button("Edit note"), () -> {
				editingNote = true;
				resetNoteForm(signedUpNote, "Save note");
				renderSignedUp();
				SwingUtilities.invokeLater(noteField::requestFocusInWindow);
			}));
			actions.add(onClick(dangerButton("Withdraw"), this::confirmWithdraw));
			shell.page.add(fitHeight(actions));
		}
		shell.page.add(gap(GAP_S));
		shell.page.add(TsgHubSidebarPanel.hint(open
			? "An admin will put you on a team. Your team's board opens here when they do."
			: "Sign-ups are closed. An admin will put you on a team, and your board opens here when they do."));
		shell.refreshPage();
	}

	private void confirmWithdraw()
	{
		if (signedUpEvent == null) return;
		if (confirm(shell, "Withdraw", "Leave the sign-ups for \"" + eventName(signedUpEvent) + "\"?", "Withdraw", true))
			plugin.sessions().withdraw(str(signedUpEvent, "id"));
	}

	void signupFailed(String message)
	{
		signupButton.setEnabled(true);
		signupButton.setText(signupLabel);
		showError(signupError, message, TsgHubSidebarPanel.TEXT_W);
	}

	private void submitSignup()
	{
		String note = noteField.getText().trim();
		if (note.length() > MAX_SIGNUP_NOTE)
		{
			signupFailed("Keep the note to " + MAX_SIGNUP_NOTE + " characters.");
			return;
		}
		signupError.setVisible(false);
		signupButton.setEnabled(false);
		signupButton.setText("Sign up".equals(signupLabel) ? "Signing up..." : "Saving...");
		if (shell.view == View.SIGNUP) plugin.sessions().editNote(str(previewEvent, "id"), note);
		else plugin.sessions().signup(str(previewEvent, "id"), note);
	}

	private void submitJoin()
	{
		String code = codeField.getText().trim();
		if (code.isEmpty())
		{
			joinFailed("Enter your team code.");
			return;
		}
		joinError.setVisible(false);
		joinButton.setEnabled(false);
		joinButton.setText("Joining...");
		plugin.sessions().join(code, str(previewEvent, "id"));
	}
}

package com.tsghub;

import java.net.ConnectException;
import java.net.SocketTimeoutException;
import java.net.UnknownHostException;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import java.util.concurrent.CompletionException;
import lombok.extern.slf4j.Slf4j;

@Slf4j
final class TsgHubFormat
{
	static final DateTimeFormatter DATE_WITH_YEAR = DateTimeFormatter.ofPattern("d MMM yyyy", Locale.US);
	static final DateTimeFormatter SHORT_DATE = DateTimeFormatter.ofPattern("d MMM", Locale.US);
	static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE d MMM", Locale.US);
	static final DateTimeFormatter CLOCK_24 = DateTimeFormatter.ofPattern("HH:mm", Locale.US);
	private static final DateTimeFormatter DAY_WITH_YEAR = DateTimeFormatter.ofPattern("EEE d MMM yyyy", Locale.US);
	private static final DateTimeFormatter HOUR = DateTimeFormatter.ofPattern("h", Locale.US);
	private static final DateTimeFormatter HOUR_MINUTE = DateTimeFormatter.ofPattern("h:mm", Locale.US);
	private static final DateTimeFormatter ZONE = DateTimeFormatter.ofPattern("zzz", Locale.US);
	static Clock clock = Clock.systemUTC();

	private TsgHubFormat()
	{
	}

	static String number(long value)
	{
		return String.format(Locale.US, "%,d", value);
	}

	static String elapsed(Instant then, Instant now)
	{
		long minutes = Math.max(0, Duration.between(then, now).toMinutes());
		if (minutes < 1) return "";
		if (minutes < 60) return minutes + "m";
		long hours = minutes / 60;
		if (hours < 24) return hours + "h";
		long days = hours / 24;
		if (days < 14) return days + "d";
		if (days < 60) return days / 7 + "w";
		if (days < 365) return days / 30 + "mo";
		return days / 365 + "y";
	}

	static String ago(Instant then, Instant now)
	{
		String elapsed = elapsed(then, now);
		return elapsed.isEmpty() ? "just now" : elapsed + " ago";
	}

	static String friendlyError(Throwable error)
	{
		if (error instanceof CompletionException && error.getCause() != null) error = error.getCause();
		log.warn("TSG Hub error", error);
		Throwable root = error;
		while (root.getCause() != null && root.getCause() != root) root = root.getCause();
		if (root instanceof ConnectException || root instanceof UnknownHostException)
			return "Can't reach the TSG Hub service. Try again in a moment.";
		if (root instanceof SocketTimeoutException)
			return "The TSG Hub service took too long to respond. Try again.";
		String message = error.getMessage();
		if (message == null || message.trim().isEmpty()) return "Something went wrong (" + root.getClass().getSimpleName() + "). Details are in the RuneLite log.";
		return message.endsWith(".") ? message : message + ".";
	}

	static String plural(int count, String noun)
	{
		return count + " " + noun + (count == 1 ? "" : "s");
	}

	static String zoneName(ZonedDateTime time)
	{
		return time.format(ZONE);
	}

	static String shortDate(String iso, Instant now, ZoneId zone)
	{
		Instant at = TsgHubJson.instant(iso);
		if (at == null) return "";
		ZonedDateTime day = at.atZone(zone);
		return day.format(day.getYear() == now.atZone(zone).getYear() ? SHORT_DATE : DATE_WITH_YEAR);
	}

	static String localDate(Instant when, ZoneId zone)
	{
		return when.atZone(zone).format(DATE_WITH_YEAR);
	}

	private static String clock(ZonedDateTime time, boolean meridiem)
	{
		String text = time.format(time.getMinute() == 0 ? HOUR : HOUR_MINUTE);
		return meridiem ? text + (time.getHour() < 12 ? "am" : "pm") : text;
	}

	static String day(ZonedDateTime time, Instant now)
	{
		return time.format(time.getYear() == now.atZone(time.getZone()).getYear() ? DAY : DAY_WITH_YEAR);
	}

	static String when(ZonedDateTime time, Instant now)
	{
		return day(time, now) + ", " + clock(time, true);
	}

	static String timeRange(Instant start, Instant end, ZoneId zone, Instant now)
	{
		if (start == null) return "Time TBD";
		ZonedDateTime from = start.atZone(zone);
		if (end == null) return when(from, now) + " " + zoneName(from);
		ZonedDateTime to = end.atZone(zone);
		boolean sameZone = zoneName(from).equals(zoneName(to));
		boolean sameDay = from.toLocalDate().equals(to.toLocalDate());
		if (sameDay && sameZone)
			return day(from, now) + ", " + clock(from, from.getHour() < 12 != to.getHour() < 12) + "-" + clock(to, true) + " " + zoneName(to);
		String until = sameDay ? clock(to, true) : when(to, now);
		return when(from, now) + (sameZone ? "" : " " + zoneName(from)) + " to " + until + " " + zoneName(to);
	}

	static String span(Duration duration)
	{
		long minutes = Math.max(1, (duration.getSeconds() + 59) / 60);
		long days = minutes / 1440, hours = minutes % 1440 / 60, rest = minutes % 60;
		if (days > 0) return days + "d" + (hours > 0 ? " " + hours + "h" : "");
		if (hours > 0) return hours + "h" + (rest > 0 ? " " + rest + "m" : "");
		return rest + "m";
	}

	static String relativeTime(Instant start, Instant end, Instant now)
	{
		if (start == null) return "";
		if (now.isBefore(start)) return "starts in " + span(Duration.between(now, start));
		if (end == null) return "happening now";
		if (now.isBefore(end)) return "ends in " + span(Duration.between(now, end));
		return "ended";
	}

	static String capitalize(String text)
	{
		return text.isEmpty() ? text : Character.toUpperCase(text.charAt(0)) + text.substring(1);
	}

	static String place(int place)
	{
		if (place % 100 >= 11 && place % 100 <= 13) return place + "th";
		switch (place % 10)
		{
			case 1: return place + "st";
			case 2: return place + "nd";
			case 3: return place + "rd";
			default: return place + "th";
		}
	}

	static String formatGp(long value)
	{
		if (value <= 0) return "";
		if (value >= 1_000_000_000L) return trimDecimal(value / 1_000_000_000.0) + "B";
		if (value >= 1_000_000L) return trimDecimal(value / 1_000_000.0) + "M";
		if (value >= 1_000L) return trimDecimal(value / 1_000.0) + "K";
		return value + " gp";
	}

	private static String trimDecimal(double value)
	{
		String text = String.format(Locale.ROOT, "%.1f", Math.floor(value * 10) / 10);
		return text.endsWith(".0") ? text.substring(0, text.length() - 2) : text;
	}
	static String skillName(String key)
	{
		if (key == null || key.isEmpty()) return "";
		String lower = key.toLowerCase(Locale.ROOT).replace('_', ' ');
		return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
	}
}

package com.tsghub;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import lombok.RequiredArgsConstructor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.WorldView;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.util.Text;

@RequiredArgsConstructor
final class TsgHubGameTracker
{
	private static final int PET_CHECK_TICKS = 5;
	private static final int MAX_LOOT_LOG_ITEMS = 50;

	private final TsgHubPlugin plugin;
	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final ScheduledExecutorService executor;
	private final Map<String, Integer> recentLootEvents = new ConcurrentHashMap<>();
	private int petCheckTicks;
	private int recentPet;
	private int recentPetTick;
	private String lastGroupContent = "";
	private int lastGroupContentTick = -1;
	private Set<Integer> inventoryPets = Collections.emptySet();

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (!plugin.sharingInClan() || client.getLocalPlayer() == null) return;
		plugin.signals().xp(event.getSkill().name(), event.getXp(), client.getTickCount());
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		rewardInterface(event.getGroupId(), true);
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		rewardInterface(event.getGroupId(), false);
	}

	private void rewardInterface(int groupId, boolean open)
	{
		if (plugin.sharingInClan() && TsgHubRules.get().rewardInterfaces.contains(groupId)) plugin.liveSync().socket().rewardInterface(groupId, open, client.getTickCount());
	}

	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot event)
	{
		if (!plugin.clan().isHubClan() || event.getComposition() == null) return;
		String name = Text.removeTags(event.getComposition().getName());
		plugin.drops().onLoot(name, itemNames(event.getItems()));
		processLoot("NPC", name, event.getItems(), 1);
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (!plugin.clan().isHubClan()) return;
		if (event.getType() == null || "PLAYER".equals(event.getType().name()) || "NPC".equals(event.getType().name())) return;
		plugin.drops().onLoot(event.getName(), itemNames(event.getItems()));
		processLoot(event.getType().name(), event.getName(), event.getItems(), event.getAmount());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event == null || event.getMessage() == null) return;
		if (event.getType() == ChatMessageType.CLAN_MESSAGE && plugin.chat().isOwnEcho(event.getMessage())) return;
		if (!plugin.clan().isHubClan() || client.getLocalPlayer() == null) return;
		plugin.drops().onChatMessage(event);
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM) return;
		if (!plugin.sharingInClan()) return;
		String plain = Text.removeTags(event.getMessage());
		String message = plain.toLowerCase(Locale.ROOT);
		if (isPetMessage(message))
		{
			if (recentPet > 0 && client.getTickCount() - recentPetTick <= 2) sendPet(recentPet);
			else petCheckTicks = PET_CHECK_TICKS;
			recentPet = 0;
		}
		if (TsgHubRules.get().groupContent.stream().anyMatch(message::contains)) reportGroupContent(plain.trim(), message);
		TsgHubSignals signals = plugin.signals();
		if (!signals.wantsChat(message)) return;
		JsonObject chat = new JsonObject();
		chat.addProperty("text", message);
		if (signals.wantsPlayers(message)) addNearbyPlayers(chat);
		signals.send("chat", chat);
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (!plugin.sharingInClan())
		{
			petCheckTicks = 0;
			return;
		}
		if (petCheckTicks <= 0) return;
		petCheckTicks--;
		int petId = followerPetId();
		if (petId > 0) sendPet(petId);
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV || !plugin.sharingInClan()) return;
		Set<Integer> pets = inventoryPetIds();
		int added = 0;
		for (int itemId : pets) if (!inventoryPets.contains(itemId)) added = itemId;
		inventoryPets = pets;
		if (added <= 0) return;
		if (petCheckTicks > 0) sendPet(added);
		else
		{
			recentPet = added;
			recentPetTick = client.getTickCount();
		}
	}

	void reportXp(String skills)
	{
		if (!plugin.sharingInClan()) return;
		clientThread.invokeLater(() -> {
			if (client.getLocalPlayer() == null) return;
			for (String name : skills.split(","))
			{
				Skill skill;
				try { skill = Skill.valueOf(name.trim()); }
				catch (IllegalArgumentException e) { continue; }
				plugin.signals().xp(skill.name(), client.getSkillExperience(skill), client.getTickCount());
			}
		});
	}

	void report(String type, String path, JsonObject body)
	{
		report(type, path, null, body);
	}

	void report(String type, String path, String token, JsonObject body)
	{
		report(type, "POST", path, token, body);
	}

	void report(String type, String method, String path, String token, JsonObject body)
	{
		TsgHubReports reports = plugin.reports();
		if (reports == null || reports.send(type, method, path, token, body) || executor.isShutdown()) return;
		if (client.isClientThread()) executor.execute(reports::flush);
		else reports.flush();
	}

	void reset()
	{
		recentLootEvents.clear();
		petCheckTicks = 0;
		recentPet = 0;
		recentPetTick = 0;
		lastGroupContent = "";
		lastGroupContentTick = -1;
		inventoryPets = Collections.emptySet();
	}

	private void reportGroupContent(String text, String key)
	{
		int tick = client.getTickCount();
		if (tick == lastGroupContentTick && key.equals(lastGroupContent)) return;
		lastGroupContentTick = tick;
		lastGroupContent = key;
		long hash = client.getAccountHash();
		Player self = client.getLocalPlayer();
		WorldView worldView = client.getTopLevelWorldView();
		if (hash == -1 || self == null || worldView == null || worldView.players() == null || executor.isShutdown()) return;
		List<String> nearby = new ArrayList<>();
		for (Player player : worldView.players())
		{
			if (player != null && player != self && player.getName() != null && player.isClanMember()) nearby.add(Text.toJagexName(player.getName()));
		}
		List<String> clanmates = clanmates(nearby, self.getName());
		if (clanmates.isEmpty()) return;
		TsgHubClan clan = plugin.clan();
		JsonObject body = new JsonObject();
		body.addProperty("clanName", clan.name());
		body.addProperty("displayName", clan.playerName().isEmpty() ? Text.toJagexName(self.getName()) : clan.playerName());
		body.addProperty("accountHash", Long.toString(hash));
		body.addProperty("message", text);
		JsonArray names = new JsonArray();
		clanmates.forEach(names::add);
		body.add("clanmates", names);
		report("group", "/v1/group-content", body);
	}

	static List<String> clanmates(List<String> names, String self)
	{
		List<String> out = new ArrayList<>();
		for (String name : names)
		{
			if (name == null || name.trim().isEmpty() || PlayerNames.samePlayer(name, self)) continue;
			if (out.stream().noneMatch(existing -> PlayerNames.samePlayer(existing, name))) out.add(name);
		}
		return out;
	}

	private void addNearbyPlayers(JsonObject chat)
	{
		List<String> visiblePlayers = new ArrayList<>();
		List<String> nonClanPlayers = new ArrayList<>();
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView != null && worldView.players() != null)
		{
			for (Player player : worldView.players())
			{
				if (player == null || player.getName() == null) continue;
				String name = player.getName();
				if (visiblePlayers.stream().noneMatch(existing -> PlayerNames.samePlayer(existing, name))) visiblePlayers.add(name);
				if (!player.isClanMember() && nonClanPlayers.stream().noneMatch(existing -> PlayerNames.samePlayer(existing, name))) nonClanPlayers.add(name);
			}
		}
		JsonArray players = new JsonArray();
		visiblePlayers.forEach(players::add);
		chat.add("players", players);
		JsonArray outsiders = new JsonArray();
		nonClanPlayers.forEach(outsiders::add);
		chat.add("nonClanPlayers", outsiders);
	}

	private void sendPet(int petId)
	{
		petCheckTicks = 0;
		recentPet = 0;
		JsonObject pet = new JsonObject();
		pet.addProperty("itemId", petId);
		pet.addProperty("name", itemManager.getItemComposition(petId).getName());
		plugin.signals().send("pet", pet);
	}

	private static boolean isPetMessage(String message)
	{
		for (String pattern : TsgHubRules.get().petMessages) if (message.contains(pattern)) return true;
		return false;
	}

	private Set<Integer> inventoryPetIds()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null) return Collections.emptySet();
		Set<Integer> pets = new HashSet<>();
		for (Item item : inventory.getItems())
		{
			int itemId = itemManager.canonicalize(item.getId());
			if (TsgHubRules.get().pets.contains(itemId)) pets.add(itemId);
		}
		return pets;
	}

	private int followerPetId()
	{
		NPC follower = client.getFollower();
		String followerName = follower == null ? null : petName(follower.getName());
		if (followerName == null || followerName.isEmpty()) return -1;
		for (int itemId : TsgHubRules.get().pets)
		{
			if (followerName.equals(petName(itemManager.getItemComposition(itemId).getName()))) return itemId;
		}
		return -1;
	}

	private static String petName(String name)
	{
		if (name == null) return null;
		String normalized = Text.removeTags(name).trim().toLowerCase(Locale.ROOT);
		return normalized.startsWith("pet ") ? normalized.substring(4) : normalized;
	}

	private List<String> itemNames(Collection<ItemStack> items)
	{
		List<String> names = new ArrayList<>();
		if (items == null) return names;
		for (ItemStack item : items)
		{
			String name = client.getItemDefinition(itemManager.canonicalize(item.getId())).getName();
			if (name != null) names.add(name);
		}
		return names;
	}

	private void processLoot(String sourceType, String sourceName, Collection<ItemStack> items, int amount)
	{
		if (!plugin.sharingInClan() || client.getLocalPlayer() == null
			|| sourceName == null || items == null || isDuplicateLootEvent(sourceType, sourceName, items)) return;
		JsonArray lootItems = new JsonArray();
		for (ItemStack item : items)
		{
			if (lootItems.size() >= MAX_LOOT_LOG_ITEMS) break;
			int itemId = itemManager.canonicalize(item.getId());
			String itemName = client.getItemDefinition(itemId).getName();
			if (itemName == null || item.getQuantity() < 1) continue;
			JsonObject entry = new JsonObject();
			entry.addProperty("itemId", itemId);
			entry.addProperty("name", itemName);
			entry.addProperty("quantity", item.getQuantity());
			lootItems.add(entry);
		}
		JsonObject loot = new JsonObject();
		loot.addProperty("sourceType", sourceType);
		loot.addProperty("sourceName", sourceName);
		loot.addProperty("kills", Math.max(1, amount));
		loot.add("items", lootItems);
		plugin.signals().send("loot", loot);
	}

	private boolean isDuplicateLootEvent(String sourceType, String sourceName, Collection<ItemStack> items)
	{
		int tick = client.getTickCount();
		recentLootEvents.entrySet().removeIf(entry -> tick - entry.getValue() > 3);
		List<String> stacks = new ArrayList<>();
		for (ItemStack item : items) stacks.add(itemManager.canonicalize(item.getId()) + "x" + item.getQuantity());
		Collections.sort(stacks);
		String key = tick + ":" + sourceType + ":" + sourceName.toLowerCase(Locale.ROOT) + ":" + String.join(",", stacks);
		return recentLootEvents.putIfAbsent(key, tick) != null;
	}
}

package com.tsghub;

import static com.tsghub.TsgHubJson.*;
import static com.tsghub.TsgHubSession.GROUP_PASSPHRASE;
import static com.tsghub.TsgHubSession.GROUP_PLAYER;
import static com.tsghub.TsgHubSession.GROUP_TOKEN;
import static com.tsghub.TsgHubUi.*;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.tsghub.TsgHubUi.Tone;
import java.util.AbstractMap;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.party.PartyService;

final class TsgHubGroups implements GroupTracker.Listener
{
	private static final String WILDERNESS = "Wilderness lvl ";
	// The service drops members after 3 minutes without a check-in.
	static final int HEARTBEAT_SECONDS = 60;
	static final int REFRESH_SECONDS = 30;

	private final TsgHubPlugin plugin;
	private final Client client;
	private final PartyService partyService;
	private final ScheduledExecutorService executor;
	private final Supplier<TsgHubApi> api;
	private final Supplier<TsgHubSidebarPanel> sidebar;
	private final TsgHubSocket socket;
	private volatile GroupTracker tracker;
	private volatile JsonObject group;
	private volatile boolean awaitingBeat;

	TsgHubGroups(TsgHubPlugin plugin, Client client, PartyService partyService, ScheduledExecutorService executor,
		Supplier<TsgHubApi> api, Supplier<TsgHubSidebarPanel> sidebar, TsgHubSocket socket)
	{
		this.plugin = plugin;
		this.socket = socket;
		this.client = client;
		this.partyService = partyService;
		this.executor = executor;
		this.api = api;
		this.sidebar = sidebar;
	}

	void setTracker(GroupTracker tracker)
	{
		this.tracker = tracker;
	}

	boolean isGroupParty(String passphrase)
	{
		String saved = plugin.session().get(GROUP_PASSPHRASE);
		return plugin.sharingEnabled() && passphrase != null && !saved.isEmpty() && saved.equals(passphrase);
	}

	boolean inGroup()
	{
		return !plugin.session().get(GROUP_TOKEN).isEmpty();
	}

	JsonObject currentGroup()
	{
		return group;
	}

	boolean isLeader()
	{
		JsonObject current = group;
		return inGroup() && current != null && PlayerNames.samePlayer(TsgHubJson.str(current, "leaderName"), plugin.session().get(GROUP_PLAYER));
	}

	boolean inOtherParty()
	{
		return partyService.isInParty() && !isGroupParty(partyService.getPartyPassphrase());
	}

	void loadGroups()
	{
		loadGroups(false);
	}

	private void loadGroups(boolean quiet)
	{
		if (!plugin.canUseHub() || executor.isShutdown()) return;
		String clan = TsgHubApi.encode(plugin.clan().name());
		if (!quiet) busy(true);
		api.get().call("GET", "/v1/groups?clanName=" + clan, null, null).whenCompleteAsync(TsgHubApi.handle(response ->
		{
			apply(response.getAsJsonArray("groups"));
		}, e -> { if (!quiet) status("Couldn't load parties. " + TsgHubFormat.friendlyError(e), Tone.ERROR); }, () -> { if (!quiet) busy(false); }), executor);
	}

	void apply(JsonArray groups)
	{
		if (groups == null) return;
		JsonObject current = group;
		if (current != null && inGroup())
		{
			JsonObject next = TsgHubJson.byId(groups, TsgHubJson.str(current, "id"));
			if (next != null) group = next;
			if ((next == null || !memberNames(next).equals(memberNames(current))) && !executor.isShutdown()) executor.submit(this::heartbeat);
		}
		plugin.ui(s -> s.partiesView.setGroups(groups));
	}

	void open()
	{
		if (socket.isLive()) plugin.liveSync().syncNow();
		else refresh();
	}

	void refresh()
	{
		if (inGroup() && !executor.isShutdown()) executor.submit(this::heartbeat);
		loadGroups();
	}

	void create()
	{
		if (!plugin.canUseHub()) { plugin.ui(s -> s.partiesView.groupActionFailed("Log in to a " + plugin.clan().hubName() + " character first.")); return; }
		enter("POST", "/v1/groups", identity(), true);
	}

	void setTitle(String title)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("activity", title.trim());
		update("/v1/groups/title", payload);
	}

	void kick(String name)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("displayName", name);
		update("/v1/groups/kick", payload);
		if (!executor.isShutdown()) executor.submit(this::heartbeat);
	}

	void setLocked(boolean locked)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("locked", locked);
		update("/v1/groups/lock", payload);
	}

	private void update(String path, JsonObject payload)
	{
		String token = plugin.session().get(GROUP_TOKEN);
		if (token.isEmpty() || executor.isShutdown()) return;
		api.get().call("POST", path, token, payload).whenCompleteAsync((response, error) -> {
			try
			{
				JsonObject joined = TsgHubApi.result(response, error).getAsJsonObject("group");
				group = joined;
				plugin.ui(s -> s.partiesView.groupRefreshed(joined));
				refreshUnlessLive();
			}
			catch (TsgHubApi.HttpError e) { when404(e); }
			catch (Exception e) { plugin.ui(s -> s.partiesView.groupActionFailed(TsgHubFormat.friendlyError(e))); }
		}, executor);
	}

	void join(String groupId)
	{
		if (!plugin.canUseHub()) { plugin.ui(s -> s.partiesView.groupActionFailed("Log in to a " + plugin.clan().hubName() + " character first.")); return; }
		enter("POST", "/v1/groups/" + groupId + "/join", identity(), false);
	}

	private void enter(String method, String path, JsonObject payload, boolean created)
	{
		String previousToken = plugin.session().get(GROUP_TOKEN);
		api.get().call(method, path, null, payload).whenCompleteAsync((response, error) -> {
			try
			{
				JsonObject result = TsgHubApi.result(response, error);
				JsonObject joined = result.getAsJsonObject("group");
				String passphrase = result.get("passphrase").getAsString();
				// The service already removed us from the previous group.
				if (!previousToken.isEmpty()) forget();
				// Save before switching so the tracker recognises the new party.
				plugin.session().set(GROUP_TOKEN, result.get("token").getAsString());
				plugin.session().set(GROUP_PASSPHRASE, passphrase);
				plugin.session().set(GROUP_PLAYER, plugin.clan().playerName());
				group = joined;
				partyService.changeParty(passphrase);
				status(created ? "Started a party." : "Joined " + partyTitle(joined) + ".", Tone.SUCCESS);
				plugin.ui(s -> s.partiesView.showGroup(joined));
				refreshUnlessLive();
			}
			catch (TsgHubApi.HttpError e) { when404(e); }
			catch (Exception e) { plugin.ui(s -> s.partiesView.groupActionFailed(TsgHubFormat.friendlyError(e))); }
		}, executor);
	}

	void leave()
	{
		String token = plugin.session().get(GROUP_TOKEN);
		// Compare passphrases directly: sharing may already be off.
		String passphrase = plugin.session().get(GROUP_PASSPHRASE);
		boolean ours = partyService.isInParty() && !passphrase.isEmpty() && passphrase.equals(partyService.getPartyPassphrase());
		forget();
		if (ours) partyService.changeParty(null);
		plugin.ui(s -> s.partiesView.showGroupList());
		if (token.isEmpty() || executor.isShutdown()) return;
		// The service drops idle members on its own if this fails.
		api.get().call("POST", "/v1/groups/leave", token, null).whenCompleteAsync((response, error) -> refreshUnlessLive(), executor);
	}

	void heartbeat()
	{
		String token = plugin.session().get(GROUP_TOKEN);
		if (token.isEmpty()) return;
		if (!plugin.sharingEnabled()) { leave(); return; }
		GroupTracker t = tracker;
		if (t != null && t.idleTooLong()) { status("Left your party after 30 minutes logged out.", Tone.INFO); leave(); return; }
		String name = plugin.clan().playerName();
		if (!name.isEmpty() && !PlayerNames.samePlayer(name, plugin.session().get(GROUP_PLAYER))) { leave(); return; }
		JsonObject payload = new JsonObject();
		if (client.getGameState() == GameState.LOGGED_IN) payload.addProperty("world", client.getWorld());
		payload.addProperty("area", plugin.currentArea());
		if (!awaitingBeat && socket.groupHeartbeat(token, payload))
		{
			awaitingBeat = true;
			return;
		}
		awaitingBeat = false;
		api.get().call("POST", "/v1/groups/heartbeat", token, payload).whenCompleteAsync((response, error) -> {
			try { beaten(TsgHubApi.result(response, error)); }
			catch (TsgHubApi.HttpError e) { beatRejected(e.status); }
			catch (Exception ignored) { /* Try again next beat. */ }
		}, executor);
	}

	void beaten(JsonObject result)
	{
		awaitingBeat = false;
		if (!inGroup() || !result.has("group") || !result.get("group").isJsonObject()) return;
		JsonObject joined = result.getAsJsonObject("group");
		group = joined;
		String rotated = str(result, "passphrase");
		if (!rotated.isEmpty()) plugin.session().set(GROUP_PASSPHRASE, rotated);
		// Still listed after a client restart but not connected.
		String passphrase = plugin.session().get(GROUP_PASSPHRASE);
		if (!passphrase.equals(partyService.getPartyPassphrase())) partyService.changeParty(passphrase);
		plugin.ui(s -> s.partiesView.groupRefreshed(joined));
	}

	void beatRejected(int status)
	{
		awaitingBeat = false;
		if (status != 404 || !inGroup()) return;
		status("Your party has closed.", Tone.INFO);
		leave();
	}

	private void refreshUnlessLive()
	{
		if (!socket.isLive()) loadGroups(true);
	}

	private static List<String> memberNames(JsonObject group)
	{
		List<String> names = new ArrayList<>();
		for (JsonObject member : objects(array(group, "members"))) names.add(PlayerNames.key(str(member, "displayName")));
		return names;
	}

	private void when404(TsgHubApi.HttpError e)
	{
		if (e.status == 404) loadGroups();
		plugin.ui(s -> s.partiesView.groupActionFailed(TsgHubFormat.friendlyError(e)));
	}

	void onSharingDisabled()
	{
		if (inGroup()) leave();
	}

	private void forget()
	{
		group = null;
		plugin.session().set(GROUP_TOKEN, "");
		plugin.session().set(GROUP_PASSPHRASE, "");
		plugin.session().set(GROUP_PLAYER, "");
	}

	@Override public void memberUpdated(PartyPlayer player, boolean self) { parties(v -> v.groupMemberUpdated(player, self)); }

	@Override public void memberRemoved(PartyPlayer player) { parties(v -> v.groupMemberRemoved(player)); }

	List<String> liveAreas()
	{
		GroupTracker t = tracker;
		return t == null ? java.util.Collections.emptyList() : t.areas();
	}

	void autoRefresh()
	{
		TsgHubSidebarPanel s = sidebar.get();
		if (s != null && s.wantsGroups()) loadGroups(true);
	}

	@Override public void areasChanged() { parties(v -> v.partyAreasChanged()); }

	@Override public void membersCleared() { parties(v -> v.groupMembersCleared()); }

	private void parties(Consumer<TsgHubPartiesView> action)
	{
		TsgHubSidebarPanel s = sidebar.get();
		if (s != null) action.accept(s.partiesView);
	}

	@Override
	public void partyChanged(String passphrase)
	{
		// Switching parties elsewhere also leaves the group.
		if (inGroup() && !isGroupParty(passphrase)) executor.submit(this::leave);
	}

	private JsonObject identity()
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("displayName", plugin.clan().playerName());
		payload.addProperty("clanName", plugin.clan().name());
		payload.addProperty("world", client.getWorld());
		payload.addProperty("area", plugin.currentArea());
		return payload;
	}

	private void status(String message, Tone tone)
	{
		plugin.ui(s -> s.setStatus(message, tone));
	}

	private void busy(boolean isBusy)
	{
		plugin.ui(s -> s.setBusy(isBusy));
	}

	static String partyTitle(JsonObject group)
	{
		String title = str(group, "activity");
		if (!title.isEmpty()) return title;
		Map.Entry<String, Integer> area = areaSummary(array(group, "members"));
		if (area != null) return area.getKey();
		String leader = str(group, "leaderName");
		return leader.isEmpty() ? "Party" : leader + "'s party";
	}

	static Map.Entry<String, Integer> areaSummary(JsonArray members)
	{
		List<String> areas = new ArrayList<>();
		for (JsonObject member : objects(members)) areas.add(str(member, "area"));
		return areaSummary(areas);
	}

	static Map.Entry<String, Integer> areaSummary(List<String> areas)
	{
		Map<String, Integer> counts = new LinkedHashMap<>();
		int low = Integer.MAX_VALUE;
		int high = 0;
		for (String area : areas)
		{
			if (area == null || area.isEmpty()) continue;
			if (area.startsWith(WILDERNESS))
			{
				try
				{
					int level = Integer.parseInt(area.substring(WILDERNESS.length()).trim());
					low = Math.min(low, level);
					high = Math.max(high, level);
					area = "Wilderness";
				}
				catch (NumberFormatException ignored) { }
			}
			counts.merge(area, 1, Integer::sum);
		}
		if (counts.isEmpty()) return null;
		Map.Entry<String, Integer> top = Collections.max(counts.entrySet(), Map.Entry.comparingByValue());
		String name = top.getKey();
		if (name.equals("Wilderness") && high > 0) name += " lvl " + (low == high ? String.valueOf(low) : low + "-" + high);
		return new AbstractMap.SimpleImmutableEntry<>(name, top.getValue());
	}
}

package com.tsghub;

import static com.tsghub.TsgHubHtml.*;
import static com.tsghub.TsgHubTheme.*;
import static com.tsghub.TsgHubUi.*;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.api.Experience;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.hiscore.HiscoreEndpoint;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;
import net.runelite.client.hiscore.Skill;
import net.runelite.client.util.ImageUtil;

final class TsgHubHiscores
{
	static final List<HiscoreSkill> SKILL_GRID = PlayerSkillsPanel.SKILL_ORDER.stream()
		.map(skill -> HiscoreSkill.valueOf(skill.name()))
		.collect(Collectors.toList());
	private static final int ICON = 16;
	private static final Map<HiscoreSkill, BufferedImage> SKILL_ICONS = new EnumMap<>(HiscoreSkill.class);

	private TsgHubHiscores()
	{
	}

	static HiscoreEndpoint endpoint(int accountType)
	{
		switch (accountType)
		{
			case 1: return HiscoreEndpoint.IRONMAN;
			case 2: return HiscoreEndpoint.ULTIMATE_IRONMAN;
			case 3: return HiscoreEndpoint.HARDCORE_IRONMAN;
			default: return HiscoreEndpoint.NORMAL;
		}
	}

	static int level(HiscoreResult result, HiscoreSkill skill)
	{
		Skill entry = result.getSkill(skill);
		return entry == null ? -1 : entry.getLevel();
	}

	static int combatLevel(HiscoreResult result)
	{
		return Experience.getCombatLevel(
			Math.max(1, level(result, HiscoreSkill.ATTACK)),
			Math.max(1, level(result, HiscoreSkill.STRENGTH)),
			Math.max(1, level(result, HiscoreSkill.DEFENCE)),
			Math.max(10, level(result, HiscoreSkill.HITPOINTS)),
			Math.max(1, level(result, HiscoreSkill.MAGIC)),
			Math.max(1, level(result, HiscoreSkill.RANGED)),
			Math.max(1, level(result, HiscoreSkill.PRAYER)));
	}

	static List<HiscoreSkill> scored(HiscoreResult result, HiscoreSkillType type)
	{
		List<HiscoreSkill> out = new ArrayList<>();
		for (HiscoreSkill skill : HiscoreSkill.values())
			if (skill.getType() == type && level(result, skill) > 0) out.add(skill);
		out.sort(Comparator.comparing(TsgHubHiscores::sortName, String.CASE_INSENSITIVE_ORDER));
		return out;
	}

	private static String sortName(HiscoreSkill skill)
	{
		String name = skill.getName();
		return name.regionMatches(true, 0, "The ", 0, 4) ? name.substring(4) : name;
	}

	static String subtitle(HiscoreResult result)
	{
		int total = level(result, HiscoreSkill.OVERALL);
		return "Combat " + combatLevel(result) + (total > 0 ? " · Total " + TsgHubFormat.number(total) : "");
	}

	static JPanel skillGrid(HiscoreResult result)
	{
		JPanel grid = new JPanel(new GridLayout(0, 3, GAP_XS, GAP_XS));
		grid.setOpaque(false);
		grid.setAlignmentX(0f);
		for (HiscoreSkill skill : SKILL_GRID) grid.add(skillCell(result, skill));
		return fitHeight(grid);
	}

	private static JPanel skillCell(HiscoreResult result, HiscoreSkill skill)
	{
		JPanel cell = card();
		cell.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
		int level = level(result, skill);
		JLabel label = label(level > 0 ? String.valueOf(level) : "--", level >= 99 ? WARNING : TEXT, boldFont());
		label.setIcon(skillIcon(skill));
		label.setIconTextGap(6);
		cell.add(label, BorderLayout.CENTER);
		cell.setToolTipText(skillTip(result.getSkill(skill), skill.getName()));
		return cell;
	}

	static JPanel totalRow(HiscoreResult result)
	{
		JPanel row = card();
		Skill overall = result.getSkill(HiscoreSkill.OVERALL);
		int total = overall == null ? -1 : overall.getLevel();
		JLabel left = label("Total " + (total > 0 ? TsgHubFormat.number(total) : "--"), TEXT, boldFont());
		left.setIcon(skillIcon(HiscoreSkill.OVERALL));
		left.setIconTextGap(6);
		row.add(left, BorderLayout.CENTER);
		if (overall != null && overall.getExperience() > 0)
			row.add(label(TsgHubFormat.number(overall.getExperience()) + " xp", MUTED, smallFont()), BorderLayout.EAST);
		row.setToolTipText(skillTip(overall, "Overall"));
		return fitHeight(row);
	}

	static JPanel scoreRow(HiscoreResult result, HiscoreSkill skill, SpriteManager sprites)
	{
		JPanel row = card();
		row.setBorder(BorderFactory.createEmptyBorder(3, 7, 3, 7));
		JLabel name = shrinkable(label(skill.getName(), TEXT, smallFont()));
		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(ICON, ICON));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		if (skill.getSpriteId() > 0)
		{
			sprites.getSpriteAsync(skill.getSpriteId(), 0, sprite -> SwingUtilities.invokeLater(() ->
				icon.setIcon(new ImageIcon(ImageUtil.resizeImage(ImageUtil.resizeCanvas(sprite, 25, 25), ICON, ICON)))));
		}
		row.add(icon, BorderLayout.WEST);
		row.add(name, BorderLayout.CENTER);
		row.add(label(TsgHubFormat.number(level(result, skill)), ACCENT, smallFont()), BorderLayout.EAST);
		row.setToolTipText(skillTip(result.getSkill(skill), skill.getName()));
		return fitHeight(row);
	}

	private static String skillTip(Skill skill, String name)
	{
		if (skill == null || skill.getRank() <= 0) return "<html><b>" + escape(name) + "</b><br>Not ranked</html>";
		String detail = skill.getExperience() >= 0 ? "XP: " + TsgHubFormat.number(skill.getExperience()) + "<br>" : "";
		return "<html><b>" + escape(name) + "</b><br>" + detail + "Rank: " + TsgHubFormat.number(skill.getRank()) + "</html>";
	}

	private static synchronized ImageIcon skillIcon(HiscoreSkill skill)
	{
		BufferedImage image = SKILL_ICONS.computeIfAbsent(skill, s -> ImageUtil.loadImageResource(TsgHubHiscores.class, "/skill_icons_small/" + s.name().toLowerCase() + ".png"));
		return image == null ? null : new ImageIcon(image);
	}
}

package com.tsghub;

import static com.tsghub.TsgHubHtml.*;
import static com.tsghub.TsgHubIcons.*;
import static com.tsghub.TsgHubTheme.*;
import static com.tsghub.TsgHubUi.*;

import com.tsghub.TsgHubSidebarPanel.View;
import java.awt.Component;
import java.awt.GridLayout;
import java.util.Arrays;
import java.util.List;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;

final class TsgHubHomeView
{
	private final TsgHubPlugin plugin;
	private final TsgHubSidebarPanel shell;

	boolean homeBuilt;
	private String update;
	private final List<Section> sections;

	TsgHubHomeView(TsgHubPlugin plugin, TsgHubSidebarPanel shell)
	{
		this.plugin = plugin;
		this.shell = shell;
		sections = Arrays.asList(
			new Section("Events", icon("calendar", ACCENT), () -> shell.eventsView.openEvents(), () -> shell.eventsView.eventsSummary(), () -> shell.eventsView.liveEvents() > 0),
			new Section("Parties", icon("party", ACCENT), () -> shell.partiesView.showParties(), () -> shell.partiesView.partiesSummary(), () -> plugin.groups().inGroup()),
			new Section("Members", icon("members", ACCENT), () -> shell.membersView.showMembers(), () -> shell.membersView.membersSummary(), () -> shell.membersView.onlineCount() > 0),
			new Section("Drops", icon("drops", ACCENT), () -> shell.dropsView.showDrops(), () -> "", () -> false),
			new Section("News", icon("news", ACCENT), () -> shell.newsView.showNews(), () -> shell.newsView.newsSummary(), () -> plugin.announcements().unreadCount() > 0));
	}

	private static final class Section
	{
		private final String name;
		private final Icon icon;
		private final Runnable open;
		private final Supplier<String> summary;
		private final BooleanSupplier live;
		private JLabel summaryLabel;
		private boolean half;

		Section(String name, Icon icon, Runnable open, Supplier<String> summary, BooleanSupplier live)
		{
			this.name = name;
			this.icon = icon;
			this.open = open;
			this.summary = summary;
			this.live = live;
		}
	}

	void showHome()
	{
		shell.setView(View.HOME);
		renderHome();
		plugin.groups().open();
		plugin.presence().open(true);
	}

	void renderHome()
	{
		if (homeBuilt)
		{
			for (Section section : sections) summarize(section);
			return;
		}
		shell.setHeader("TSG Hub", plugin.clan().playerName(), false, true);
		shell.page.removeAll();
		for (int i = 0; i < sections.size(); i += 2)
		{
			boolean pair = i + 1 < sections.size();
			JPanel row = panel(new GridLayout(1, pair ? 2 : 1, 6, 0));
			row.add(sectionTile(sections.get(i), pair));
			if (pair) row.add(sectionTile(sections.get(i + 1), true));
			addCard(shell.page, fitHeight(row));
		}
		if (update != null)
		{
			shell.page.add(gap(GAP_S));
			JLabel notice = label("Update available. Restart RuneLite.", WARNING, smallFont());
			notice.setHorizontalAlignment(JLabel.CENTER);
			notice.setToolTipText("Version " + update);
			shell.page.add(fitHeight(notice));
		}
		shell.refreshPage();
		homeBuilt = true;
	}

	void setUpdate(String version)
	{
		update = version;
		homeBuilt = false;
		if (shell.view == View.HOME) renderHome();
	}

	private JPanel sectionTile(Section section, boolean half)
	{
		JPanel tile = new JPanel();
		tile.setLayout(new BoxLayout(tile, BoxLayout.Y_AXIS));
		tile.setBackground(CARD);
		tile.setBorder(BorderFactory.createEmptyBorder(12, 6, 12, 6));
		JLabel icon = new JLabel(section.icon);
		JLabel name = boldLabel(section.name);
		JLabel summary = label("", MUTED, smallFont());
		section.summaryLabel = summary;
		section.half = half;
		summarize(section);
		tile.add(icon);
		tile.add(gap(GAP_M));
		tile.add(name);
		tile.add(gap(GAP_XS));
		tile.add(summary);
		for (Component part : tile.getComponents())
		{
			((JComponent) part).setAlignmentX(Component.CENTER_ALIGNMENT);
			if (part instanceof JLabel) ((JLabel) part).setHorizontalAlignment(JLabel.CENTER);
		}
		clickable(tile, section.open);
		return tile;
	}

	private void summarize(Section section)
	{
		String text = html("<div style='text-align:center'>" + escape(section.summary.get()) + "</div>", section.half ? 80 : 180);
		if (!text.equals(section.summaryLabel.getText())) section.summaryLabel.setText(text);
		section.summaryLabel.setForeground(section.live.getAsBoolean() ? SUCCESS : MUTED);
	}
}

package com.tsghub;

import static com.tsghub.PlayerNames.*;
import static com.tsghub.TsgHubTheme.*;
import static com.tsghub.TsgHubUi.*;
import static net.runelite.client.util.ColorUtil.toHexColor;

import java.awt.Color;
import javax.swing.text.html.HTML;

final class TsgHubHtml
{
	private TsgHubHtml()
	{
	}

	static String escape(String text)
	{
		return text == null ? "" : text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	// Swing HTML treats px as 1/72in but fonts render at 96dpi, so scale by 3/4.
	static String html(String innerHtml, int widthPx)
	{
		return "<html><body style='width:" + Math.round(widthPx * 0.75f) + "px'>" + innerHtml + "</body></html>";
	}

	private static final java.util.regex.Pattern URL = java.util.regex.Pattern.compile("https?://[^\\s<>\"']+");

	private static final int LINK_TEXT_MAX = 24;
	private static final java.util.regex.Pattern BULLET = java.util.regex.Pattern.compile("[-*•]\\s+(.+)");
	private static final java.util.regex.Pattern NUMBERED = java.util.regex.Pattern.compile("\\d{1,2}[.)]\\s+(.+)");
	private static final java.util.regex.Pattern HEADING = java.util.regex.Pattern.compile("(#{1,3})\\s+(.+)");
	private static final java.util.regex.Pattern RULE = java.util.regex.Pattern.compile("-{3,}|\\*{3,}|_{3,}");
	private static final java.util.regex.Pattern LINK = java.util.regex.Pattern.compile("\\[([^\\]]+)]\\((https?://[^\\s)]+)\\)|(https?://[^\\s<>\"']+)");
	private static final java.util.regex.Pattern LEAD_IN = java.util.regex.Pattern.compile("([^:/]{1,24}:)(\\s.*)");

	// Escapes plain text for HTML, keeps line breaks, and turns http(s) URLs into links. Long URLs show
	// shortened: Swing can't wrap inside one, and a long one widens the whole label past its wrap width.
	static String linkify(String text)
	{
		String raw = text == null ? "" : text;
		StringBuilder out = new StringBuilder();
		java.util.regex.Matcher matcher = URL.matcher(raw);
		int last = 0;
		while (matcher.find())
		{
			String url = matcher.group().replaceAll("[.,;:!?)]+$", "");
			out.append(escape(raw.substring(last, matcher.start())));
			out.append("<a href='").append(escape(url)).append("' style='color:").append(toHexColor(ACCENT)).append("'>")
				.append(escape(linkText(url))).append("</a>");
			last = matcher.start() + url.length();
		}
		out.append(escape(raw.substring(last)));
		return out.toString().replace("\n", "<br>");
	}

	static String postHtml(String text)
	{
		StringBuilder out = new StringBuilder();
		StringBuilder block = new StringBuilder();
		String kind = "";
		for (String line : (text == null ? "" : text).split("\n", -1))
		{
			String trimmed = line.trim();
			java.util.regex.Matcher bullet = BULLET.matcher(trimmed);
			java.util.regex.Matcher numbered = NUMBERED.matcher(trimmed);
			java.util.regex.Matcher heading = HEADING.matcher(trimmed);
			String next = trimmed.isEmpty() || heading.matches() || RULE.matcher(trimmed).matches() ? ""
				: bullet.matches() ? "ul" : numbered.matches() ? "ol" : trimmed.startsWith(">") ? "quote" : "p";
			if (!next.equals(kind)) flushBlock(out, block, kind);
			kind = next;
			if (heading.matches())
			{
				boolean big = heading.group(1).length() == 1;
				int top = out.length() == 0 ? 0 : 6;
				out.append("<p style='margin:0;margin-top:").append(top).append("px'>").append(big ? "<font size='+1'>" : "").append("<b>")
					.append(inline(heading.group(2))).append("</b>").append(big ? "</font>" : "").append("</p>");
			}
			else if (RULE.matcher(trimmed).matches()) out.append("<p style='margin:0;margin-top:6px;border-top:1px solid ").append(toHexColor(MUTED.darker())).append("'></p>");
			else if (next.equals("ul")) block.append("<li>").append(leadIn(bullet.group(1))).append("</li>");
			else if (next.equals("ol")) block.append("<li>").append(leadIn(numbered.group(1))).append("</li>");
			else if (!next.isEmpty())
			{
				if (block.length() > 0) block.append("<br>");
				block.append(inline(next.equals("quote") ? trimmed.substring(1).trim() : trimmed));
			}
		}
		flushBlock(out, block, kind);
		return out.toString();
	}

	private static void flushBlock(StringBuilder out, StringBuilder block, String kind)
	{
		if (block.length() == 0) return;
		String top = "margin-top:" + (out.length() == 0 ? 0 : 4) + "px";
		if (kind.equals("ul") || kind.equals("ol"))
			out.append("<").append(kind).append(" style='margin-left:").append(kind.equals("ol") ? 16 : 10).append("px;margin-bottom:0;").append(top).append("'>")
				.append(block).append("</").append(kind).append(">");
		else if (kind.equals("quote"))
			out.append("<p style='margin:0;").append(top).append(";margin-left:4px;padding-left:6px;border-left:2px solid ").append(toHexColor(MUTED))
				.append(";color:").append(toHexColor(MUTED)).append("'>").append(block).append("</p>");
		else out.append("<p style='margin:0;").append(top).append("'>").append(block).append("</p>");
		block.setLength(0);
	}

	private static String leadIn(String item)
	{
		java.util.regex.Matcher lead = LEAD_IN.matcher(item);
		return lead.matches() ? "<b>" + inline(lead.group(1)) + "</b>" + inline(lead.group(2)) : inline(item);
	}

	private static String inline(String raw)
	{
		StringBuilder out = new StringBuilder();
		java.util.regex.Matcher matcher = LINK.matcher(raw);
		int last = 0;
		while (matcher.find())
		{
			String url = matcher.group(2) != null ? matcher.group(2) : matcher.group(3).replaceAll("[.,;:!?)]+$", "");
			String shown = matcher.group(1) != null ? emphasis(escape(matcher.group(1))) : escape(linkText(url));
			out.append(emphasis(escape(raw.substring(last, matcher.start()))));
			out.append("<a href='").append(escape(url)).append("' style='color:").append(toHexColor(ACCENT)).append("'>").append(shown).append("</a>");
			last = matcher.group(2) != null ? matcher.end() : matcher.start() + url.length();
		}
		return out.append(emphasis(escape(raw.substring(last)))).toString();
	}

	private static String emphasis(String text)
	{
		return text.replaceAll("\\*\\*(?=\\S)(.+?)(?<=\\S)\\*\\*", "<b>$1</b>")
			.replaceAll("__(?=\\S)(.+?)(?<=\\S)__", "<u>$1</u>")
			.replaceAll("~~(?=\\S)(.+?)(?<=\\S)~~", "<strike>$1</strike>")
			.replaceAll("(?<![*\\w])\\*(?=\\S)(.+?)(?<=\\S)\\*(?![*\\w])", "<i>$1</i>")
			.replaceAll("(?<![_\\w])_(?=\\S)(.+?)(?<=\\S)_(?![_\\w])", "<i>$1</i>");
	}

	static String linkText(String url)
	{
		String shown = url.replaceFirst("^https?://(www\\.)?", "").replaceAll("/$", "");
		return shown.length() > LINK_TEXT_MAX ? shown.substring(0, LINK_TEXT_MAX - 3) + "..." : shown;
	}

	static String nameHtml(String name, String self)
	{
		return samePlayer(name, self) ? selfName(escape(name)) : escape(name);
	}

	static String tipSection(boolean first, String heading)
	{
		return "<div style='margin-top:" + (first ? 0 : 6) + "px'>" + heading + "</div>";
	}

	static String tipCard(Color bar, String inner)
	{
		return "<table cellspacing='0' cellpadding='0' width='100%' style='margin-top:2px'><tr><td bgcolor='" + toHexColor(bar) + "' width='2'></td>"
			+ "<td bgcolor='" + toHexColor(CARD_HOVER) + "' style='padding:3px 6px'>" + inner + "</td></tr></table>";
	}

	static String tipLine(Color color, String html)
	{
		return "<font color='" + toHexColor(color) + "'>" + html + "</font>";
	}
}

package com.tsghub;

import static com.tsghub.TsgHubTheme.*;

import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics2D;
import java.awt.Graphics;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.swing.AbstractButton;
import javax.swing.Icon;
import javax.swing.Timer;
import net.runelite.client.util.ImageUtil;

final class TsgHubIcons
{
	private TsgHubIcons()
	{
	}

	static Glyph icon(String name, Color color)
	{
		return icon(name, color, 0);
	}

	static Glyph icon(String name, Color color, int height)
	{
		BufferedImage mask = mask(name);
		return new Glyph(ImageUtil.fillImage(mask, color), null, null, height, mask);
	}

	static Glyph hover(String name)
	{
		return hover(name, ACCENT);
	}

	static Glyph hover(String name, Color hover)
	{
		BufferedImage mask = mask(name);
		return new Glyph(ImageUtil.fillImage(mask, MUTED), ImageUtil.fillImage(mask, hover), ImageUtil.fillImage(mask, BORDER), 0, mask);
	}

	private static BufferedImage mask(String name)
	{
		return ImageUtil.loadImageResource(TsgHubIcons.class, "icons/" + name + ".png");
	}

	static final class Glyph implements Icon
	{
		private final BufferedImage normal;
		private final BufferedImage hover;
		private final BufferedImage disabled;
		private final int width;
		private final int height;
		double angle;
		private Timer timer;

		private Glyph(BufferedImage normal, BufferedImage hover, BufferedImage disabled, int height, BufferedImage mask)
		{
			this.normal = normal;
			this.hover = hover;
			this.disabled = disabled;
			this.height = height > 0 ? height : mask.getHeight() / 2;
			this.width = mask.getWidth() * this.height / mask.getHeight();
		}

		@Override public int getIconWidth() { return width; }
		@Override public int getIconHeight() { return height; }

		@Override
		public void paintIcon(Component component, Graphics graphics, int x, int y)
		{
			BufferedImage image = normal;
			if (hover != null && component != null && !component.isEnabled()) image = disabled;
			else if (hover != null && component instanceof AbstractButton && ((AbstractButton) component).getModel().isRollover()) image = hover;
			Graphics2D g = (Graphics2D) graphics.create();
			g.translate(x, y);
			g.rotate(angle, width / 2.0, height / 2.0);
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
			g.drawImage(image, 0, 0, width, height, null);
			g.dispose();
		}

		void setSpinning(boolean spinning, Component owner)
		{
			if (spinning)
			{
				if (timer == null) timer = new Timer(30, e -> { angle = (angle + Math.PI / 10) % (2 * Math.PI); owner.repaint(); });
				if (!timer.isRunning()) timer.start();
			}
			else if (timer != null)
			{
				timer.stop();
				angle = 0;
				owner.repaint();
			}
		}
	}
}

package com.tsghub;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.time.DateTimeException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;

final class TsgHubJson
{
	private TsgHubJson()
	{
	}

	static List<String> strings(JsonArray array)
	{
		List<String> out = new ArrayList<>();
		for (JsonElement element : array) if (element.isJsonPrimitive()) out.add(element.getAsString());
		return out;
	}

	static JsonObject byId(JsonArray items, String id)
	{
		if (items == null || id == null) return null;
		for (JsonObject item : objects(items)) if (id.equals(str(item, "id"))) return item;
		return null;
	}

	static String str(JsonObject object, String key)
	{
		if (object == null) return "";
		JsonElement value = object.get(key);
		return value != null && value.isJsonPrimitive() ? value.getAsString() : "";
	}

	static int integer(JsonObject object, String key, int fallback)
	{
		if (object == null || !object.has(key) || object.get(key).isJsonNull()) return fallback;
		try { return object.get(key).getAsInt(); }
		catch (RuntimeException ignored) { return fallback; }
	}

	static boolean bool(JsonObject object, String key)
	{
		if (object == null || !object.has(key) || object.get(key).isJsonNull()) return false;
		try { return object.get(key).getAsBoolean(); }
		catch (RuntimeException ignored) { return false; }
	}

	static JsonArray array(JsonObject object, String key)
	{
		return object != null && object.has(key) && object.get(key).isJsonArray() ? object.getAsJsonArray(key) : new JsonArray();
	}

	static Instant instant(String iso)
	{
		try { return iso == null || iso.isEmpty() ? null : Instant.parse(iso); }
		catch (DateTimeException e) { return null; }
	}

	static long longValue(JsonObject object, String key, long fallback)
	{
		if (object == null || !object.has(key) || object.get(key).isJsonNull()) return fallback;
		try { return object.get(key).getAsLong(); }
		catch (RuntimeException ignored) { return fallback; }
	}

	static JsonObject object(JsonObject object, String key)
	{
		return object != null && object.has(key) && object.get(key).isJsonObject() ? object.getAsJsonObject(key) : new JsonObject();
	}

	static List<JsonObject> objects(JsonArray array)
	{
		List<JsonObject> objects = new ArrayList<>();
		for (JsonElement element : array) objects.add(element.getAsJsonObject());
		return objects;
	}
}

package com.tsghub;

import com.google.gson.JsonObject;
import com.tsghub.TsgHubUi.Tone;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.swing.SwingUtilities;
import lombok.RequiredArgsConstructor;
import net.runelite.client.config.ConfigManager;

@RequiredArgsConstructor
final class TsgHubKeys
{
	private final TsgHubPlugin plugin;
	private final TsgHubConfig config;
	private final ConfigManager configManager;
	private final ScheduledExecutorService executor;
	private final TsgHubBackoff backoff = new TsgHubBackoff(30_000, 300_000);
	private volatile boolean verified;
	private volatile String checkedIdentity = "";
	private volatile String rejected = "";
	private volatile boolean announce;
	private ScheduledFuture<?> retry;
	private volatile String deviceCode = "";
	private volatile long linkDeadline;
	private volatile boolean linkStarting;
	private volatile ScheduledFuture<?> linkPoll;

	boolean verified()
	{
		return verified;
	}

	String adminKey()
	{
		return verified ? configured() : "";
	}

	boolean needsLink()
	{
		String key = configured();
		return key.isEmpty() || key.equals(rejected);
	}

	long linkDeadline()
	{
		return deviceCode.isEmpty() ? 0 : linkDeadline;
	}

	boolean linkStarting()
	{
		return linkStarting;
	}

	void startLink()
	{
		if (linkStarting || linkDeadline() > System.currentTimeMillis() || executor.isShutdown()) return;
		stopLink();
		linkStarting = true;
		JsonObject body = new JsonObject();
		body.addProperty("clanName", plugin.clan().name());
		plugin.api().call("POST", "/v1/auth/start", null, body).whenCompleteAsync(TsgHubApi.handle(response -> {
			String code = TsgHubJson.str(response, "deviceCode");
			String command = TsgHubJson.str(response, "command");
			if (code.isEmpty() || command.isEmpty()) throw new IllegalStateException("The server didn't return a link code.");
			linkDeadline = System.currentTimeMillis() + Math.max(60, TsgHubJson.integer(response, "expiresIn", 600)) * 1000L;
			deviceCode = code;
			scheduleLinkPoll(code, Math.max(2, TsgHubJson.integer(response, "interval", 5)));
			SwingUtilities.invokeLater(() -> TsgHubUi.copyToClipboard(command));
			plugin.memberStatus("Copied " + command + ". Paste it in the clan Discord to link.", Tone.SUCCESS);
			plugin.joinDiscord(e -> plugin.memberError("Copied " + command + ", but couldn't open the Discord invite. ", e));
		}, e -> plugin.memberError("Couldn't start linking. ", e), () -> {
			linkStarting = false;
			plugin.discordLinkChanged();
		}), executor);
	}

	void cancelLink()
	{
		stopLink();
		plugin.discordLinkChanged();
	}

	private void stopLink()
	{
		deviceCode = "";
		ScheduledFuture<?> pending = linkPoll;
		if (pending != null) pending.cancel(false);
		linkPoll = null;
	}

	private void scheduleLinkPoll(String code, int seconds)
	{
		if (!executor.isShutdown()) linkPoll = executor.schedule(() -> pollLink(code, seconds), seconds, TimeUnit.SECONDS);
	}

	private void pollLink(String code, int seconds)
	{
		if (!code.equals(deviceCode)) return;
		if (System.currentTimeMillis() > linkDeadline)
		{
			linkExpired();
			return;
		}
		JsonObject body = new JsonObject();
		body.addProperty("deviceCode", code);
		plugin.api().call("POST", "/v1/auth/poll", null, body).whenCompleteAsync((response, error) -> {
			if (!code.equals(deviceCode)) return;
			try
			{
				JsonObject result = TsgHubApi.result(response, error);
				String status = TsgHubJson.str(result, "status");
				if ("complete".equals(status))
				{
					stopLink();
					String key = TsgHubJson.str(result, "key");
					if (key.isEmpty()) plugin.memberStatus("Linking didn't finish. Click Link Discord to try again.", Tone.ERROR);
					else configManager.setConfiguration("tsghub", "hubKey", key);
					plugin.discordLinkChanged();
					return;
				}
				if ("expired".equals(status))
				{
					linkExpired();
					return;
				}
			}
			catch (Exception ignored) { }
			scheduleLinkPoll(code, seconds);
		}, executor);
	}

	private void linkExpired()
	{
		stopLink();
		plugin.memberStatus("The link code expired. Click Link Discord to try again.", Tone.ERROR);
		plugin.discordLinkChanged();
	}

	private String configured()
	{
		String key = config.hubKey();
		return key == null ? "" : key.trim();
	}

	void check()
	{
		String key = configured();
		TsgHubClan clan = plugin.clan();
		String name = clan.playerName();
		if (key.isEmpty())
		{
			checkedIdentity = "";
			if (verified) setVerified(false);
			return;
		}
		if (name.isEmpty() || !plugin.sharingInClan()) return;
		String hash = clan.accountHash();
		String identity = key + "\n" + name + "\n" + hash;
		if (identity.equals(checkedIdentity) || key.equals(rejected) || executor.isShutdown()) return;
		checkedIdentity = identity;
		String query = "/v1/me?displayName=" + TsgHubApi.encode(name) + (hash.isEmpty() ? "" : "&accountHash=" + hash);
		plugin.api().call("GET", query, key, null).whenCompleteAsync((response, error) -> {
			try
			{
				JsonObject result = TsgHubApi.result(response, error);
				if (!identity.equals(checkedIdentity)) return;
				backoff.reset();
				boolean admin = grantsAdmin(result);
				if (admin != verified) setVerified(admin);
				String linkError = TsgHubJson.str(result, "linkError");
				boolean linked = TsgHubJson.bool(result, "linked");
				if (!linkError.isEmpty()) plugin.memberStatus(linkError, Tone.ERROR);
				else if (announce && linked) plugin.memberStatus(admin ? "Hub key accepted. Your Discord account is linked and the admin site button is unlocked." : "Hub key accepted. Your Discord account is linked.", Tone.SUCCESS);
				if (linked || !linkError.isEmpty()) announce = false;
				if (!linked && hash.isEmpty()) retry(identity);
			}
			catch (TsgHubApi.HttpError e)
			{
				if (e.status == 401) rejected(key);
				else retry(identity);
			}
			catch (Exception e) { retry(identity); }
		}, executor);
	}

	static boolean grantsAdmin(JsonObject me)
	{
		String role = TsgHubJson.str(me, "role");
		return role.isEmpty() || "admin".equals(role);
	}

	private void retry(String identity)
	{
		if (!identity.equals(checkedIdentity)) return;
		checkedIdentity = "";
		if (!executor.isShutdown()) retry = executor.schedule(this::check, backoff.next(), TimeUnit.MILLISECONDS);
	}

	void recheck(String key)
	{
		if (!key.equals(configured())) return;
		checkedIdentity = "";
		if (verified) setVerified(false);
		check();
	}

	void rejected(String key)
	{
		if (!key.equals(configured())) return;
		rejected = key;
		announce = false;
		setVerified(false);
		plugin.discordLinkChanged();
		plugin.memberStatus("Your hub key wasn't accepted. It may have expired or been revoked. Click Link Discord on the home screen to link again.", Tone.ERROR);
	}

	void keyChanged()
	{
		if (!configured().isEmpty()) stopLink();
		checkedIdentity = "";
		rejected = "";
		backoff.reset();
		announce = !configured().isEmpty();
		if (verified) setVerified(false);
		check();
	}

	void revoke()
	{
		checkedIdentity = "";
		if (verified) setVerified(false);
	}

	void cancelRetry()
	{
		ScheduledFuture<?> pending = retry;
		if (pending != null) pending.cancel(false);
		retry = null;
		stopLink();
	}

	void loggedOut()
	{
		verified = false;
		checkedIdentity = "";
	}

	void reset()
	{
		verified = false;
		checkedIdentity = "";
		rejected = "";
		backoff.reset();
		announce = false;
	}

	private void setVerified(boolean value)
	{
		verified = value;
		plugin.accessChanged();
	}
}

package com.tsghub;

import static com.tsghub.TsgHubSession.EVENT_ID;
import static com.tsghub.TsgHubSession.MEMBER_NAME;
import static com.tsghub.TsgHubSession.MEMBER_TOKEN;
import static com.tsghub.TsgHubSession.TOKEN;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import lombok.AllArgsConstructor;
import net.runelite.client.util.Filepath;
import okhttp3.OkHttpClient;

final class TsgHubLiveSync
{
	@AllArgsConstructor
	private static final class Topic
	{
		final BiConsumer<JsonObject, String> snapshot;
		final Consumer<String> changed;
	}

	private final TsgHubPlugin plugin;
	private final ScheduledExecutorService executor;
	private final Gson gson;
	private final TsgHubSocket socket;
	private final Map<String, Topic> topics = new HashMap<>();
	private volatile Filepath rulesCache;

	TsgHubLiveSync(TsgHubPlugin plugin, OkHttpClient http, Gson gson, String serviceUrl, ScheduledExecutorService executor)
	{
		this.plugin = plugin;
		this.executor = executor;
		this.gson = gson;
		socket = new TsgHubSocket(http, gson, serviceUrl, executor, new TsgHubSocket.Listener()
		{
			@Override public void onReady(String rulesVersion)
			{
				refreshRules(rulesVersion);
				plugin.signals().resend();
				plugin.reports().resend();
			}
			@Override public void onRulesChanged(String version) { refreshRules(version); }
			@Override public void onChanged(String topic, String eventId) { changed(topic, eventId); }
			@Override public void onAdminRevoked(String token) { plugin.keys().recheck(token); }
			@Override public void onAnnouncement(String text) { plugin.chat().announce(text); }
			@Override public void onUpdateAvailable(String version) { plugin.chat().updateAvailable(version); }
			@Override public void onSnapshot(JsonObject message) { snapshot(message); }
			@Override public void onConnection(TsgHubSocket.State state) { plugin.ui(s -> s.setConnection(state)); }
			@Override public void onAck(String id)
			{
				plugin.signals().acked(id);
				plugin.reports().acked(id);
			}
			@Override public void onRejected(String id, int status) { plugin.reports().failed(id, status); }
			@Override public void onSubscribed() { plugin.signals().resend(); }
			@Override public void onReply(JsonObject message) { plugin.chat().reply(message); }
			@Override public void onXpRequest(String skills) { plugin.tracker().reportXp(skills); }
			@Override public void onScreenshotRequest(String id, String token) { plugin.drops().sendScreenshot(id, token); }
			@Override public void onGroupHeartbeat(JsonObject message) { plugin.groups().beaten(message); }
			@Override public void onGroupRejected(int status) { plugin.groups().beatRejected(status); }
		});
		topics.put("groups", new Topic((data, eventId) -> plugin.groups().apply(TsgHubJson.array(data, "groups")), eventId -> plugin.groups().autoRefresh()));
		topics.put("presence", new Topic(this::presence, eventId -> plugin.presence().autoRefresh()));
		topics.put("positions", new Topic((data, eventId) -> plugin.memberMap().apply(TsgHubJson.array(data, "members")), eventId -> { }));
		topics.put("drops", new Topic((data, eventId) -> plugin.drops().onSnapshot(TsgHubJson.array(data, "drops")), eventId -> plugin.drops().autoRefresh()));
		topics.put("announcements", new Topic((data, eventId) -> plugin.announcements().apply(TsgHubJson.array(data, "announcements")), eventId -> plugin.announcements().load()));
		topics.put("events", new Topic((data, eventId) -> plugin.sessions().applyClanEvents(TsgHubJson.array(data, "events")), eventId -> plugin.sessions().loadClanEvents()));
		topics.put("notifications", new Topic((data, eventId) -> {
			if (isActiveEvent(eventId)) plugin.chat().notifications(TsgHubJson.array(data, "notifications"));
		}, eventId -> {
			if (isActiveEvent(eventId)) plugin.sessions().pollNotifications();
		}));
		topics.put("event", new Topic(this::eventSnapshot, this::eventChanged));
	}

	TsgHubSocket socket()
	{
		return socket;
	}

	boolean live()
	{
		return socket.isLive();
	}

	Runnable unlessLive(Runnable poll)
	{
		return () -> {
			if (!socket.isLive()) poll.run();
		};
	}

	void syncNow()
	{
		if (executor.isShutdown()) return;
		executor.execute(this::tick);
	}

	void tick()
	{
		TsgHubReports reports = plugin.reports();
		if (!plugin.sharingEnabled()) reports.clear();
		reports.flush();
		if (!plugin.sharingInClan())
		{
			socket.disconnect();
			return;
		}
		TsgHubClan clan = plugin.clan();
		TsgHubSession session = plugin.session();
		TsgHubSidebarPanel sidebar = plugin.sidebar();
		socket.connect(clan.name());
		Map<String, String> tokens = new HashMap<>();
		String eventId = session.get(EVENT_ID);
		String token = session.get(TOKEN);
		if (!eventId.isEmpty() && !token.isEmpty()) tokens.put(eventId, token);
		String competitionId = sidebar == null ? null : sidebar.competitionView.openCompetitionId();
		String memberToken = competitionId == null ? "" : session.get(MEMBER_TOKEN + competitionId);
		if (!memberToken.isEmpty()) tokens.putIfAbsent(competitionId, memberToken);
		for (String joinedId : plugin.sessions().joinedCompetitions())
		{
			String joinedToken = session.get(MEMBER_TOKEN + joinedId);
			if (!joinedToken.isEmpty()) tokens.putIfAbsent(joinedId, joinedToken);
		}
		socket.sync(tokens, clan.inClanChat());
		socket.admin(plugin.keys().adminKey());
		socket.watch(watched(sidebar, competitionId));
		plugin.signals().flush(tokens);
	}

	private Set<String> watched(TsgHubSidebarPanel sidebar, String competitionId)
	{
		Set<String> watched = new HashSet<>();
		watched.add("events");
		watched.add("announcements");
		watched.add("notifications");
		if (sidebar == null) return watched;
		TsgHubMemberMap memberMap = plugin.memberMap();
		if (memberMap != null && memberMap.isOpen()) watched.add("positions");
		if (sidebar.wantsGroups()) watched.add("groups");
		if (sidebar.wantsMembers()) watched.add("presence");
		if (sidebar.wantsDrops()) watched.add("drops");
		String eventId = plugin.session().get(EVENT_ID);
		if (sidebar.wantsAutoRefresh() && !eventId.isEmpty()) watched.add("event:" + eventId);
		if (competitionId != null) watched.add("event:" + competitionId);
		return watched;
	}

	private void snapshot(JsonObject message)
	{
		Topic topic = topics.get(TsgHubJson.str(message, "topic"));
		if (topic != null) topic.snapshot.accept(TsgHubJson.object(message, "data"), TsgHubJson.str(message, "eventId"));
	}

	private void changed(String name, String eventId)
	{
		Topic topic = topics.get(name);
		if (topic != null) topic.changed.accept(eventId);
	}

	private void presence(JsonObject data, String eventId)
	{
		if (data.has("delta"))
		{
			plugin.presence().applyDelta(data.has("presence") ? TsgHubJson.object(data, "presence") : null, data.has("members") ? TsgHubJson.object(data, "members") : null);
			return;
		}
		if (!data.has("presence") || !data.get("presence").isJsonObject()) return;
		JsonObject notes = data.has("members") && data.get("members").isJsonObject() ? data.getAsJsonObject("members") : null;
		plugin.presence().apply(TsgHubJson.array(data.getAsJsonObject("presence"), "members"), notes == null ? null : TsgHubJson.array(notes, "members"));
	}

	private void eventSnapshot(JsonObject data, String eventId)
	{
		if (!data.has("event") || !data.get("event").isJsonObject()) return;
		JsonObject event = data.getAsJsonObject("event");
		TsgHubSidebarPanel sidebar = plugin.sidebar();
		if (sidebar == null) return;
		TsgHubSession session = plugin.session();
		if (isActiveEvent(eventId) && sidebar.wantsAutoRefresh()) plugin.sessions().applyBoard(eventId, session.get(TOKEN), event, false);
		if (eventId.equals(sidebar.competitionView.openCompetitionId()))
		{
			String name = session.get(MEMBER_NAME + eventId);
			plugin.ui(s -> s.competitionView.showCompetition(event, name, false));
		}
	}

	private void eventChanged(String eventId)
	{
		TsgHubSidebarPanel sidebar = plugin.sidebar();
		if (sidebar == null) return;
		if (isActiveEvent(eventId) && sidebar.wantsAutoRefresh()) plugin.sessions().refreshBoard();
		if (eventId.equals(sidebar.competitionView.openCompetitionId())) plugin.sessions().openCompetition(eventId);
	}

	private boolean isActiveEvent(String eventId)
	{
		return eventId.equals(plugin.session().get(EVENT_ID));
	}

	private void refreshRules(String version)
	{
		if (version.isEmpty() || version.equals(TsgHubRules.get().version)) return;
		plugin.api().call("GET", "/v1/rules", null, null).thenAcceptAsync(rules -> TsgHubRules.save(rules, rulesCache), executor);
	}

	void loadCachedRules(Filepath cache)
	{
		rulesCache = cache;
		TsgHubRules.loadCached(cache, gson);
	}
}

package com.tsghub;

import static com.tsghub.TsgHubFormat.*;
import static com.tsghub.TsgHubTheme.*;
import static com.tsghub.TsgHubUi.*;

import com.tsghub.TsgHubSidebarPanel.View;
import java.util.List;
import javax.swing.SwingUtilities;
import lombok.RequiredArgsConstructor;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

@RequiredArgsConstructor
final class TsgHubLookupView
{
	private final TsgHubPlugin plugin;
	private final TsgHubSidebarPanel shell;

	private String lookupName = "";
	View lookupReturn = View.MEMBERS;
	private int lookupType;
	private HiscoreResult lookupResult;
	private String lookupError = "";
	private int lookupSeq;

	void showLookup(String name, int accountType)
	{
		lookupName = name;
		lookupType = accountType;
		if (shell.view != View.LOOKUP) lookupReturn = shell.view;
		shell.setView(View.LOOKUP);
		loadLookup();
	}

	void loadLookup()
	{
		int seq = ++lookupSeq;
		lookupResult = null;
		lookupError = "";
		renderLookup();
		shell.setBusy(true);
		plugin.lookupHiscores(lookupName, lookupType).whenComplete((result, error) -> SwingUtilities.invokeLater(() -> {
			shell.setBusy(false);
			if (seq != lookupSeq) return;
			lookupResult = result;
			lookupError = error != null ? friendlyError(error) : result == null ? "Not found" : "";
			if (shell.view == View.LOOKUP) renderLookup();
		}));
	}

	private void renderLookup()
	{
		HiscoreResult result = lookupResult;
		shell.setHeader(lookupName, result == null ? TsgHubHiscores.endpoint(lookupType).getName() + " hiscores" : TsgHubHiscores.subtitle(result), true, true);
		shell.page.removeAll();
		if (!lookupError.isEmpty())
		{
			shell.page.add("Not found".equals(lookupError)
				? shell.errorPanel("Not on the hiscores", lookupName + " isn't ranked on the " + TsgHubHiscores.endpoint(lookupType).getName() + " hiscores.")
				: shell.errorPanel("Lookup failed", lookupError));
		}
		else if (result == null)
		{
			shell.page.add(caption("Looking up " + lookupName + "..."));
		}
		else
		{
			shell.page.add(shell.sectionHeading("Skills", null));
			shell.page.add(TsgHubHiscores.skillGrid(result));
			shell.page.add(gap(GAP_XS));
			shell.page.add(TsgHubHiscores.totalRow(result));
			addScores("Bosses", result, HiscoreSkillType.BOSS);
			addScores("Activities", result, HiscoreSkillType.ACTIVITY);
		}
		shell.refreshPage();
	}

	private void addScores(String heading, HiscoreResult result, HiscoreSkillType type)
	{
		List<HiscoreSkill> scored = TsgHubHiscores.scored(result, type);
		if (scored.isEmpty()) return;
		shell.page.add(gap(GAP_L));
		shell.page.add(shell.sectionHeading(heading + " (" + scored.size() + ")", null));
		for (HiscoreSkill skill : scored)
		{
			shell.page.add(TsgHubHiscores.scoreRow(result, skill, plugin.sprites()));
			shell.page.add(gap(2));
		}
	}
}

package com.tsghub;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.worldmap.WorldMapOverlay;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;

final class TsgHubMapOverlay extends Overlay
{
	private static final int PAD = 5;
	private static final int ROW_GAP = 2;
	private static final int COLUMN_GAP = 10;
	private static final int OFFSET = 12;
	private static final Color CARD = new Color(0x1F, 0x1D, 0x22, 235);

	private final Client client;
	private final WorldMapOverlay worldMap;
	private final TsgHubMemberMap memberMap;

	TsgHubMapOverlay(Client client, WorldMapOverlay worldMap, TsgHubMemberMap memberMap)
	{
		this.client = client;
		this.worldMap = worldMap;
		this.memberMap = memberMap;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.MANUAL);
		setPriority(Math.nextUp(PRIORITY_HIGHEST));
		drawAfterInterface(InterfaceID.WORLDMAP);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!memberMap.isOpen()) return null;
		Point mouse = client.getMouseCanvasPosition();
		List<TsgHubMemberMap.Member> hovered = hovered(mouse);
		if (hovered == null) return null;
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics metrics = g.getFontMetrics();
		int nameWidth = 0;
		int worldWidth = 0;
		for (TsgHubMemberMap.Member m : hovered)
		{
			nameWidth = Math.max(nameWidth, metrics.stringWidth(m.name));
			worldWidth = Math.max(worldWidth, metrics.stringWidth(world(m)));
		}
		int row = metrics.getAscent() + ROW_GAP;
		int width = PAD * 2 + nameWidth + (worldWidth > 0 ? COLUMN_GAP + worldWidth : 0);
		int height = PAD * 2 + row * hovered.size() - ROW_GAP;
		Rectangle canvas = new Rectangle(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
		int x = Math.min(mouse.getX() + OFFSET, canvas.width - width - 1);
		int y = Math.min(mouse.getY() + OFFSET, canvas.height - height - 1);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(CARD);
		g.fillRoundRect(x, y, width, height, 6, 6);
		g.setColor(TsgHubTheme.ACCENT);
		g.drawRoundRect(x, y, width - 1, height - 1, 6, 6);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		int baseline = y + PAD + metrics.getAscent() - 1;
		for (TsgHubMemberMap.Member m : hovered)
		{
			g.setColor(TsgHubTheme.TEXT);
			g.drawString(m.name, x + PAD, baseline);
			String world = world(m);
			g.setColor(TsgHubTheme.MUTED);
			g.drawString(world, x + width - PAD - metrics.stringWidth(world), baseline);
			baseline += row;
		}
		return null;
	}

	private List<TsgHubMemberMap.Member> hovered(Point mouse)
	{
		if (mouse == null) return null;
		for (Map.Entry<WorldMapPoint, List<TsgHubMemberMap.Member>> entry : memberMap.groups().entrySet())
		{
			WorldMapPoint point = entry.getKey();
			if (point.isCurrentlyEdgeSnapped()) continue;
			Point at = worldMap.mapWorldPointToGraphicsPoint(point.getWorldPoint());
			BufferedImage image = point.getImage();
			if (at == null || image == null) continue;
			Point anchor = point.getImagePoint();
			int left = at.getX() - (anchor == null ? image.getWidth() / 2 : anchor.getX());
			int top = at.getY() - (anchor == null ? image.getHeight() / 2 : anchor.getY());
			if (new Rectangle(left, top, image.getWidth(), image.getHeight()).contains(mouse.getX(), mouse.getY())) return entry.getValue();
		}
		return null;
	}

	private static String world(TsgHubMemberMap.Member m)
	{
		return m.world > 0 ? "W" + m.world : "";
	}
}

package com.tsghub;

import static com.tsghub.TsgHubJson.*;
import static com.tsghub.TsgHubTheme.*;
import static com.tsghub.TsgHubUi.*;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.tsghub.TsgHubUi.Tone;
import java.awt.Component;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;

final class TsgHubMemberAdmin
{
	private final TsgHubPlugin plugin;
	private final TsgHubSidebarPanel shell;
	private final Feedback feedback;

	TsgHubMemberAdmin(TsgHubPlugin plugin, TsgHubSidebarPanel shell)
	{
		this.plugin = plugin;
		this.shell = shell;
		feedback = new Feedback()
		{
			@Override public void busy(boolean busy) { shell.setBusy(busy); }
			@Override public void status(String message, Tone tone) { shell.setStatus(message, tone); }
		};
	}

	void addNoteItems(JPopupMenu menu, JsonObject member)
	{
		String name = str(member, "displayName");
		String altOf = str(member, "altOf");
		String note = str(member, "note");
		boolean alt = TsgHubRoster.isAltRank(str(member, "rank"));
		int active = TsgHubRoster.activeWarnings(array(member, "warnings")).size();
		menu.addSeparator();
		JMenuItem edit = new JMenuItem(alt ? "Edit alt and admin note" : "Edit admin note");
		edit.addActionListener(e -> editNote(shell, plugin.presence(), name, alt, altOf, note, mainCandidates(name), feedback));
		menu.add(edit);
		menu.addSeparator();
		JMenuItem warn = new JMenuItem("Add warning...");
		warn.addActionListener(e -> addWarning(shell, plugin.presence(), name, active, feedback));
		menu.add(warn);
	}

	private List<String> mainCandidates(String alt)
	{
		Map<String, String> ranks = new LinkedHashMap<>();
		for (JsonArray list : new JsonArray[] {shell.membersView.members, shell.membersView.offlineMembers})
		{
			if (list == null) continue;
			for (JsonObject member : objects(list)) ranks.put(str(member, "displayName"), str(member, "rank"));
		}
		return mainCandidates(alt, ranks);
	}

	static final int MAX_NOTE_LENGTH = 500;
	static final int MAX_WARNING_LENGTH = 300;
	private static final int[] EXPIRY_DAYS = {30, 90, 0};

	interface Feedback
	{
		void busy(boolean busy);

		void status(String message, Tone tone);
	}

	static List<String> mainCandidates(String alt, Map<String, String> ranksByName)
	{
		List<String> names = new ArrayList<>();
		for (Map.Entry<String, String> entry : ranksByName.entrySet())
		{
			if (!PlayerNames.samePlayer(entry.getKey(), alt) && !TsgHubRoster.isAltRank(entry.getValue())) names.add(entry.getKey());
		}
		names.sort(String.CASE_INSENSITIVE_ORDER);
		return names;
	}

	static void editNote(Component parent, TsgHubPresence presence, String name, boolean alt, String altOf, String note, List<String> candidates,
		Feedback feedback)
	{
		TsgHubMemberPicker main = new TsgHubMemberPicker(candidates, altOf);
		JTextArea notes = new JTextArea(note, 4, 20);
		notes.setLineWrap(true);
		notes.setWrapStyleWord(true);
		JPanel form = stack();
		if (alt)
		{
			form.add(new JLabel("Alt of (main character)"));
			form.add(main);
			form.add(gap(GAP_M));
		}
		form.add(new JLabel("Admin note (only admins see this)"));
		form.add(new JScrollPane(notes));
		if (JOptionPane.showConfirmDialog(parent, form, name, JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE) != JOptionPane.OK_OPTION) return;
		String typed = main.getText();
		String nextMain = typed.equals(altOf) ? altOf : PlayerNames.resolveName(candidates, typed);
		String nextNote = notes.getText().trim();
		if (PlayerNames.samePlayer(nextMain, name))
		{
			feedback.status("A character can't be its own alt.", Tone.ERROR);
			return;
		}
		if (nextNote.length() > MAX_NOTE_LENGTH)
		{
			feedback.status("Keep the note to " + MAX_NOTE_LENGTH + " characters.", Tone.ERROR);
			return;
		}
		if (nextMain.equals(altOf) && nextNote.equals(note)) return;
		after(presence.saveNote(name, nextMain, nextNote), "Saved " + name + ".", feedback);
	}

	static void addWarning(Component parent, TsgHubPresence presence, String name, int active, Feedback feedback)
	{
		JTextArea reason = new JTextArea(3, 22);
		reason.setLineWrap(true);
		reason.setWrapStyleWord(true);
		JComboBox<String> expiry = new JComboBox<>(new String[] {"After 30 days", "After 90 days", "Never"});
		expiry.setAlignmentX(Component.LEFT_ALIGNMENT);
		JPanel form = stack();
		form.add(label(active == 0 ? name + " has no active warnings." : name + " has " + active + " active warning" + (active == 1 ? "." : "s."), MUTED, smallFont()));
		form.add(gap(GAP_M));
		form.add(new JLabel("Reason"));
		form.add(new JScrollPane(reason));
		form.add(gap(GAP_M));
		form.add(new JLabel("Expires"));
		form.add(expiry);
		form.add(gap(GAP_M));
		form.add(label("Only admins see warnings.", MUTED, smallFont()));
		Object[] options = {"Add warning", "Cancel"};
		if (JOptionPane.showOptionDialog(parent, form, "Warn " + name, JOptionPane.DEFAULT_OPTION, JOptionPane.PLAIN_MESSAGE, null, options, options[0]) != 0) return;
		String text = reason.getText().trim();
		if (text.isEmpty())
		{
			feedback.status("Add a reason for the warning.", Tone.ERROR);
			return;
		}
		if (text.length() > MAX_WARNING_LENGTH)
		{
			feedback.status("Keep the reason to " + MAX_WARNING_LENGTH + " characters.", Tone.ERROR);
			return;
		}
		after(presence.addWarning(name, text, EXPIRY_DAYS[expiry.getSelectedIndex()]), "Warned " + name + ".", feedback);
	}

	private static void after(CompletableFuture<?> write, String success, Feedback feedback)
	{
		feedback.busy(true);
		write.whenComplete((ignored, error) -> SwingUtilities.invokeLater(() -> {
			feedback.busy(false);
			if (error == null) feedback.status(success, Tone.SUCCESS);
			else feedback.status("Couldn't save. " + TsgHubFormat.friendlyError(error), Tone.ERROR);
		}));
	}
}

package com.tsghub;

