package com.tsghub;

import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BiPredicate;
import java.util.function.LongSupplier;
import lombok.extern.slf4j.Slf4j;

@Slf4j
final class TsgHubReports
{
	static final long RETRY_MILLIS = 10_000;

	interface Poster
	{
		void post(String method, String path, String token, JsonObject body) throws Exception;
	}

	private static final class Pending extends TsgHubOutbox.Item
	{
		final String type;
		final String method;
		final String path;
		final String token;
		final JsonObject body;
		long nextAt;
		boolean socketTried;

		Pending(String type, String method, String path, String token, JsonObject body, long now)
		{
			super(now);
			this.type = type;
			this.method = method;
			this.path = path;
			this.token = token;
			this.body = body;
			this.nextAt = now;
		}
	}

	private final BiPredicate<String, JsonObject> socket;
	private final Poster poster;
	private final LongSupplier clock;
	private final TsgHubOutbox<Pending> pending = new TsgHubOutbox<>();

	TsgHubReports(BiPredicate<String, JsonObject> socket, Poster poster)
	{
		this(socket, poster, System::currentTimeMillis);
	}

	TsgHubReports(BiPredicate<String, JsonObject> socket, Poster poster, LongSupplier clock)
	{
		this.socket = socket;
		this.poster = poster;
		this.clock = clock;
	}

	boolean send(String type, String path, JsonObject body)
	{
		return send(type, path, null, body);
	}

	boolean send(String type, String path, String token, JsonObject body)
	{
		return send(type, "POST", path, token, body);
	}

	synchronized boolean send(String type, String method, String path, String token, JsonObject body)
	{
		if (!body.has("id")) body.addProperty("id", TsgHubSignals.newId());
		long now = clock.getAsLong();
		Pending entry = new Pending(type, method, path, token, body, now);
		pending.add(body.get("id").getAsString(), entry);
		return sendSocket(entry, now);
	}

	synchronized void acked(String id)
	{
		pending.remove(id);
	}

	synchronized void failed(String id, int status)
	{
		Pending entry = pending.get(id);
		if (entry == null) return;
		if (status == 429) entry.nextAt = clock.getAsLong() + RETRY_MILLIS;
		else if (status == 401 && entry.token != null) entry.nextAt = clock.getAsLong();
		else pending.remove(id);
	}

	synchronized void resend()
	{
		long now = clock.getAsLong();
		for (Pending entry : pending.values()) sendSocket(entry, now);
	}

	synchronized int size()
	{
		return pending.size();
	}

	synchronized void clear()
	{
		pending.clear();
	}

	void flush()
	{
		long now = clock.getAsLong();
		List<Pending> due = new ArrayList<>();
		synchronized (this)
		{
			pending.expire(now);
			for (Pending entry : pending.values())
			{
				if (entry.nextAt > now || (!entry.socketTried && sendSocket(entry, now))) continue;
				due.add(entry);
			}
		}
		for (Pending entry : due)
		{
			String id = entry.body.get("id").getAsString();
			try
			{
				poster.post(entry.method, entry.path, entry.token, entry.body);
				acked(id);
			}
			catch (TsgHubApi.HttpError e)
			{
				if (e.status >= 400 && e.status < 500 && e.status != 429)
				{
					log.debug("TSG Hub {} rejected: {}", entry.type, e.getMessage());
					acked(id);
					continue;
				}
				retryLater(entry, now);
				return;
			}
			catch (Exception e)
			{
				log.debug("TSG Hub {} not sent", entry.type, e);
				retryLater(entry, now);
				return;
			}
		}
	}

	private synchronized void retryLater(Pending entry, long now)
	{
		entry.nextAt = now + RETRY_MILLIS;
	}

	private boolean sendSocket(Pending entry, long now)
	{
		if (!socket.test(entry.type, entry.body)) return false;
		entry.socketTried = true;
		entry.nextAt = now + RETRY_MILLIS;
		return true;
	}
}

package com.tsghub;

import static com.tsghub.TsgHubHtml.*;
import static com.tsghub.TsgHubJson.*;
import static com.tsghub.TsgHubTheme.*;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.awt.Color;
import java.time.Instant;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class TsgHubRoster
{
	private static final String ALT_RANK = "Gnome Child";
	private static final int MAX_PAST_WARNINGS = 3;

	private TsgHubRoster()
	{
	}

	static String locationTip(String activity, String area)
	{
		String detail = activityDetail(activity, "");
		boolean active = !"Idle".equals(activity) && !"Online".equals(activity) && !activity.isEmpty();
		String html = tipLine(active ? SUCCESS : MUTED, escape(detail));
		return area.isEmpty() || area.equals(detail) ? html : html + "<br>" + tipLine(MUTED, escape(area));
	}

	static boolean hasActiveWarning(JsonArray warnings)
	{
		return !activeWarnings(warnings).isEmpty();
	}

	static List<JsonObject> activeWarnings(JsonArray warnings)
	{
		List<JsonObject> active = new ArrayList<>();
		for (JsonObject warning : objects(warnings)) if (bool(warning, "active")) active.add(warning);
		return active;
	}

	static String lastSeen(String iso, Instant now)
	{
		Instant then = instant(iso);
		return then == null ? "" : TsgHubFormat.ago(then, now);
	}

	static String rosterTooltip(String location, JsonArray previousNames, String altOf, JsonArray alts, String note, JsonArray warnings, Instant now, ZoneId zone)
	{
		List<String> names = strings(alts);
		List<String> formerly = strings(previousNames);
		Collections.reverse(formerly);
		List<String> lines = new ArrayList<>();
		if (!altOf.isEmpty()) lines.add(tipLine(ACCENT, "Alt of <b>" + escape(altOf) + "</b>"));
		if (!names.isEmpty()) lines.add(tipLine(ACCENT, (names.size() == 1 ? "Alt: " : "Alts: ") + "<b>" + escape(String.join(", ", names)) + "</b>"));
		String head = String.join("<br>", lines);
		if (!location.isEmpty()) head = head.isEmpty() ? location : location + tipSection(false, head);
		String sections = "";
		if (!formerly.isEmpty())
		{
			sections += tipSection(head.isEmpty(), tipLine(MUTED, "<b>PREVIOUS NAMES</b>"))
				+ tipCard(CARD_HOVER, escape(String.join("\n", formerly)).replace("\n", "<br>"));
		}
		if (!note.isEmpty())
		{
			sections += tipSection(head.isEmpty() && sections.isEmpty(), tipLine(WARNING, "<b>ADMIN NOTE</b>"))
				+ tipCard(CARD_HOVER, escape(note).replace("\n", "<br>"));
		}
		List<JsonObject> history = objects(warnings);
		if (!history.isEmpty())
		{
			sections += tipSection(head.isEmpty() && sections.isEmpty(), tipLine(TsgHubTheme.ERROR, "<b>WARNINGS</b>") + " " + tipLine(MUTED, warningSummary(history)))
				+ warningCards(history, now, zone);
		}
		return head + sections;
	}

	static String warningSummary(List<JsonObject> warnings)
	{
		int active = activeWarningCount(warnings), expired = warnings.size() - active;
		return active + " active" + (expired > 0 ? " · " + expired + " expired" : "");
	}

	static String warningCards(List<JsonObject> warnings, Instant now, ZoneId zone)
	{
		List<JsonObject> all = activeFirst(warnings);
		int current = activeWarningCount(warnings);
		int inactive = all.size() - current;
		List<JsonObject> ordered = all.subList(0, current + Math.min(inactive, MAX_PAST_WARNINGS));
		StringBuilder out = new StringBuilder();
		for (JsonObject warning : ordered)
		{
			boolean active = bool(warning, "active");
			String meta = warningMeta(warning, now, zone);
			Color text = active ? TEXT : DIM;
			out.append(tipCard(active ? TsgHubTheme.ERROR : BORDER, tipLine(text, escape(str(warning, "reason"))) + "<br>" + tipLine(active ? MUTED : DIM, meta)));
		}
		if (inactive > MAX_PAST_WARNINGS) out.append(tipLine(DIM, "+" + (inactive - MAX_PAST_WARNINGS) + " older"));
		return out.toString();
	}

	static List<JsonObject> activeFirst(List<JsonObject> warnings)
	{
		List<JsonObject> ordered = new ArrayList<>();
		List<JsonObject> past = new ArrayList<>();
		for (JsonObject warning : warnings) (bool(warning, "active") ? ordered : past).add(warning);
		ordered.addAll(past);
		return ordered;
	}

	private static int activeWarningCount(List<JsonObject> warnings)
	{
		int count = 0;
		for (JsonObject warning : warnings) if (bool(warning, "active")) count++;
		return count;
	}

	static String warningMeta(JsonObject warning, Instant now, ZoneId zone)
	{
		return TsgHubFormat.shortDate(str(warning, "issuedAt"), now, zone) + " · " + escape(str(warning, "issuedBy")) + " · " + warningStatus(warning, now, zone);
	}

	static String warningStatus(JsonObject warning, Instant now, ZoneId zone)
	{
		if (!bool(warning, "active")) return "expired";
		String expires = str(warning, "expiresAt");
		return expires.isEmpty() ? "no expiry" : "expires " + TsgHubFormat.shortDate(expires, now, zone);
	}

	static boolean isAltRank(String rank)
	{
		return ALT_RANK.equalsIgnoreCase(rank.trim());
	}

	static String activityDetail(String activity, String area)
	{
		if (activity.isEmpty()) activity = "Online";
		int dash = activity.indexOf(" - ");
		String detail = dash < 0 ? activity : activity.startsWith("Slayer - ") ? "Slayer: " + activity.substring(dash + 3) : activity.substring(dash + 3);
		if (area.isEmpty() || area.equals(detail)) return detail;
		return detail + " · " + area;
	}
}

package com.tsghub;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

@Slf4j
final class TsgHubRules
{
	final String version;
	final List<String> chat;
	final List<String> players;
	final List<String> broadcastKeywords;
	final List<String> petMessages;
	final List<String> dropContext;
	final List<String> groupContent;
	final int dropDelayMs;
	final int dropContextTicks;
	final int dropContextKeep;
	final int skillingDrops;
	final long skillingWindowMillis;
	final Set<Integer> pets;
	final Set<Integer> rewardInterfaces;
	final Map<String, String> bosses;
	final Map<Integer, AreaNames.Area> areas;

	private static final TsgHubRules EMPTY = new TsgHubRules(new JsonObject());
	private static volatile TsgHubRules current = EMPTY;

	private TsgHubRules(JsonObject json)
	{
		version = TsgHubJson.str(json, "version");
		chat = strings(json, "chat");
		players = strings(json, "players");
		broadcastKeywords = strings(json, "broadcastKeywords");
		petMessages = strings(json, "petMessages");
		dropContext = strings(json, "dropContext");
		groupContent = strings(json, "groupContent");
		dropDelayMs = TsgHubJson.integer(json, "dropDelayMs", 1200);
		dropContextTicks = TsgHubJson.integer(json, "dropContextTicks", 50);
		dropContextKeep = TsgHubJson.integer(json, "dropContextKeep", 16);
		JsonObject skilling = TsgHubJson.object(json, "skilling");
		skillingDrops = TsgHubJson.integer(skilling, "minDrops", 3);
		skillingWindowMillis = TsgHubJson.longValue(skilling, "windowMillis", 120_000);
		pets = ints(json, "pets");
		rewardInterfaces = ints(json, "rewardInterfaces");
		Map<String, String> bossNames = new HashMap<>();
		for (JsonObject boss : TsgHubJson.objects(TsgHubJson.array(json, "bosses")))
		{
			String name = TsgHubJson.str(boss, "name");
			for (JsonElement npc : TsgHubJson.array(boss, "npcs")) bossNames.put(npc.getAsString().trim().toLowerCase(Locale.ROOT), name);
		}
		bosses = Collections.unmodifiableMap(bossNames);
		Map<Integer, AreaNames.Area> regions = new HashMap<>();
		for (JsonObject area : TsgHubJson.objects(TsgHubJson.array(json, "areas")))
		{
			AreaNames.Type type;
			try { type = AreaNames.Type.valueOf(TsgHubJson.str(area, "type")); }
			catch (IllegalArgumentException e) { continue; }
			AreaNames.Area named = new AreaNames.Area(TsgHubJson.str(area, "name"), type);
			for (JsonElement region : TsgHubJson.array(area, "regions")) regions.putIfAbsent(region.getAsInt(), named);
		}
		areas = Collections.unmodifiableMap(regions);
	}

	static TsgHubRules get()
	{
		return current;
	}

	static boolean apply(JsonObject json)
	{
		try
		{
			current = new TsgHubRules(json);
			return true;
		}
		catch (RuntimeException e)
		{
			log.debug("TSG Hub rules rejected", e);
			return false;
		}
	}

	static void reset()
	{
		current = EMPTY;
	}

	static void loadCached(Filepath cache, Gson gson)
	{
		if (cache == null || !cache.exists()) return;
		try (Reader reader = cache.openReader())
		{
			JsonObject saved = gson.fromJson(reader, JsonObject.class);
			if (TsgHubVersion.VERSION.equals(TsgHubJson.str(saved, "plugin")) && saved.has("rules") && saved.get("rules").isJsonObject()) apply(saved.getAsJsonObject("rules"));
		}
		catch (Exception e) { log.debug("TSG Hub cached rules unreadable", e); }
	}

	static void save(JsonObject json, Filepath cache)
	{
		if (!apply(json) || cache == null) return;
		try
		{
			cache.getParent().createDirectories();
			JsonObject saved = new JsonObject();
			saved.addProperty("plugin", TsgHubVersion.VERSION);
			saved.add("rules", json);
			cache.write(saved.toString());
		}
		catch (Exception e) { log.debug("TSG Hub rules cache not written", e); }
	}

	static void loadBundled(Gson gson)
	{
		InputStream in = TsgHubRules.class.getResourceAsStream("rules.json");
		if (in == null) return;
		try (InputStreamReader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			apply(gson.fromJson(reader, JsonObject.class));
		}
		catch (Exception e) { log.debug("TSG Hub bundled rules unreadable", e); }
	}

	private static List<String> strings(JsonObject json, String key)
	{
		List<String> out = new ArrayList<>();
		for (JsonElement value : TsgHubJson.array(json, key)) out.add(value.getAsString().toLowerCase(Locale.ROOT));
		return Collections.unmodifiableList(out);
	}

	private static Set<Integer> ints(JsonObject json, String key)
	{
		Set<Integer> out = new HashSet<>();
		for (JsonElement value : TsgHubJson.array(json, key)) out.add(value.getAsInt());
		return Collections.unmodifiableSet(out);
	}
}

package com.tsghub;

import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.DefaultListModel;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.ListSelectionModel;

abstract class TsgHubSearchField extends JPanel
{
	static final int HIDDEN = -1;
	private static final int VISIBLE_ROWS = 6;

	private final JTextField field;
	private final DefaultListModel<String> results = new DefaultListModel<>();
	private final JList<String> resultList = new JList<>(results);
	private final JScrollPane resultScroll = new JScrollPane(resultList);

	TsgHubSearchField(JTextField field)
	{
		this.field = field;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
		setAlignmentX(LEFT_ALIGNMENT);
	}

	void addSearch(String placeholder)
	{
		TsgHubUi.placeholder(field, placeholder);
		field.setAlignmentX(LEFT_ALIGNMENT);
		TsgHubUi.onTextChange(field, this::filter);
		field.addActionListener(e -> {
			if (resultScroll.isVisible() && !results.isEmpty()) choose(results.get(Math.max(0, resultList.getSelectedIndex())));
			else enterWithoutResults();
		});
		field.addKeyListener(new KeyAdapter()
		{
			@Override public void keyPressed(KeyEvent e)
			{
				if (!resultScroll.isVisible() || results.isEmpty()) return;
				int index = resultList.getSelectedIndex();
				if (e.getKeyCode() == KeyEvent.VK_DOWN) index = Math.min(results.size() - 1, index + 1);
				else if (e.getKeyCode() == KeyEvent.VK_UP) index = Math.max(0, index - 1);
				else if (e.getKeyCode() == KeyEvent.VK_ESCAPE) { hideResults(); e.consume(); return; }
				else return;
				resultList.setSelectedIndex(index);
				resultList.ensureIndexIsVisible(index);
				e.consume();
			}
		});
		add(TsgHubUi.fitHeight(field));

		resultList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		resultList.setVisibleRowCount(VISIBLE_ROWS);
		resultList.setBackground(TsgHubTheme.CARD);
		resultList.setCellRenderer((list, value, index, selected, focus) -> {
			JLabel row = new JLabel(value);
			row.setOpaque(true);
			row.setBorder(BorderFactory.createEmptyBorder(3, 6, 3, 6));
			row.setBackground(selected ? TsgHubTheme.CARD_HOVER : TsgHubTheme.CARD);
			row.setForeground(TsgHubTheme.TEXT);
			return row;
		});
		resultList.addMouseListener(new MouseAdapter()
		{
			@Override public void mouseClicked(MouseEvent e)
			{
				int index = resultList.locationToIndex(e.getPoint());
				if (index >= 0 && resultList.getCellBounds(index, index).contains(e.getPoint())) choose(results.get(index));
			}
		});
		resultScroll.setBorder(BorderFactory.createLineBorder(TsgHubTheme.BORDER));
		resultScroll.setAlignmentX(LEFT_ALIGNMENT);
		resultScroll.setVisible(false);
		add(resultScroll);
	}

	String getText()
	{
		return field.getText().trim();
	}

	void setText(String value)
	{
		field.setText(value == null ? "" : value);
		hideResults();
	}

	JTextField field()
	{
		return field;
	}

	abstract boolean isExact(String query);

	abstract List<String> matches(String query);

	void resultsChanged(String query, int matches)
	{
	}

	void resultsToggled()
	{
	}

	void chosen()
	{
	}

	void enterWithoutResults()
	{
	}

	private void filter()
	{
		String query = getText();
		results.clear();
		if (!query.isEmpty() && !isExact(query)) for (String match : matches(query)) results.addElement(match);
		resultList.setVisibleRowCount(Math.max(1, Math.min(VISIBLE_ROWS, results.size())));
		if (!results.isEmpty()) resultList.setSelectedIndex(0);
		showResults(!results.isEmpty(), results.size());
	}

	private void choose(String value)
	{
		field.setText(value);
		hideResults();
		chosen();
	}

	private void hideResults()
	{
		showResults(false, HIDDEN);
	}

	private void showResults(boolean visible, int matches)
	{
		boolean changed = resultScroll.isVisible() != visible;
		resultScroll.setVisible(visible);
		resultsChanged(getText(), matches);
		TsgHubUi.refresh(this);
		if (changed) resultsToggled();
	}
}

package com.tsghub;

import java.util.ArrayList;
import java.util.List;
import lombok.RequiredArgsConstructor;
import net.runelite.client.config.ConfigManager;

@RequiredArgsConstructor
class TsgHubSession
{
	static final String EVENT_ID = "eventId";
	static final String TOKEN = "token";
	static final String DISPLAY_NAME = "displayName";
	static final String MEMBER_TOKEN = "memberToken:";
	static final String MEMBER_NAME = "memberName:";
	static final String SIGNUP_NOTE = "signupNote:";
	static final String GROUP_TOKEN = "groupToken";
	static final String GROUP_PASSPHRASE = "groupPassphrase";
	static final String GROUP_PLAYER = "groupPlayer";
	static final String HIDE_COMPLETED = "hideCompleted";
	static final String SHOW_OFFLINE = "showOffline";
	static final String DOCK_VIEW = "dockView";
	static final String DOCK_SPLIT = "dockSplit";
	static final String DOCK_COLLAPSED = "dockCollapsed";
	static final String DROP_TYPE = "dropType";
	static final String DROP_VALUE = "dropValue";
	static final String ANNOUNCEMENTS_READ = "announcementsRead";
	static final String ANNOUNCEMENTS_ALERTED = "announcementsAlerted";

	private static final String GROUP = "tsghubsession";
	private final ConfigManager configManager;

	// ConfigManager rejects ':' in keys, so ':' is stored as '_'.
	// Event IDs, clan keys and prefixes never contain '_'.
	private static String encode(String key)
	{
		return key.replace(':', '_');
	}

	private static String decode(String key)
	{
		return key.replace('_', ':');
	}

	String get(String key)
	{
		ConfigManager manager = configManager;
		if (manager == null) return "";
		String value = manager.getRSProfileConfiguration(GROUP, encode(key));
		return value == null ? "" : value;
	}

	void set(String key, String value)
	{
		ConfigManager manager = configManager;
		if (manager == null) return;
		if (value == null || value.isEmpty()) manager.unsetRSProfileConfiguration(GROUP, encode(key));
		else manager.setRSProfileConfiguration(GROUP, encode(key), value);
	}

	List<String> keysWithPrefix(String prefix)
	{
		ConfigManager manager = configManager;
		List<String> keys = new ArrayList<>();
		if (manager == null) return keys;
		String profile = manager.getRSProfileKey();
		if (profile == null) return keys;
		for (String key : manager.getRSProfileConfigurationKeys(GROUP, profile, encode(prefix))) keys.add(decode(key));
		return keys;
	}

	String memberToken(String eventId)
	{
		return eventValue(MEMBER_TOKEN, eventId, TOKEN);
	}

	String memberName(String eventId)
	{
		return eventValue(MEMBER_NAME, eventId, DISPLAY_NAME);
	}

	private String eventValue(String prefix, String eventId, String activeKey)
	{
		String value = get(prefix + eventId);
		return value.isEmpty() && eventId.equals(get(EVENT_ID)) ? get(activeKey) : value;
	}

	void clear(String... keys)
	{
		for (String key : keys) set(key, "");
	}

	void removePrefix(String prefix)
	{
		for (String key : keysWithPrefix(prefix)) set(key, "");
	}
}

package com.tsghub;

import static com.tsghub.TsgHubSession.DISPLAY_NAME;
import static com.tsghub.TsgHubSession.EVENT_ID;
import static com.tsghub.TsgHubSession.MEMBER_NAME;
import static com.tsghub.TsgHubSession.MEMBER_TOKEN;
import static com.tsghub.TsgHubSession.SIGNUP_NOTE;
import static com.tsghub.TsgHubSession.TOKEN;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.tsghub.TsgHubUi.Tone;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
final class TsgHubSessions
{
	private final TsgHubPlugin plugin;
	private final ScheduledExecutorService executor;
	private final Map<String, Integer> syncedClanRanks = new ConcurrentHashMap<>();
	private volatile List<String> joinedCompetitions = Collections.emptyList();
	private volatile String syncedIdentity = "";

	private TsgHubSession session()
	{
		return plugin.session();
	}

	private TsgHubApi api()
	{
		return plugin.api();
	}

	List<String> joinedCompetitions()
	{
		return joinedCompetitions;
	}

	void profileChanged()
	{
		syncedClanRanks.clear();
		syncedIdentity = "";
		joinedCompetitions = Collections.emptyList();
	}

	void loggedOut()
	{
		joinedCompetitions = Collections.emptyList();
	}

	void reset()
	{
		syncedClanRanks.clear();
		syncedIdentity = "";
		joinedCompetitions = Collections.emptyList();
	}

	private String joinBlocker(TsgHubClan clan)
	{
		if (!clan.isHubClan()) return "TSG Hub is only for members of the " + clan.hubName() + " clan.";
		if (!plugin.sharingEnabled()) return "Turn on sharing first.";
		if (clan.playerName().isEmpty()) return "Log in to RuneScape before joining.";
		if (clan.name().isEmpty()) return "No clan detected. Log in to a character in your clan first.";
		return null;
	}

	void join(String code, String expectedEventId)
	{
		TsgHubClan clan = plugin.clan();
		String blocker = joinBlocker(clan);
		if (blocker != null)
		{
			joinFailed(blocker);
			return;
		}
		JsonObject payload = clan.memberBody(clan.playerName());
		payload.addProperty("code", code.trim());
		if (expectedEventId != null && !expectedEventId.trim().isEmpty()) payload.addProperty("eventId", expectedEventId.trim());
		api().call("POST", "/v1/join", null, payload).whenCompleteAsync(TsgHubApi.handle(result ->
		{
			String joinedEventId = result.getAsJsonObject("member").get("eventId").getAsString();
			String memberToken = result.get("token").getAsString();
			String memberName = result.getAsJsonObject("member").get("displayName").getAsString();
			session().set(MEMBER_TOKEN + joinedEventId, memberToken);
			session().set(MEMBER_NAME + joinedEventId, memberName);
			setActiveEvent(joinedEventId, memberToken, memberName);
			plugin.memberStatus("You're in! Progress now counts for your team.", Tone.SUCCESS);
			refreshBoard(true);
		}, e -> joinFailed(TsgHubFormat.friendlyError(e))), executor);
	}

	private void joinFailed(String message)
	{
		plugin.ui(s -> s.eventsView.joinFailed(message));
	}

	void signup(String eventId, String note)
	{
		TsgHubClan clan = plugin.clan();
		String blocker = joinBlocker(clan);
		if (blocker != null)
		{
			signupFailed(blocker);
			return;
		}
		JsonObject payload = clan.memberBody(clan.playerName());
		payload.addProperty("note", note.trim());
		api().call("POST", "/v1/events/" + eventId + "/signup", null, payload).whenCompleteAsync(TsgHubApi.handle(result ->
		{
			JsonObject member = result.getAsJsonObject("member");
			String memberToken = result.get("token").getAsString();
			String memberName = member.get("displayName").getAsString();
			session().set(MEMBER_TOKEN + eventId, memberToken);
			session().set(MEMBER_NAME + eventId, memberName);
			session().set(SIGNUP_NOTE + eventId, TsgHubJson.str(member, "note"));
			setActiveEvent(eventId, memberToken, memberName);
			plugin.memberStatus("Signed up! An admin will put you on a team.", Tone.SUCCESS);
			applyBoard(eventId, memberToken, result.getAsJsonObject("event"), true);
		}, e -> signupFailed(TsgHubFormat.friendlyError(e))), executor);
	}

	void editNote(String eventId, String note)
	{
		String token = session().memberToken(eventId);
		if (token.isEmpty()) return;
		JsonObject payload = new JsonObject();
		payload.addProperty("note", note.trim());
		api().call("PATCH", "/v1/events/" + eventId + "/signup", token, payload).whenCompleteAsync(TsgHubApi.handle(result ->
		{
			session().set(SIGNUP_NOTE + eventId, TsgHubJson.str(result.getAsJsonObject("member"), "note"));
			plugin.memberStatus("Note saved.", Tone.SUCCESS);
			applyBoard(eventId, token, result.getAsJsonObject("event"), true);
		}, e ->
		{
			signupFailed(TsgHubFormat.friendlyError(e));
			refreshBoard();
		}), executor);
	}

	private void signupFailed(String message)
	{
		plugin.ui(s -> s.eventsView.signupFailed(message));
	}

	void withdraw(String eventId)
	{
		String token = session().memberToken(eventId);
		if (token.isEmpty()) return;
		plugin.sidebarBusy(true);
		api().call("DELETE", "/v1/events/" + eventId + "/signup", token, null).whenCompleteAsync(TsgHubApi.handle(result ->
		{
			forgetEvent(eventId);
			plugin.memberStatus("You've left the sign-ups.", Tone.SUCCESS);
			loadClanEvents();
		}, e ->
		{
			signupFailed(TsgHubFormat.friendlyError(e));
			refreshBoard();
		}, () -> plugin.sidebarBusy(false)), executor);
	}

	void leaveEvent(String eventId)
	{
		String revokeToken = session().memberToken(eventId);
		if (!revokeToken.isEmpty()) disconnect(eventId, revokeToken);
		session().clear(MEMBER_TOKEN + eventId, MEMBER_NAME + eventId, SIGNUP_NOTE + eventId);
		if (eventId.equals(session().get(EVENT_ID))) session().clear(TOKEN, EVENT_ID);
		plugin.memberStatus("Disconnected. Rejoin anytime with your team code.", Tone.SUCCESS);
		plugin.ui(s -> s.eventsView.showEventList());
		loadClanEvents();
	}

	void clearAll()
	{
		joinedCompetitions = Collections.emptyList();
		revokeRemote();
		TsgHubSession session = session();
		session.clear(TOKEN, EVENT_ID);
		session.removePrefix(MEMBER_TOKEN);
		session.removePrefix(MEMBER_NAME);
		session.removePrefix(SIGNUP_NOTE);
		syncedClanRanks.clear();
	}

	private void revokeRemote()
	{
		if (executor.isShutdown()) return;
		Map<String, String> sessions = new HashMap<>();
		for (String key : session().keysWithPrefix(MEMBER_TOKEN))
		{
			String eventId = key.substring(MEMBER_TOKEN.length());
			sessions.put(eventId, session().get(key));
		}
		String activeEventId = session().get(EVENT_ID);
		String activeToken = session().get(TOKEN);
		if (!activeEventId.isEmpty() && !activeToken.isEmpty()) sessions.putIfAbsent(activeEventId, activeToken);
		sessions.forEach(this::disconnect);
	}

	private void disconnect(String eventId, String token)
	{
		// Local disconnect still succeeds while the service is unavailable.
		api().call("POST", "/v1/events/" + eventId + "/disconnect", token, new JsonObject());
	}

	void refreshBoard()
	{
		refreshBoard(false);
	}

	private void refreshBoard(boolean open)
	{
		if (!plugin.sharingInClan()) return;
		String eventId = session().get(EVENT_ID);
		String token = session().get(TOKEN);
		if (eventId.isEmpty() || token.isEmpty()) return;
		plugin.sidebarBusy(true);
		api().call("GET", "/v1/events/" + eventId + "?sets=1", token, null).whenCompleteAsync(TsgHubApi.handle(response ->
		{
			JsonObject event = response.getAsJsonObject("event");
			applyBoard(eventId, token, event, open);
		}, e -> eventLoadFailed(eventId, e, "Couldn't update the board. "), () -> plugin.sidebarBusy(false)), executor);
	}

	boolean claimTile(String eventId, String taskId, String note)
	{
		return sendTileClaim("tile.claim", "POST", eventId, taskId, note);
	}

	boolean dropTileClaim(String eventId, String taskId)
	{
		return sendTileClaim("tile.unclaim", "DELETE", eventId, taskId, null);
	}

	private boolean sendTileClaim(String type, String method, String eventId, String taskId, String note)
	{
		String token = session().get(TOKEN);
		if (!plugin.sharingInClan() || token.isEmpty() || !eventId.equals(session().get(EVENT_ID)) || executor.isShutdown()) return false;
		JsonObject body = TsgHubTileClaims.body(eventId, taskId, note);
		executor.execute(() -> plugin.tracker().report(type, method, TsgHubTileClaims.path(eventId, taskId), token, body));
		return true;
	}

	void applyBoard(String eventId, String token, JsonObject event, boolean open)
	{
		syncClanRank(eventId, token, event);
		String name = session().get(DISPLAY_NAME);
		if (TsgHubEvents.awaitingTeam(event, name))
		{
			String note = session().get(SIGNUP_NOTE + eventId);
			plugin.ui(s -> s.eventsView.showSignedUp(event, note, open));
			return;
		}
		session().clear(SIGNUP_NOTE + eventId);
		plugin.ui(s ->
		{
			boolean placed = s.view == TsgHubSidebarPanel.View.SIGNUP;
			if (placed) s.setStatus("You're on a team! Progress now counts for your team.", Tone.SUCCESS);
			s.boardView.showBoard(event, name, open || placed);
		});
	}

	private void eventLoadFailed(String eventId, Exception e, String failure)
	{
		String message = e.getMessage() == null ? "" : e.getMessage();
		if (message.startsWith("Event not found") || message.startsWith("Connect to this event first"))
		{
			// Event or team was deleted: forget it instead of failing every refresh.
			forgetEvent(eventId);
			plugin.memberStatus("That event is no longer available.", Tone.ERROR);
			loadClanEvents();
		}
		else plugin.memberError(failure, e);
	}

	void autoRefreshBoard(TsgHubSidebarPanel sidebar)
	{
		if (sidebar == null) return;
		if (sidebar.wantsAutoRefresh()) refreshBoard();
		String competitionId = sidebar.competitionView.openCompetitionId();
		if (competitionId != null) openCompetition(competitionId);
	}

	void participate(String eventId)
	{
		TsgHubClan clan = plugin.clan();
		if (!plugin.sharingInClan() || clan.playerName().isEmpty()) return;
		JsonObject body = clan.memberBody(clan.playerName());
		plugin.sidebarBusy(true);
		api().call("POST", "/v1/events/" + eventId + "/participate", null, body).whenCompleteAsync(TsgHubApi.handle(result ->
		{
			session().set(MEMBER_TOKEN + eventId, result.get("token").getAsString());
			session().set(MEMBER_NAME + eventId, result.getAsJsonObject("member").get("displayName").getAsString());
			plugin.liveSync().syncNow();
			plugin.memberStatus("You're in! Your progress counts from now.", Tone.SUCCESS);
			loadClanEvents();
			openCompetition(eventId, true);
		}, e -> plugin.ui(s -> s.competitionView.competitionJoinFailed(TsgHubFormat.friendlyError(e))), () -> plugin.sidebarBusy(false)), executor);
	}

	void openCompetition(String eventId)
	{
		openCompetition(eventId, false);
	}

	void openCompetition(String eventId, boolean open)
	{
		String token = session().get(MEMBER_TOKEN + eventId);
		if (token.isEmpty()) return;
		String name = session().get(MEMBER_NAME + eventId);
		plugin.sidebarBusy(true);
		api().call("GET", "/v1/events/" + eventId, token, null).whenCompleteAsync(TsgHubApi.handle(response ->
		{
			JsonObject event = response.getAsJsonObject("event");
			plugin.ui(s -> s.competitionView.showCompetition(event, name, open));
		}, e -> eventLoadFailed(eventId, e, "Couldn't load the leaderboard. "), () -> plugin.sidebarBusy(false)), executor);
	}

	void syncIdentity()
	{
		TsgHubClan clan = plugin.clan();
		String name = clan.playerName();
		String hash = clan.accountHash();
		if (name.isEmpty() || hash.isEmpty() || clan.name().isEmpty()) return;
		String identity = hash + ":" + name;
		if (identity.equals(syncedIdentity)) return;
		syncedIdentity = identity;
		TsgHubSession session = session();
		JsonArray memberTokens = new JsonArray();
		for (String key : session.keysWithPrefix(MEMBER_TOKEN)) memberTokens.add(session.get(key));
		if (!session.get(TOKEN).isEmpty()) memberTokens.add(session.get(TOKEN));
		for (String key : session.keysWithPrefix(MEMBER_NAME)) renameStored(key, name);
		renameStored(DISPLAY_NAME, name);
		JsonObject body = new JsonObject();
		body.addProperty("displayName", name);
		body.addProperty("clanName", clan.name());
		body.addProperty("accountHash", hash);
		body.add("memberTokens", memberTokens);
		api().call("POST", "/v1/identity", null, body).whenCompleteAsync(TsgHubApi.handle(result ->
		{
			if (TsgHubJson.bool(result, "updated") && !session().get(EVENT_ID).isEmpty() && !plugin.live()) refreshBoard();
		}, e -> syncedIdentity = ""), executor);
	}

	private void renameStored(String key, String name)
	{
		String stored = session().get(key);
		if (!stored.isEmpty() && !PlayerNames.samePlayer(stored, name)) session().set(key, name);
	}

	void loadClanEvents()
	{
		if (!plugin.sharingInClan()) return;
		String clanName = plugin.clan().name();
		if (clanName.trim().isEmpty())
		{
			plugin.ui(s -> s.eventsView.setEvents(new JsonArray()));
			return;
		}
		plugin.sidebarBusy(true);
		api().call("GET", "/v1/events?clanName=" + TsgHubApi.encode(clanName), null, null).whenCompleteAsync(TsgHubApi.handle(response ->
		{
			applyClanEvents(response.getAsJsonArray("events"));
		}, e -> plugin.memberError("Couldn't load events. ", e), () -> plugin.sidebarBusy(false)), executor);
	}

	void applyClanEvents(JsonArray events)
	{
		if (events == null) return;
		TsgHubSession session = session();
		for (JsonObject event : TsgHubJson.objects(events))
		{
			String eventId = event.get("id").getAsString();
			event.addProperty("joined", !session.memberToken(eventId).isEmpty());
		}
		joinedCompetitions = joinedCompetitionIds(events);
		plugin.ui(s -> s.eventsView.setEvents(events));
	}

	private List<String> joinedCompetitionIds(JsonArray events)
	{
		List<String> ids = new ArrayList<>();
		for (JsonObject event : TsgHubJson.objects(events))
		{
			String type = TsgHubJson.str(event, "type");
			if (!("skill".equals(type) || "boss".equals(type)) || "ended".equals(TsgHubJson.str(event, "status"))) continue;
			String id = TsgHubJson.str(event, "id");
			if (!session().get(MEMBER_TOKEN + id).isEmpty()) ids.add(id);
		}
		return ids;
	}

	void activateEvent(String eventId)
	{
		activateEvent(eventId, true);
	}

	void activateEvent(String eventId, boolean open)
	{
		String token = session().memberToken(eventId);
		if (token.isEmpty())
		{
			plugin.memberStatus("Join this event with your team code first.", Tone.ERROR);
			return;
		}
		setActiveEvent(eventId, token, session().memberName(eventId));
		refreshBoard(open);
	}

	private void setActiveEvent(String eventId, String token, String displayName)
	{
		session().set(TOKEN, token);
		session().set(EVENT_ID, eventId);
		session().set(DISPLAY_NAME, displayName);
		plugin.liveSync().syncNow();
	}

	private void syncClanRank(String eventId, String token, JsonObject event)
	{
		TsgHubClan clan = plugin.clan();
		String displayName = clan.playerName();
		String memberName = session().get(DISPLAY_NAME);
		String eventClan = TsgHubJson.str(event, "clanName");
		if (token.isEmpty() || displayName.isEmpty() || !PlayerNames.samePlayer(displayName, memberName)
			|| eventClan.isEmpty() || !eventClan.equalsIgnoreCase(clan.name())) return;
		int rank = clan.rank();
		String key = eventId + ":" + PlayerNames.key(displayName);
		Integer synced = syncedClanRanks.get(key);
		if (synced != null && synced == rank) return;
		JsonObject body = new JsonObject();
		body.addProperty("eventId", eventId);
		body.addProperty("displayName", displayName);
		body.addProperty("clanName", clan.name());
		body.addProperty("clanRank", rank);
		syncedClanRanks.put(key, rank);
		plugin.tracker().report("clan-rank", "/v1/events/" + eventId + "/clan-rank", token, body);
	}

	void forgetEvent(String eventId)
	{
		TsgHubSession session = session();
		session.clear(MEMBER_TOKEN + eventId, MEMBER_NAME + eventId, SIGNUP_NOTE + eventId);
		if (eventId.equals(session.get(EVENT_ID)))
		{
			session.clear(TOKEN, EVENT_ID);
			plugin.ui(s -> s.boardView.closeBoard());
		}
	}

	void pollNotifications()
	{
		TsgHubClan clan = plugin.clan();
		if (!plugin.sharingInClan() || executor.isShutdown()) return;
		String token = session().get(TOKEN);
		String eventId = session().get(EVENT_ID);
		if (token.isEmpty() || eventId.isEmpty()) return;
		String path = "/v1/events/" + eventId + "/notifications?inClanChat=" + clan.inClanChat() + "&clanName=" + TsgHubApi.encode(clan.name());
		api().call("GET", path, token, null).thenAcceptAsync(result -> {
			if (plugin.chat().notifications(result.getAsJsonArray("notifications"))) refreshBoard();
		}, executor);
	}
}

package com.tsghub;

