final class TsgHubSidebarPanel extends PluginPanel
{
	static final int TEXT_W = 215;
	static final int CARD_TEXT_W = 185;
	static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("h:mm a");

	enum View { LOGGED_OUT, NOT_IN_CLAN, SHARING_OFF, HOME, EVENTS, PREVIEW, SIGNUP, BOARD, COMPETITION_PREVIEW, COMPETITION, DROP_PARTY, GROUPS, MEMBERS, LOOKUP, DROPS, NEWS }

	private final TsgHubPlugin plugin;
	final TsgHubHomeView homeView;
	final TsgHubMembersView membersView;
	final TsgHubMemberAdmin memberAdmin;
	final TsgHubLookupView lookupView;
	final TsgHubDropsView dropsView;
	final TsgHubNewsView newsView;
	final TsgHubEventsView eventsView;
	final TsgHubCompetitionView competitionView;
	final TsgHubPartiesView partiesView;
	final TsgHubBoardView boardView;
	final JButton back = iconButton(hover("back"), "Back to events");
	private final JLabel title = boldLabel("TSG Hub");
	private final JLabel subtitle = caption(" ");
	private String titleText = "TSG Hub";
	private final Glyph refreshIcon = hover("refresh");
	final JButton refresh = iconButton(refreshIcon, "Refresh");
	private final JButton admin = iconButton(hover("organizer"), "Open the admin site");
	private final JButton settings = iconButton(hover("cog"), "Plugin settings");
	private final JButton pin = iconButton(hover("pin"), "Pin below");
	private final JPanel footer = new JPanel();
	private final JButton discord = iconButton(hover("discord", DISCORD), "Open the clan Discord");
	private final JButton link = button("Link Discord");
	private final Timer linkTimer = new Timer(1000, e -> renderLink());
	private boolean needsLink;
	private long linkDeadline;
	private final JLabel connection = label("", MUTED, smallFont());
	private final JLabel version = label("v" + TsgHubVersion.VERSION, DIM, smallFont());
	private final StatusLine status = new StatusLine(TEXT_W);

	private final CardLayout centerLayout = new CardLayout();
	private final JPanel center = new JPanel(centerLayout);
	final WidthTrackingPanel page = new WidthTrackingPanel();
	final TsgHubDock dock;
	View pinned;
	View view = View.LOGGED_OUT;
	private int busy;
	volatile boolean active;
	private volatile boolean boardShowing;
	private volatile boolean membersWanted;
	private volatile boolean groupsWanted;
	private volatile boolean dropsWanted;
	private final JPanel titleRow = new JPanel(new BorderLayout(4, 0));
	private final JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
	final GroupMembersPanel groupMembers;
	TsgHubSidebarPanel(TsgHubPlugin plugin, GroupMembersPanel groupMembers)
	{
		super(false);
		this.plugin = plugin;
		this.groupMembers = groupMembers;
		membersView = new TsgHubMembersView(plugin, this);
		memberAdmin = new TsgHubMemberAdmin(plugin, this);
		lookupView = new TsgHubLookupView(plugin, this);
		dropsView = new TsgHubDropsView(plugin, this);
		newsView = new TsgHubNewsView(plugin, this);
		eventsView = new TsgHubEventsView(plugin, this);
		competitionView = new TsgHubCompetitionView(plugin, this);
		partiesView = new TsgHubPartiesView(plugin, this);
		boardView = new TsgHubBoardView(plugin, this);
		homeView = new TsgHubHomeView(plugin, this);
		dock = new TsgHubDock(center, this::unpin, plugin.session());
		setLayout(new BorderLayout(0, 6));
		setBackground(BACKGROUND);
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		add(buildHeader(), BorderLayout.NORTH);

		center.setOpaque(false);
		center.add(scroll(page), "page");
		center.add(boardView.buildBoard(), "board");
		center.add(partiesView.groupsScroll, "groups");
		center.add(membersView.membersScroll, "members");
		center.add(dropsView.buildDropsView(), "drops");
		add(dock, BorderLayout.CENTER);
		add(buildFooter(), BorderLayout.SOUTH);

		showLoggedOut();
		restorePin();
	}

	private JPanel buildHeader()
	{
		JPanel header = panel(new BorderLayout());
		titleRow.setOpaque(false);
		back.addActionListener(e -> {
			if (view == View.GROUPS && partiesView.browsingParties && plugin.groups().inGroup())
			{
				partiesView.browsingParties = false;
				partiesView.renderGroups();
				return;
			}
			if (view == View.LOOKUP)
			{
				reopen(lookupView.lookupReturn);
				return;
			}
			if (view == View.GROUPS || view == View.EVENTS || view == View.MEMBERS || view == View.DROPS || view == View.NEWS)
			{
				homeView.showHome();
				return;
			}
			eventsView.showEventList();
			if (!plugin.live()) plugin.sessions().loadClanEvents();
		});
		titleRow.add(back, BorderLayout.WEST);

		JPanel titles = stack();
		titles.add(title);
		titles.add(shrinkable(subtitle));
		titleRow.add(fillWidth(titles), BorderLayout.CENTER);

		actions.setOpaque(false);
		admin.addActionListener(e -> {
			admin.setEnabled(false);
			plugin.openAdminSite(() -> admin.setEnabled(true));
		});
		admin.setVisible(false);
		refresh.addActionListener(e -> {
			if (view == View.HOME)
			{
				plugin.sessions().loadClanEvents();
				plugin.groups().refresh();
				plugin.presence().loadMembers(false);
				plugin.announcements().load();
			}
			else if (view == View.GROUPS) plugin.groups().refresh();
			else if (view == View.NEWS) plugin.announcements().load();
			else if (view == View.MEMBERS) plugin.presence().loadMembers(false);
			else if (view == View.LOOKUP) lookupView.loadLookup();
			else if (view == View.DROPS) plugin.drops().load(false);
			else if (view == View.BOARD || view == View.SIGNUP) plugin.sessions().refreshBoard();
			else if (view == View.COMPETITION && competitionView.competitionEvent != null) plugin.sessions().openCompetition(str(competitionView.competitionEvent, "id"));
			else plugin.sessions().loadClanEvents();
		});
		JPanel refreshSlot = panel(new BorderLayout());
		refreshSlot.setPreferredSize(refresh.getPreferredSize());
		refreshSlot.add(refresh);
		settings.addActionListener(e -> plugin.openSettings());
		pin.addActionListener(e -> pinCurrent());
		pin.setVisible(false);
		actions.add(admin);
		actions.add(pin);
		actions.add(refreshSlot);
		actions.add(settings);
		titleRow.add(actions, BorderLayout.EAST);

		JPanel below = stack();
		below.add(titleRow);
		below.add(status);

		header.add(below, BorderLayout.CENTER);
		header.setBorder(BorderFactory.createCompoundBorder(bottomRule(), BorderFactory.createEmptyBorder(0, 0, 6, 0)));
		return header;
	}

	void setAdminAccess(boolean allowed)
	{
		admin.setVisible(allowed);
		title.setText(html(escape(titleText), titleWidth()));
		if (shows(View.MEMBERS)) membersView.renderMembers();
	}

	private int titleWidth()
	{
		return 150 - (admin.isVisible() ? admin.getPreferredSize().width + 2 : 0)
			- (pin.isVisible() ? pin.getPreferredSize().width + 2 : 0);
	}

	void setStatus(String message, Tone tone)
	{
		status.show(message, tone);
	}

	void setBusy(boolean isBusy)
	{
		busy = Math.max(0, busy + (isBusy ? 1 : -1));
		refreshIcon.setSpinning(busy > 0, refresh);
	}

	boolean wantsAutoRefresh()
	{
		return active && boardShowing;
	}

	boolean wantsMembers()
	{
		return active && membersWanted;
	}

	boolean wantsDrops()
	{
		return active && dropsWanted;
	}

	boolean wantsGroups()
	{
		return active && groupsWanted;
	}

	@Override
	public void onActivate()
	{
		active = true;
	}

	@Override
	public void onDeactivate()
	{
		active = false;
	}

	void showLoggedOut()
	{
		showMessage(View.LOGGED_OUT, errorPanel("Not logged in", "Log in to see your clan's events and your team's progress."));
	}

	void showNotInClan(String hubClan, String detectedClan)
	{
		String body = detectedClan == null || detectedClan.isEmpty()
			? "TSG Hub is for members of the " + hubClan + " clan. Join the clan in game to see its events."
			: "TSG Hub is for members of the " + hubClan + " clan. This character is in " + detectedClan + ".";
		showMessage(View.NOT_IN_CLAN, errorPanel("For " + hubClan + " members", body));
	}

	void showCheckingClan()
	{
		showMessage(View.NOT_IN_CLAN, caption("Checking your clan..."));
	}

	void showSharingOff()
	{
		JButton enable = onClick(primaryButton("Enable sharing"), () -> plugin.enableSharing());
		showMessage(View.SHARING_OFF,
			boldLabel("Share your progress"),
			gap(GAP_S),
			hint("TSG Hub tracks your boss kills, drops and raids for clan events. "
				+ "To do that it sends your RuneScape name, clan and rank, and that progress to your clan's event service."),
			gap(GAP_S),
			hint("Nothing is ever posted in game chat."),
			gap(GAP_L),
			fitHeight(enable),
			gap(GAP_S),
			hint("You can turn this off anytime in the TSG Hub plugin settings."));
	}

	private void showMessage(View next, Component... parts)
	{
		setView(next);
		setHeader("TSG Hub", "", false, false);
		page.removeAll();
		for (Component part : parts) page.add(part);
		refreshPage();
	}

	void setConnection(TsgHubSocket.State state)
	{
		Color color = state == TsgHubSocket.State.CONNECTED ? SUCCESS : state == TsgHubSocket.State.CONNECTING ? WARNING : TsgHubTheme.ERROR;
		String status = state == TsgHubSocket.State.CONNECTED ? "Connected" : state == TsgHubSocket.State.CONNECTING ? "Connecting…" : "Disconnected";
		connection.setIcon(icon("dot", color, 7));
		connection.setText(status);
		connection.setToolTipText(state == TsgHubSocket.State.CONNECTED ? "Receiving live updates" : state == TsgHubSocket.State.CONNECTING ? "Connecting to TSG Hub" : "Not connected to TSG Hub");
	}

	JPanel sectionHeading(String text, JComponent right)
	{
		JPanel row = row();
		row.setBorder(BorderFactory.createEmptyBorder(0, 2, 4, 0));
		row.add(label(text.toUpperCase(), MUTED, smallFont()), BorderLayout.CENTER);
		if (right != null) row.add(right, BorderLayout.EAST);
		return fitHeight(row);
	}

	static JPanel fillWidth(Component content)
	{
		JPanel slot = panel(new GridBagLayout());
		GridBagConstraints fill = new GridBagConstraints();
		fill.weightx = 1;
		fill.fill = GridBagConstraints.HORIZONTAL;
		slot.add(content, fill);
		return slot;
	}

	void setView(View next)
	{
		view = next;
		homeView.homeBuilt = false;
		boardShowing = next == View.BOARD || next == View.SIGNUP;
		boolean docked = pinned != null && !gated(next);
		membersWanted = next == View.MEMBERS || next == View.HOME || docked && pinned == View.MEMBERS;
		groupsWanted = next == View.GROUPS || next == View.HOME || docked && pinned == View.GROUPS;
		dropsWanted = next == View.DROPS || docked && pinned == View.DROPS;
		if (next != View.COMPETITION) competitionView.openCompetitionId = null;
		centerLayout.show(center, cardName(next));
		discord.setVisible(next == View.HOME && !needsLink);
		link.setVisible(next == View.HOME && needsLink);
		dock.setShown(!gated(next));
		pin.setVisible(pinnable(next));
		title.setText(html(escape(titleText), titleWidth()));
		back.setToolTipText(next == View.LOOKUP ? backLabel(lookupView.lookupReturn) : next == View.EVENTS || next == View.GROUPS || next == View.MEMBERS || next == View.DROPS || next == View.NEWS ? "Home" : "Back to events");
	}

	private static String cardName(View next)
	{
		switch (next)
		{
			case BOARD: return "board";
			case GROUPS: return "groups";
			case MEMBERS: return "members";
			case DROPS: return "drops";
			default: return "page";
		}
	}

	private static boolean gated(View next)
	{
		return next == View.LOGGED_OUT || next == View.NOT_IN_CLAN || next == View.SHARING_OFF;
	}

	private static boolean pinnable(View next)
	{
		return next == View.MEMBERS || next == View.DROPS || next == View.GROUPS;
	}

	boolean shows(View owner)
	{
		return view == owner || pinned == owner;
	}

	private static String backLabel(View target)
	{
		switch (target)
		{
			case MEMBERS: return "Members";
			case BOARD:
			case COMPETITION: return "Back to event";
			case EVENTS: return "Events";
			case DROPS: return "Drops";
			case GROUPS: return "Parties";
			default: return "Home";
		}
	}

	private void reopen(View target)
	{
		switch (target)
		{
			case MEMBERS: membersView.showMembers(); break;
			case DROPS: dropsView.showDrops(); break;
			case GROUPS: partiesView.showParties(); break;
			case EVENTS: eventsView.showEventList(); break;
			case BOARD:
				if (boardView.boardEvent != null) boardView.showBoard(boardView.boardEvent, boardView.boardDisplayName, true);
				else homeView.showHome();
				break;
			case COMPETITION:
				if (competitionView.competitionEvent != null) competitionView.showCompetition(competitionView.competitionEvent, competitionView.competitionName, true);
				else homeView.showHome();
				break;
			default: homeView.showHome();
		}
	}

	void viewHeader(View owner, String titleText, String subtitleText, String dockDetail)
	{
		if (pinned == owner) dock.setTitle(titleText, dockDetail);
		else setHeader(titleText, subtitleText, true, true);
	}

	private JComponent pane(View owner)
	{
		return owner == View.MEMBERS ? membersView.membersScroll : owner == View.DROPS ? dropsView.dropsPanel : partiesView.groupsScroll;
	}

	private String pinIcon(View owner)
	{
		return owner == View.MEMBERS ? "members" : owner == View.DROPS ? "drops" : "party";
	}

	void pinCurrent()
	{
		if (!pinnable(view)) return;
		View next = view;
		if (pinned != null) unpin();
		pin(next);
		homeView.showHome();
	}

	private void pin(View next)
	{
		pinned = next;
		plugin.session().set(DOCK_VIEW, next.name());
		dock.pin(pinIcon(next), pane(next));
		dock.expand();
		renderPinned();
	}

	private void unpin()
	{
		if (pinned == null) return;
		View was = pinned;
		pinned = null;
		plugin.session().set(DOCK_VIEW, "");
		dock.unpin();
		center.add(pane(was), cardName(was));
		setView(view);
	}

	private void restorePin()
	{
		String saved = plugin.session().get(DOCK_VIEW);
		for (View candidate : View.values())
			if (pinnable(candidate) && candidate.name().equals(saved))
			{
				pinned = candidate;
				dock.pin(pinIcon(candidate), pane(candidate));
				setView(view);
				renderPinned();
			}
	}

	private void renderPinned()
	{
		if (pinned == View.MEMBERS) membersView.renderMembers();
		else if (pinned == View.DROPS) dropsView.renderDrops();
		else if (pinned == View.GROUPS) partiesView.renderGroups();
	}

	private JPanel buildFooter()
	{
		discord.addActionListener(e -> {
			discord.setEnabled(false);
			plugin.openDiscordInvite(() -> discord.setEnabled(true));
		});
		discord.setAlignmentX(Component.CENTER_ALIGNMENT);
		link.setIcon(icon("discord", Color.WHITE, 14));
		link.setIconTextGap(6);
		link.setBackground(DISCORD);
		link.setForeground(Color.WHITE);
		link.setAlignmentX(Component.CENTER_ALIGNMENT);
		link.addActionListener(e -> {
			link.setEnabled(false);
			if (linkDeadline > System.currentTimeMillis()) plugin.keys().cancelLink();
			else plugin.keys().startLink();
		});
		connection.setIconTextGap(6);
		setConnection(TsgHubSocket.State.DISCONNECTED);
		JPanel status = new JPanel(new BorderLayout());
		status.setOpaque(false);
		status.setAlignmentX(Component.CENTER_ALIGNMENT);
		status.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(1, 0, 0, 0, BORDER), BorderFactory.createEmptyBorder(6, 2, 0, 2)));
		status.add(connection, BorderLayout.WEST);
		status.add(version, BorderLayout.EAST);
		footer.setLayout(new BoxLayout(footer, BoxLayout.Y_AXIS));
		footer.setOpaque(false);
		footer.add(discord);
		footer.add(link);
		footer.add(gap(6));
		footer.add(status);
		discord.setVisible(false);
		link.setVisible(false);
		return footer;
	}

	void setDiscordLink(boolean needsLink, long deadline, boolean starting)
	{
		this.needsLink = needsLink;
		linkDeadline = needsLink ? deadline : 0;
		link.setEnabled(!starting);
		discord.setVisible(view == View.HOME && !needsLink);
		link.setVisible(view == View.HOME && needsLink);
		renderLink();
	}

	private void renderLink()
	{
		long left = linkDeadline - System.currentTimeMillis();
		if (linkDeadline > 0 && left > 0)
		{
			long seconds = (left + 999) / 1000;
			link.setText(String.format("Waiting\u2026 %d:%02d", seconds / 60, seconds % 60));
			link.setToolTipText("Run the copied command in the clan Discord. Click to cancel.");
			if (!linkTimer.isRunning()) linkTimer.start();
			return;
		}
		linkTimer.stop();
		link.setText("Link Discord");
		link.setToolTipText("Copy a /plugin link command and open the clan Discord");
	}

	void setEventHeader(JsonObject event, boolean showBack, boolean showRefresh)
	{
		String relative = eventRelative(event);
		setHeader(eventName(event), relative.isEmpty() ? statusLabel(str(event, "status")) : capitalize(relative), showBack, showRefresh);
		subtitle.setToolTipText(eventWhen(event));
	}

	void setHeader(String titleText, String subtitleText, boolean showBack, boolean showRefresh)
	{
		this.titleText = titleText;
		title.setText(html(escape(titleText), titleWidth()));
		subtitle.setText(subtitleText);
		subtitle.setVisible(!subtitleText.isEmpty());
		subtitle.setToolTipText(null);
		back.setVisible(showBack);
		refresh.setVisible(showRefresh);
	}

	JPanel errorPanel(String heading, String body)
	{
		return emptyState(heading, body, TEXT_W - 20);
	}

	static JLabel hint(String text)
	{
		return wrapped(text, MUTED, smallFont(), TEXT_W);
	}

	static JLabel cardNote(String text)
	{
		return wrapped(text, MUTED, smallFont(), CARD_TEXT_W);
	}

	static JLabel cardNoteHtml(String innerHtml)
	{
		return label(html(innerHtml, CARD_TEXT_W), MUTED, smallFont());
	}

	void refreshPage()
	{
		refresh(page);
	}
}

package com.tsghub;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.function.Consumer;
import java.util.function.Supplier;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@RequiredArgsConstructor
final class TsgHubSignals
{
	private static final long RETRY_MILLIS = 10_000;
	private static final int MAX_BATCH = 50;

	private static final class Pending extends TsgHubOutbox.Item
	{
		final JsonObject message;
		final Set<String> deliveredTo = new HashSet<>();
		long sentAt;

		Pending(JsonObject message, long now)
		{
			super(now);
			this.message = message;
		}
	}

	private final TsgHubSocket socket;
	private final Supplier<TsgHubApi> api;
	private final Consumer<JsonObject> receiver;
	private final TsgHubOutbox<Pending> pending = new TsgHubOutbox<>();
	private final Map<String, Integer> offlineXp = new HashMap<>();

	boolean wantsChat(String message)
	{
		return matches(TsgHubRules.get().chat, message);
	}

	boolean wantsPlayers(String message)
	{
		return matches(TsgHubRules.get().players, message);
	}

	private static boolean matches(List<String> rules, String message)
	{
		for (String rule : rules) if (message.contains(rule)) return true;
		return false;
	}

	static String newId()
	{
		return UUID.randomUUID().toString();
	}

	void send(String type, JsonObject message)
	{
		message.addProperty("type", type);
		if (!message.has("id")) message.addProperty("id", newId());
		long now = System.currentTimeMillis();
		Pending entry = new Pending(message, now);
		synchronized (this)
		{
			pending.add(message.get("id").getAsString(), entry);
			if (socket.sendSignal(message)) entry.sentAt = now;
		}
	}

	void xp(String skill, int xp, int tick)
	{
		if (socket.xp(skill, xp, tick)) return;
		synchronized (this) { offlineXp.merge(skill, xp, Math::max); }
	}

	synchronized void acked(String id)
	{
		pending.remove(id);
	}

	synchronized void resend()
	{
		long now = System.currentTimeMillis();
		for (Pending entry : pending.values()) if (socket.sendSignal(entry.message)) entry.sentAt = now;
	}

	synchronized void clear()
	{
		pending.clear();
		offlineXp.clear();
	}

	void flush(Map<String, String> tokens)
	{
		long now = System.currentTimeMillis();
		List<JsonObject> xp = new ArrayList<>();
		List<Pending> entries = new ArrayList<>();
		synchronized (this)
		{
			pending.expire(now);
			if (socket.isLive())
			{
				offlineXp.clear();
				for (Pending entry : pending.values())
				{
					if (now - entry.sentAt >= RETRY_MILLIS && socket.sendSignal(entry.message)) entry.sentAt = now;
				}
				return;
			}
			if (tokens.isEmpty())
			{
				offlineXp.clear();
				return;
			}
			for (Map.Entry<String, Integer> entry : offlineXp.entrySet())
			{
				JsonObject total = new JsonObject();
				total.addProperty("type", "xp");
				total.addProperty("skill", entry.getKey());
				total.addProperty("xp", entry.getValue());
				xp.add(total);
			}
			offlineXp.clear();
			for (Pending entry : pending.values())
			{
				if (entries.size() + xp.size() >= MAX_BATCH) break;
				entries.add(entry);
			}
		}
		boolean retryXp = false;
		for (Map.Entry<String, String> event : tokens.entrySet())
		{
			List<Pending> undelivered = new ArrayList<>();
			synchronized (this) { for (Pending entry : entries) if (!entry.deliveredTo.contains(event.getKey())) undelivered.add(entry); }
			if (undelivered.isEmpty() && xp.isEmpty()) continue;
			JsonArray signals = new JsonArray();
			xp.forEach(signals::add);
			undelivered.forEach(entry -> signals.add(entry.message));
			JsonObject body = new JsonObject();
			body.add("signals", signals);
			try
			{
				JsonObject result = api.get().request("POST", "/v1/events/" + event.getKey() + "/signals", event.getValue(), body);
				delivered(undelivered, event.getKey());
				for (JsonObject message : TsgHubJson.objects(TsgHubJson.array(result, "messages"))) receiver.accept(message);
			}
			catch (TsgHubApi.HttpError e)
			{
				if (e.status == 401 || e.status == 403 || e.status == 404) delivered(undelivered, event.getKey());
				else retryXp = true;
			}
			catch (Exception e)
			{
				retryXp = true;
				log.debug("TSG Hub signal fallback failed", e);
			}
		}
		synchronized (this)
		{
			for (Pending entry : entries)
			{
				if (entry.deliveredTo.containsAll(tokens.keySet())) pending.remove(entry.message.get("id").getAsString());
			}
			if (retryXp) for (JsonObject total : xp) offlineXp.merge(total.get("skill").getAsString(), total.get("xp").getAsInt(), Math::max);
		}
	}

	private synchronized void delivered(List<Pending> entries, String eventId)
	{
		for (Pending entry : entries) entry.deliveredTo.add(eventId);
	}
}

package com.tsghub;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.Gson;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

@Slf4j
final class TsgHubSocket
{
	enum State { DISCONNECTED, CONNECTING, CONNECTED }

	interface Listener
	{
		void onConnection(State state);

		void onSnapshot(JsonObject message);

		void onReady(String rulesVersion);

		void onRulesChanged(String version);

		void onChanged(String topic, String eventId);

		void onAdminRevoked(String token);

		void onAnnouncement(String text);

		void onUpdateAvailable(String version);

		void onAck(String id);

		void onRejected(String id, int status);

		void onSubscribed();

		void onReply(JsonObject message);

		void onXpRequest(String skills);

		void onScreenshotRequest(String id, String token);

		void onGroupHeartbeat(JsonObject message);

		void onGroupRejected(int status);
	}

	private static final int CLOSE_NORMAL = 1000;
	private static final int CLOSE_GOING_AWAY = 1001;
	private static final long PING_SECONDS = 30;
	private static final long RESTART_MIN_MILLIS = 2_000;
	private static final long RESTART_SPREAD_MILLIS = 8_000;

	@Value
	private static class Subscription
	{
		String token;
		boolean inClanChat;
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final HttpUrl url;
	private final ScheduledExecutorService executor;
	private final Listener listener;
	private final Map<String, Subscription> subscriptions = new HashMap<>();
	private final Map<String, String> rejectedTokens = new HashMap<>();
	private final Set<String> confirmed = new HashSet<>();
	private WebSocket socket;
	private JsonObject presence;
	private String adminToken = "";
	private Set<String> watching = new HashSet<>();
	private ScheduledFuture<?> retry;
	private String clanName = "";
	private String rejectedClan = "";
	private boolean ready;
	private final TsgHubBackoff backoff = new TsgHubBackoff(1_000, 60_000);
	private State state = State.DISCONNECTED;

	TsgHubSocket(OkHttpClient http, Gson gson, String baseUrl, ScheduledExecutorService executor, Listener listener)
	{
		this.gson = gson;
		this.http = http.newBuilder().pingInterval(PING_SECONDS, TimeUnit.SECONDS).build();
		this.url = HttpUrl.get(baseUrl.replaceAll("/+$", "") + "/v1/ws");
		this.executor = executor;
		this.listener = listener;
	}

	synchronized boolean isLive()
	{
		return ready;
	}

	synchronized void connect(String clan)
	{
		if (clan.isEmpty() || clan.equals(rejectedClan)) return;
		if (clan.equals(clanName) && (socket != null || retry != null)) return;
		close();
		clanName = clan;
		backoff.reset();
		open();
	}

	synchronized void disconnect()
	{
		close();
		clanName = "";
		rejectedClan = "";
		subscriptions.clear();
		rejectedTokens.clear();
		confirmed.clear();
		presence = null;
		adminToken = "";
		watching = new HashSet<>();
		changed();
	}

	synchronized void sync(Map<String, String> tokens, boolean inClanChat)
	{
		subscriptions.keySet().removeIf(eventId -> {
			if (tokens.containsKey(eventId)) return false;
			confirmed.remove(eventId);
			send("unsubscribe", eventId, null, false);
			return true;
		});
		for (Map.Entry<String, String> entry : tokens.entrySet())
		{
			Subscription wanted = new Subscription(entry.getValue(), inClanChat);
			if (wanted.equals(subscriptions.get(entry.getKey())) || wanted.token.equals(rejectedTokens.get(entry.getKey()))) continue;
			subscriptions.put(entry.getKey(), wanted);
			confirmed.remove(entry.getKey());
			send("subscribe", entry.getKey(), wanted.token, wanted.inClanChat);
		}
	}

	synchronized boolean presence(JsonObject payload)
	{
		boolean live = ready && socket != null;
		if (payload == null)
		{
			if (live && presence != null) socket.send("{\"type\":\"presence.leave\"}");
			presence = null;
			return live;
		}
		presence = payload;
		if (live) sendPresence();
		return live;
	}

	synchronized boolean send(String type, JsonObject body)
	{
		return emit(type, body.deepCopy());
	}

	synchronized boolean groupHeartbeat(String token, JsonObject body)
	{
		JsonObject message = body.deepCopy();
		message.addProperty("token", token);
		return emit("group.heartbeat", message);
	}

	private boolean emit(String type, JsonObject message)
	{
		if (!ready || socket == null) return false;
		message.addProperty("type", type);
		return socket.send(message.toString());
	}

	synchronized boolean sendSignal(JsonObject message)
	{
		return isLive() && socket.send(message.toString());
	}

	synchronized boolean xp(String skill, int xp, int tick)
	{
		JsonObject message = new JsonObject();
		message.addProperty("skill", skill);
		message.addProperty("xp", xp);
		message.addProperty("tick", tick);
		return emit("xp", message);
	}

	synchronized void rewardInterface(int group, boolean open, int tick)
	{
		JsonObject message = new JsonObject();
		message.addProperty("group", group);
		message.addProperty("open", open);
		message.addProperty("tick", tick);
		emit("interface", message);
	}

	synchronized void watch(Set<String> topics)
	{
		if (topics.equals(watching)) return;
		watching = new HashSet<>(topics);
		if (ready && socket != null) sendWatch();
	}

	private void sendWatch()
	{
		JsonArray topics = new JsonArray();
		watching.forEach(topics::add);
		JsonObject message = new JsonObject();
		message.add("topics", topics);
		message.addProperty("deltas", true);
		message.addProperty("sets", true);
		emit("watch", message);
	}

	synchronized void admin(String token)
	{
		String wanted = token == null ? "" : token;
		if (wanted.equals(adminToken)) return;
		adminToken = wanted;
		if (ready && socket != null && !adminToken.isEmpty()) sendAdmin();
	}

	private void sendAdmin()
	{
		JsonObject message = new JsonObject();
		message.addProperty("token", adminToken);
		emit("admin", message);
	}

	private void sendPresence()
	{
		emit("presence", presence.deepCopy());
	}

	private void open()
	{
		retry = null;
		Request request = new Request.Builder().url(url.newBuilder().addQueryParameter("clanName", clanName).addQueryParameter("version", TsgHubVersion.VERSION).build()).build();
		socket = http.newWebSocket(request, new Handler());
		changed();
	}

	private void close()
	{
		if (retry != null) retry.cancel(false);
		retry = null;
		if (socket != null) socket.close(CLOSE_NORMAL, null);
		socket = null;
		ready = false;
		confirmed.clear();
	}

	private void send(String type, String eventId, String token, boolean inClanChat)
	{
		JsonObject message = new JsonObject();
		message.addProperty("eventId", eventId);
		if (token != null)
		{
			message.addProperty("token", token);
			message.addProperty("inClanChat", inClanChat);
		}
		emit(type, message);
	}

	private synchronized void opened(WebSocket ws, JsonObject message)
	{
		if (ws != socket) return;
		ready = true;
		backoff.reset();
		for (Map.Entry<String, Subscription> entry : subscriptions.entrySet())
		{
			send("subscribe", entry.getKey(), entry.getValue().token, entry.getValue().inClanChat);
		}
		if (presence != null) sendPresence();
		if (!adminToken.isEmpty()) sendAdmin();
		if (!watching.isEmpty()) sendWatch();
		changed();
		String rulesVersion = TsgHubJson.str(message, "rules");
		executor.execute(() -> listener.onReady(rulesVersion));
	}

	private synchronized void rejected(WebSocket ws, String eventId)
	{
		if (ws != socket) return;
		confirmed.remove(eventId);
		Subscription subscription = subscriptions.remove(eventId);
		if (subscription != null) rejectedTokens.put(eventId, subscription.token);
	}

	private synchronized void subscribed(WebSocket ws, String eventId)
	{
		if (ws != socket || !subscriptions.containsKey(eventId)) return;
		confirmed.add(eventId);
		if (listener != null) executor.execute(listener::onSubscribed);
	}

	private synchronized void adminRevoked(WebSocket ws)
	{
		if (ws != socket || adminToken.isEmpty()) return;
		String token = adminToken;
		adminToken = "";
		executor.execute(() -> listener.onAdminRevoked(token));
	}

	private synchronized void dropped(WebSocket ws, int code, int status)
	{
		if (ws != socket) return;
		socket = null;
		ready = false;
		confirmed.clear();
		if (status == 403)
		{
			rejectedClan = clanName;
			clanName = "";
		}
		if (!clanName.isEmpty() && !executor.isShutdown())
		{
			long delay = code == CLOSE_GOING_AWAY ? restartDelay() : backoff.next();
			retry = executor.schedule(this::reopen, delay, TimeUnit.MILLISECONDS);
		}
		changed();
	}

	private void changed()
	{
		State next = ready ? State.CONNECTED : socket != null || retry != null ? State.CONNECTING : State.DISCONNECTED;
		if (next == state) return;
		state = next;
		if (listener != null && !executor.isShutdown()) executor.execute(() -> listener.onConnection(next));
	}

	private synchronized void reopen()
	{
		if (retry == null || clanName.isEmpty()) return;
		open();
	}

	private static long restartDelay()
	{
		return RESTART_MIN_MILLIS + ThreadLocalRandom.current().nextLong(RESTART_SPREAD_MILLIS);
	}

	private final class Handler extends WebSocketListener
	{
		@Override
		public void onMessage(WebSocket ws, String text)
		{
			JsonObject message;
			try
			{
				JsonElement element = gson.fromJson(text, JsonElement.class);
				if (element == null || !element.isJsonObject()) return;
				message = element.getAsJsonObject();
			}
			catch (RuntimeException e) { return; }
			String type = TsgHubJson.str(message, "type");
			String eventId = TsgHubJson.str(message, "eventId");
			switch (type)
			{
				case "ready":
					opened(ws, message);
					break;
				case "changed":
					String topic = TsgHubJson.str(message, "topic");
					dispatch(ws, () -> listener.onChanged(topic, eventId));
					break;
				case "rules":
					String rules = TsgHubJson.str(message, "rules");
					if (!rules.isEmpty()) dispatch(ws, () -> listener.onRulesChanged(rules));
					break;
				case "subscribed":
					subscribed(ws, eventId);
					break;
				case "progress":
				case "claimed":
				case "notice":
					dispatch(ws, () -> listener.onReply(message));
					break;
				case "state":
					dispatch(ws, () -> listener.onSnapshot(message));
					break;
				case "group.heartbeat":
					dispatch(ws, () -> listener.onGroupHeartbeat(message));
					break;
				case "ack":
					String id = TsgHubJson.str(message, "id");
					if (!id.isEmpty()) dispatch(ws, () -> listener.onAck(id));
					break;
				case "xp.request":
					String skills = TsgHubJson.str(message, "skills");
					if (!skills.isEmpty()) dispatch(ws, () -> listener.onXpRequest(skills));
					break;
				case "drop.screenshot":
					String shot = TsgHubJson.str(message, "id");
					String token = TsgHubJson.str(message, "token");
					if (!shot.isEmpty() && !token.isEmpty()) dispatch(ws, () -> listener.onScreenshotRequest(shot, token));
					break;
				case "admin.revoked":
					adminRevoked(ws);
					break;
				case "announcement":
					String announcement = TsgHubJson.str(message, "text");
					if (!announcement.isEmpty()) dispatch(ws, () -> listener.onAnnouncement(announcement));
					break;
				case "update":
					String version = TsgHubJson.str(message, "version");
					if (!version.isEmpty()) dispatch(ws, () -> listener.onUpdateAvailable(version));
					break;
				case "error":
					String failed = TsgHubJson.str(message, "id");
					int status = TsgHubJson.integer(message, "status", 0);
					if (!failed.isEmpty()) dispatch(ws, () -> listener.onRejected(failed, status));
					String errorTopic = TsgHubJson.str(message, "topic");
					if (!eventId.isEmpty()) rejected(ws, eventId);
					else if ("admin".equals(errorTopic) && status == 401) adminRevoked(ws);
					else if ("group".equals(errorTopic)) dispatch(ws, () -> listener.onGroupRejected(status));
					log.debug("TSG Hub socket error: {}", TsgHubJson.str(message, "message"));
					break;
				default:
			}
		}

		@Override
		public void onClosing(WebSocket ws, int code, String reason)
		{
			ws.close(CLOSE_NORMAL, null);
			dropped(ws, code, 0);
		}

		@Override
		public void onClosed(WebSocket ws, int code, String reason)
		{
			dropped(ws, code, 0);
		}

		@Override
		public void onFailure(WebSocket ws, Throwable error, Response response)
		{
			log.debug("TSG Hub socket failed", error);
			dropped(ws, 0, response == null ? 0 : response.code());
		}
	}

	private synchronized void dispatch(WebSocket ws, Runnable action)
	{
		if (ws != socket || executor.isShutdown()) return;
		executor.execute(action);
	}
}

