package com.tsghub;

import java.awt.Container;
import java.awt.Dialog;
import java.awt.Dimension;
import java.awt.Window;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.JDialog;
import javax.swing.SwingUtilities;
import javax.swing.WindowConstants;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;

@RequiredArgsConstructor
final class TsgHubWindows
{
	private final Client client;
	private final Supplier<TsgHubAnnouncements> announcements;
	private volatile JDialog newsDialog;
	private TsgHubNewsWindow newsWindow;

	void openNews(String id)
	{
		SwingUtilities.invokeLater(() -> {
			if (newsDialog == null || !newsDialog.isDisplayable())
			{
				TsgHubAnnouncements news = announcements.get();
				newsWindow = new TsgHubNewsWindow(news.polls());
				newsWindow.setAnnouncements(news.list());
				newsDialog = dialog("TSG Hub · News", newsWindow, new Dimension(TsgHubNewsWindow.TEXT_W + 60, 320), new Dimension(TsgHubNewsWindow.TEXT_W + 60, 640));
			}
			newsWindow.show(id);
			newsDialog.setVisible(true);
			newsDialog.toFront();
		});
	}

	void news(Consumer<TsgHubNewsWindow> action)
	{
		SwingUtilities.invokeLater(() -> { if (newsWindow != null) action.accept(newsWindow); });
	}

	void hideAll()
	{
		SwingUtilities.invokeLater(() -> { if (newsDialog != null) newsDialog.setVisible(false); });
	}

	void dispose()
	{
		JDialog newsWindowDialog = newsDialog;
		newsDialog = null;
		SwingUtilities.invokeLater(() -> {
			if (newsWindowDialog != null) newsWindowDialog.dispose();
			newsWindow = null;
		});
	}

	private JDialog dialog(String title, Container content, Dimension min, Dimension size)
	{
		Window owner = SwingUtilities.getWindowAncestor(client.getCanvas());
		JDialog dialog = new JDialog(owner, title, Dialog.ModalityType.MODELESS);
		dialog.setDefaultCloseOperation(WindowConstants.HIDE_ON_CLOSE);
		dialog.setContentPane(content);
		dialog.setResizable(true);
		dialog.setMinimumSize(min);
		dialog.setSize(size);
		dialog.setLocationRelativeTo(owner);
		return dialog;
	}
}

package com.tsghub;

import static org.junit.Assert.assertEquals;
import net.runelite.api.Skill;
import org.junit.Test;

public class ActivityDetectorTest
{
	@Test
	public void singleDropIsNotSkilling()
	{
		ActivityDetector detector = new ActivityDetector();
		detector.onXp(Skill.MAGIC, 100, 0);
		detector.onXp(Skill.MAGIC, 135, 1_000);
		assertEquals("Idle", detector.activity(null, 2_000));
		detector.onXp(Skill.MAGIC, 170, 200_000);
		assertEquals("Idle", detector.activity(null, 201_000));
	}

	@Test
	public void repeatedDropsAreSkilling()
	{
		ActivityDetector detector = new ActivityDetector();
		detector.onXp(Skill.MINING, 100, 0);
		detector.onXp(Skill.MINING, 135, 1_000);
		detector.onXp(Skill.MINING, 170, 30_000);
		assertEquals("Idle", detector.activity(null, 31_000));
		detector.onXp(Skill.MINING, 205, 60_000);
		assertEquals("Skilling - Mining", detector.activity(null, 61_000));
		detector.onXp(Skill.MAGIC, 100, 62_000);
		detector.onXp(Skill.MAGIC, 135, 63_000);
		assertEquals("Skilling - Mining", detector.activity(null, 64_000));
		detector.onXp(Skill.MINING, 240, 140_000);
		assertEquals("Skilling - Mining", detector.activity(null, 220_000));
		assertEquals("Idle", detector.activity(null, 231_000));
	}
}

package com.tsghub;

import static org.junit.Assert.assertEquals;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
