		assertEquals("Wilderness lvl 40", TsgHubGroups.partyTitle(group("", "Wilderness lvl 40", "Wilderness lvl 40")));
		assertEquals("Wilderness lvl 40-42", TsgHubGroups.partyTitle(group("", "Wilderness lvl 42", "Wilderness lvl 40")));
		assertEquals("Wilderness lvl 40", TsgHubGroups.partyTitle(group("", "Wilderness lvl 40", "Wilderness lvl 40", "Edgeville")));
		assertEquals(2, (int) TsgHubGroups.areaSummary(members("Wilderness lvl 40", "Wilderness lvl 40", "Edgeville")).getValue());
	}

	private static JsonObject group(String title, String... areas)
	{
		JsonObject group = new JsonObject();
		group.addProperty("activity", title);
		group.addProperty("leaderName", "Alice");
		group.add("members", members(areas));
		return group;
	}

	private static JsonArray members(String... areas)
	{
		JsonArray array = new JsonArray();
		for (String area : areas)
		{
			JsonObject member = new JsonObject();
			member.addProperty("area", area);
			array.add(member);
		}
		return array;
	}
}

package com.tsghub;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import org.junit.Test;

public class PresenceDeltaTest
{
	private static JsonArray rows(String json)
	{
		return new Gson().fromJson(json, JsonArray.class);
	}

	private static JsonObject delta(String json)
	{
		return new Gson().fromJson(json, JsonObject.class);
	}

	@Test
	public void upsertsReplaceAndAppendRows()
	{
		JsonArray merged = TsgHubPresence.merge(rows("[{\"displayName\":\"Alice\",\"area\":\"Varrock\"},{\"displayName\":\"Bob\"}]"),
			delta("{\"upsert\":[{\"displayName\":\"alice\",\"area\":\"Lumbridge\"},{\"displayName\":\"Carol\"}],\"remove\":[]}"));
		assertEquals(3, merged.size());
		assertEquals("Lumbridge", TsgHubJson.str(merged.get(0).getAsJsonObject(), "area"));
		assertEquals("Carol", TsgHubJson.str(merged.get(2).getAsJsonObject(), "displayName"));
	}

	@Test
	public void removesDropRowsByName()
	{
		JsonArray merged = TsgHubPresence.merge(rows("[{\"displayName\":\"Alice\"},{\"displayName\":\"Bob\"}]"), delta("{\"upsert\":[],\"remove\":[\"Alice\"]}"));
		assertEquals(1, merged.size());
		assertEquals("Bob", TsgHubJson.str(merged.get(0).getAsJsonObject(), "displayName"));
	}

	@Test
	public void missingSectionKeepsRows()
	{
		JsonArray base = rows("[{\"displayName\":\"Alice\"}]");
		assertSame(base, TsgHubPresence.merge(base, null));
		assertEquals(1, TsgHubPresence.merge(null, delta("{\"upsert\":[{\"displayName\":\"Alice\"}]}")).size());
	}
}

package com.tsghub;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class ReportsTest
{
	private final List<JsonObject> socketSent = new ArrayList<>();
	private final List<JsonObject> posted = new ArrayList<>();
	private final List<String> tokens = new ArrayList<>();
	private final List<String> methods = new ArrayList<>();
	private boolean live = true;
	private int status = 200;
	private long now = 1_000;

	private TsgHubReports reports()
	{
		return new TsgHubReports((type, body) -> {
			if (!live) return false;
			JsonObject message = body.deepCopy();
			message.addProperty("type", type);
			socketSent.add(message);
			return true;
		}, (method, path, token, body) -> {
			methods.add(method);
			posted.add(body.deepCopy());
			tokens.add(token);
			if (status == -1) throw new IOException("offline");
			if (status != 200) throw new TsgHubApi.HttpError(status, "HTTP " + status);
		}, () -> now);
	}

	private static JsonObject drop()
	{
		JsonObject body = new JsonObject();
		body.addProperty("message", "Bob received a drop: Abyssal whip");
		return body;
	}

	@Test
	public void ackRemovesPending()
	{
		TsgHubReports reports = reports();
		assertTrue(reports.send("broadcast", "/v1/broadcasts", drop()));
		String id = socketSent.get(0).get("id").getAsString();
		assertEquals("broadcast", socketSent.get(0).get("type").getAsString());
		reports.acked(id);
		assertEquals(0, reports.size());
		now += TsgHubReports.RETRY_MILLIS;
		reports.flush();
		assertTrue(posted.isEmpty());
	}

	@Test
	public void unackedFallsBackToRestWithSameId()
	{
		TsgHubReports reports = reports();
		reports.send("broadcast", "/v1/broadcasts", drop());
		String id = socketSent.get(0).get("id").getAsString();
		reports.flush();
		assertTrue(posted.isEmpty());

		now += TsgHubReports.RETRY_MILLIS;
		reports.flush();
		assertEquals(1, posted.size());
		assertEquals(id, posted.get(0).get("id").getAsString());
		assertFalse(posted.get(0).has("type"));
		assertEquals(0, reports.size());
	}

	@Test
	public void offlineSocketPostsImmediately()
	{
		live = false;
		TsgHubReports reports = reports();
		assertFalse(reports.send("group", "/v1/group-content", drop()));
		reports.flush();
		assertEquals(1, posted.size());
		assertEquals(0, reports.size());
	}

	@Test
	public void finalErrorDrops()
	{
		TsgHubReports reports = reports();
		reports.send("broadcast", "/v1/broadcasts", drop());
		reports.failed(socketSent.get(0).get("id").getAsString(), 400);
		assertEquals(0, reports.size());

		live = false;
		status = 403;
		reports.send("broadcast", "/v1/broadcasts", drop());
		reports.flush();
		assertEquals(0, reports.size());
	}

	@Test
	public void rateLimitAndServerErrorsRetry()
	{
		TsgHubReports reports = reports();
		reports.send("broadcast", "/v1/broadcasts", drop());
		String id = socketSent.get(0).get("id").getAsString();
		reports.failed(id, 429);
		assertEquals(1, reports.size());

		now += TsgHubReports.RETRY_MILLIS;
		status = 429;
		reports.flush();
		assertEquals(1, reports.size());
		status = 500;
		reports.flush();
		assertEquals(1, posted.size());
		now += TsgHubReports.RETRY_MILLIS;
		reports.flush();
		assertEquals(1, reports.size());
		status = -1;
		now += TsgHubReports.RETRY_MILLIS;
		reports.flush();
		assertEquals(1, reports.size());

		status = 200;
		now += TsgHubReports.RETRY_MILLIS;
		reports.flush();
		assertEquals(0, reports.size());
		assertTrue(posted.stream().allMatch(body -> id.equals(body.get("id").getAsString())));
	}

	@Test
	public void networkFailureStopsFlush()
	{
		live = false;
		status = -1;
		TsgHubReports reports = reports();
		reports.send("broadcast", "/v1/broadcasts", drop());
		reports.send("broadcast", "/v1/broadcasts", drop());
		reports.flush();
		assertEquals(1, posted.size());
		assertEquals(2, reports.size());
	}

	@Test
	public void reconnectResendsOverSocket()
	{
		live = false;
		status = 500;
		TsgHubReports reports = reports();
		reports.send("broadcast", "/v1/broadcasts", drop());
		reports.flush();
		live = true;
		reports.resend();
		assertEquals(1, socketSent.size());
		assertEquals(posted.get(0).get("id"), socketSent.get(0).get("id"));
	}

	@Test
	public void expiresAfterMaxAge()
	{
		live = false;
		status = 500;
		TsgHubReports reports = reports();
		reports.send("broadcast", "/v1/broadcasts", drop());
		now += TsgHubOutbox.MAX_AGE_MILLIS + 1;
		reports.flush();
		assertEquals(0, reports.size());
		assertTrue(posted.isEmpty());
	}

	@Test
	public void capsPending()
	{
		TsgHubReports reports = reports();
		for (int i = 0; i < TsgHubOutbox.MAX_PENDING + 5; i++) reports.send("broadcast", "/v1/broadcasts", drop());
		assertEquals(TsgHubOutbox.MAX_PENDING, reports.size());
		reports.acked(socketSent.get(0).get("id").getAsString());
		assertEquals(TsgHubOutbox.MAX_PENDING, reports.size());
		reports.acked(socketSent.get(socketSent.size() - 1).get("id").getAsString());
		assertEquals(TsgHubOutbox.MAX_PENDING - 1, reports.size());
	}

	@Test
	public void unauthorizedTokenReportFallsBackToRest()
	{
		TsgHubReports reports = reports();
		reports.send("clan-rank", "/v1/events/e1/clan-rank", "member-token", drop());
		reports.failed(socketSent.get(0).get("id").getAsString(), 401);
		assertEquals(1, reports.size());
		reports.flush();
		assertEquals(1, posted.size());
		assertEquals("member-token", tokens.get(0));
		assertEquals(0, reports.size());

		reports.send("broadcast", "/v1/broadcasts", drop());
		reports.failed(socketSent.get(1).get("id").getAsString(), 401);
		assertEquals(0, reports.size());
	}

	@Test
	public void restFallbackUsesReportMethod()
	{
		live = false;
		TsgHubReports reports = reports();
		reports.send("tile.claim", "/v1/events/e1/tasks/t1/claim", "member-token", drop());
		reports.send("tile.unclaim", "DELETE", "/v1/events/e1/tasks/t1/claim", "member-token", drop());
		reports.flush();
		assertEquals(2, posted.size());
		assertEquals("POST", methods.get(0));
		assertEquals("DELETE", methods.get(1));
		assertEquals(0, reports.size());
	}
}

package com.tsghub;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import net.runelite.client.util.Filepath;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.Buffer;
import org.junit.After;
import org.junit.BeforeClass;
import org.junit.Test;

public class SignalsTest
{
	@BeforeClass
	public static void rules()
	{
		TsgHubRules.loadBundled(new Gson());
	}

	private final ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
	private final List<JsonObject> posted = new ArrayList<>();
	private final List<JsonObject> received = new ArrayList<>();
	private final List<String> paths = new ArrayList<>();
	private final Map<String, Integer> eventStatus = new HashMap<>();
	private int status = 200;

	@After
	public void stop()
	{
		executor.shutdownNow();
	}

	private TsgHubSignals signals()
	{
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain -> {
			Buffer body = new Buffer();
			chain.request().body().writeTo(body);
			posted.add(new JsonParser().parse(body.readUtf8()).getAsJsonObject());
			String path = chain.request().url().encodedPath();
			paths.add(path);
			int code = eventStatus.getOrDefault(path, status);
			String reply = "{\"acked\":[],\"messages\":[{\"type\":\"claimed\",\"taskTitle\":\"Hydra\",\"progress\":\"1/3\"}]}";
			return new Response.Builder().request(chain.request()).protocol(Protocol.HTTP_1_1).code(code).message("")
				.body(ResponseBody.create(MediaType.get("application/json"), reply)).build();
		}).build();
		TsgHubSocket socket = new TsgHubSocket(http, new Gson(), "https://hub.test", executor, null);
		TsgHubApi api = new TsgHubApi(http, new Gson(), "https://hub.test");
		return new TsgHubSignals(socket, () -> api, received::add);
	}

	@Test
	public void serverRulesReplaceBundled() throws Exception
	{
		TsgHubSignals signals = signals();
		TsgHubRules bundled = TsgHubRules.get();
		assertEquals("Alchemical Hydra", AreaNames.forRegion(5536).name);
		assertEquals("Vorkath", ActivityDetector.bossFor("Vorkath"));
		assertTrue(bundled.pets.contains(11995));
		assertTrue(bundled.rewardInterfaces.contains(153));
		assertTrue(signals.wantsChat("your vorkath kill count is: 5."));
		assertFalse(signals.wantsChat("you catch a shrimp."));
		assertTrue(signals.wantsPlayers("theatre of blood completion time: 20:00"));

		JsonObject server = new JsonParser().parse("{\"version\":\"abc\",\"chat\":[\"You catch\"],\"areas\":[{\"type\":\"CITIES\",\"name\":\"Lumbridge\",\"regions\":[5536]}]}").getAsJsonObject();
		try
		{
			TsgHubRules.apply(server);
			assertEquals("abc", TsgHubRules.get().version);
			assertTrue(signals.wantsChat("you catch a shrimp."));
			assertEquals("Lumbridge", AreaNames.forRegion(5536).name);
			assertNull(ActivityDetector.bossFor("Vorkath"));
		}
		finally { restoreBundled(); }
	}

	@Test
	public void socketSendFallsBackWhenNotReady()
	{
		TsgHubSocket socket = new TsgHubSocket(new OkHttpClient(), new Gson(), "https://hub.test", executor, null);
		JsonObject body = new JsonObject();
		body.addProperty("message", "Bob received a drop: Abyssal whip");
		assertFalse(socket.send("broadcast", body));
		assertFalse(body.has("type"));
	}

	@Test
	public void cachedRulesSurviveRestart() throws Exception
	{
		Filepath cache = Filepath.Unchecked.getRooted(Files.createTempDirectory("tsghub")).join("rules.json");
		JsonObject server = new JsonParser().parse("{\"version\":\"v2\",\"chat\":[\"you catch\"]}").getAsJsonObject();
		try
		{
			TsgHubRules.save(server, cache);
			restoreBundled();
			assertEquals("", TsgHubRules.get().version);
			TsgHubRules.loadCached(cache, new Gson());
			assertEquals("v2", TsgHubRules.get().version);
			assertTrue(TsgHubRules.get().chat.contains("you catch"));
		}
		finally { restoreBundled(); }
	}

	private static void restoreBundled() throws Exception
	{
		try (InputStreamReader reader = new InputStreamReader(TsgHubRules.class.getResourceAsStream("rules.json"), StandardCharsets.UTF_8))
		{
			TsgHubRules.apply(new JsonParser().parse(reader).getAsJsonObject());
		}
	}

	@Test
	public void fallbackRetriesOnlyEventsThatFailed()
	{
		TsgHubSignals signals = signals();
		signals.send("loot", new JsonObject());
		Map<String, String> tokens = new LinkedHashMap<>();
		tokens.put("e1", "member");
		tokens.put("e2", "member");
		tokens.put("gone", "member");
		eventStatus.put("/v1/events/e2/signals", 500);
		eventStatus.put("/v1/events/gone/signals", 404);
		signals.flush(tokens);
		assertEquals(3, posted.size());

		eventStatus.remove("/v1/events/e2/signals");
		signals.flush(tokens);
		assertEquals(List.of("/v1/events/e1/signals", "/v1/events/e2/signals", "/v1/events/gone/signals", "/v1/events/e2/signals"), paths);

		signals.flush(tokens);
		assertEquals(4, posted.size());
	}

	@Test
	public void cacheFromAnotherPluginVersionIsIgnored() throws Exception
	{
		Filepath cache = Filepath.Unchecked.getRooted(Files.createTempDirectory("tsghub")).join("rules.json");
		cache.write("{\"plugin\":\"0.0.1\",\"rules\":{\"version\":\"old\"}}");
		try
		{
			TsgHubRules.loadCached(cache, new Gson());
			assertEquals("", TsgHubRules.get().version);
			assertTrue(TsgHubRules.get().petMessages.contains("you feel something weird sneaking into your backpack"));
		}
		finally { restoreBundled(); }
	}

	@Test
	public void fallbackPostsPendingAndClearsOnSuccess()
	{
		TsgHubSignals signals = signals();
		JsonObject loot = new JsonObject();
		loot.addProperty("sourceName", "Alchemical Hydra");
		signals.send("loot", loot);
		signals.xp("WOODCUTTING", 1000, 1);
		signals.xp("WOODCUTTING", 1200, 2);

		status = 500;
		signals.flush(Map.of("e1", "member"));
		assertEquals(1, posted.size());
		assertEquals(2, posted.get(0).getAsJsonArray("signals").size());

		status = 200;
		signals.flush(Map.of("e1", "member"));
		assertEquals(2, posted.size());
		JsonObject retried = posted.get(1).getAsJsonArray("signals").get(0).getAsJsonObject();
		assertEquals(1200, retried.get("xp").getAsInt());
		assertEquals(1, received.size());

		signals.flush(Map.of("e1", "member"));
		assertEquals(2, posted.size());
	}
}

package com.tsghub;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.List;
import org.junit.Test;

public class TileClaimsTest
{
	private static JsonObject json(String json)
	{
		return new JsonParser().parse(json).getAsJsonObject();
	}

	private static JsonObject board()
	{
		return json("{\"id\":\"e1\",\"status\":\"active\",\"tileClaims\":["
			+ "{\"taskId\":\"t1\",\"teamId\":\"red\",\"displayName\":\"Bob\",\"note\":\"\",\"claimedAt\":\"2026-10-01T00:00:00Z\"},"
			+ "{\"taskId\":\"t1\",\"teamId\":\"red\",\"displayName\":\"Alice\",\"note\":\"tonight\",\"claimedAt\":\"2026-10-02T00:00:00Z\",\"mine\":true},"
			+ "{\"taskId\":\"t2\",\"teamId\":\"red\",\"displayName\":\"Bob\",\"note\":\"after work\",\"claimedAt\":\"2026-10-03T00:00:00Z\"}]}");
	}

	@Test
	public void forTaskListsOwnClaimFirst()
	{
		List<JsonObject> claims = TsgHubTileClaims.forTask(board(), "t1");
		assertEquals(2, claims.size());
		assertEquals("Alice", TsgHubJson.str(claims.get(0), "displayName"));
		assertEquals("Bob", TsgHubJson.str(claims.get(1), "displayName"));
		assertEquals("tonight", TsgHubJson.str(TsgHubTileClaims.mine(board(), "t1"), "note"));
		assertNull(TsgHubTileClaims.mine(board(), "t2"));
		assertTrue(TsgHubTileClaims.forTask(board(), "t3").isEmpty());
	}

	@Test
	public void olderServersHaveNoClaims()
	{
		JsonObject event = json("{\"id\":\"e1\",\"status\":\"active\"}");
		assertFalse(TsgHubTileClaims.supported(event));
		assertTrue(TsgHubTileClaims.forTask(event, "t1").isEmpty());
		assertFalse(TsgHubTileClaims.claimable(event, "red", new JsonObject()));
	}

	@Test
	public void claimableOnlyOnOpenTilesInLiveEvents()
	{
		JsonObject open = json("{\"completed\":false}");
		assertTrue(TsgHubTileClaims.claimable(board(), "red", open));
		assertFalse(TsgHubTileClaims.claimable(board(), "", open));
		assertFalse(TsgHubTileClaims.claimable(board(), "red", json("{\"completed\":true}")));
		JsonObject scheduled = board();
		scheduled.addProperty("status", "scheduled");
		assertTrue(TsgHubTileClaims.claimable(scheduled, "red", open));
		JsonObject ended = board();
		ended.addProperty("status", "ended");
		assertFalse(TsgHubTileClaims.claimable(ended, "red", open));
	}

	@Test
	public void cleanNoteTrimsAndLimits()
	{
		assertEquals("", TsgHubTileClaims.cleanNote(null));
		assertEquals("on it", TsgHubTileClaims.cleanNote("  on it \n"));
		String longest = new String(new char[TsgHubTileClaims.MAX_NOTE_LENGTH]).replace('\0', 'a');
		assertEquals(longest, TsgHubTileClaims.cleanNote(longest));
		assertNull(TsgHubTileClaims.cleanNote(longest + "a"));
	}

	@Test
	public void bodyAndPath()
	{
		assertEquals("/v1/events/e1/tasks/t1/claim", TsgHubTileClaims.path("e1", "t1"));
		JsonObject claim = TsgHubTileClaims.body("e1", "t1", "tonight");
		assertEquals("e1", TsgHubJson.str(claim, "eventId"));
		assertEquals("t1", TsgHubJson.str(claim, "taskId"));
		assertEquals("tonight", TsgHubJson.str(claim, "note"));
		assertFalse(TsgHubTileClaims.body("e1", "t1", null).has("note"));
	}

	@Test
	public void withClaimUpdatesOnlyOwnClaim()
	{
		JsonObject original = board();
		JsonObject changed = TsgHubTileClaims.withClaim(original, "t1", "red", "Alice", "now");
		assertEquals("tonight", TsgHubJson.str(TsgHubTileClaims.mine(original, "t1"), "note"));
		JsonObject mine = TsgHubTileClaims.mine(changed, "t1");
		assertEquals("now", TsgHubJson.str(mine, "note"));
		assertEquals("2026-10-02T00:00:00Z", TsgHubJson.str(mine, "claimedAt"));
		assertEquals(2, TsgHubTileClaims.forTask(changed, "t1").size());

		JsonObject claimed = TsgHubTileClaims.withClaim(original, "t2", "red", "Alice", "");
		assertEquals(2, TsgHubTileClaims.forTask(claimed, "t2").size());
		assertEquals("Alice", TsgHubJson.str(TsgHubTileClaims.mine(claimed, "t2"), "displayName"));

		JsonObject dropped = TsgHubTileClaims.withClaim(original, "t1", "red", "Alice", null);
		assertNull(TsgHubTileClaims.mine(dropped, "t1"));
		assertEquals(1, TsgHubTileClaims.forTask(dropped, "t1").size());
		assertEquals(1, TsgHubTileClaims.forTask(dropped, "t2").size());
	}
}

